"use client";
import * as PopoverPrimitive from "@radix-ui/react-popover";
import { useControllableState } from "@ux-sting/hooks";
import { CheckIcon, ChevronsUpDownIcon } from "@ux-sting/icons";
import { cn } from "@ux-sting/utils";
import { forwardRef, useState, type ReactNode } from "react";
import { controlVariants, type ControlSize } from "../../lib/control.js";
import { useFieldControlProps } from "../../lib/field.js";
import { floatingSurfaceClass } from "../../lib/overlay.js";
import { useMessages, usePortalContainer } from "../../provider/context.js";
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
  CommandLoading,
} from "../command/command.js";
import { groupOptions, type ComboboxOption } from "./combobox.types.js";

export interface ComboboxProps {
  options: ComboboxOption[];
  value?: string | null;
  defaultValue?: string | null;
  onValueChange?: (value: string | null) => void;
  placeholder?: string;
  searchPlaceholder?: string;
  emptyText?: ReactNode;
  size?: ControlSize;
  disabled?: boolean;
  invalid?: boolean;
  /** Allow clearing the value by selecting the current option again. */
  clearable?: boolean;
  /** Async search: receives the query; set `loading` and update `options`. */
  onSearchChange?: (search: string) => void;
  loading?: boolean;
  /** Name for a hidden input so the value is submitted with forms. */
  name?: string;
  id?: string;
  className?: string;
  "aria-label"?: string;
  "aria-labelledby"?: string;
  renderOption?: (option: ComboboxOption) => ReactNode;
}

/**
 * Searchable single-select for long lists (countries, categories, users).
 * Supports grouping, async results and form submission.
 */
export const Combobox = forwardRef<HTMLButtonElement, ComboboxProps>(function Combobox(
  {
    options,
    value: valueProp,
    defaultValue = null,
    onValueChange,
    placeholder = "Select…",
    searchPlaceholder,
    emptyText,
    size,
    disabled,
    invalid,
    clearable,
    onSearchChange,
    loading,
    name,
    id,
    className,
    renderOption,
    ...aria
  },
  ref,
) {
  const [open, setOpen] = useState(false);
  const [value, setValue] = useControllableState({
    value: valueProp,
    defaultValue,
    onChange: onValueChange,
  });
  const container = usePortalContainer();
  const messages = useMessages();
  const fieldProps = useFieldControlProps({
    id,
    disabled,
    "aria-invalid": invalid || undefined,
    ...aria,
  });
  const selected = options.find((o) => o.value === value);

  return (
    <PopoverPrimitive.Root open={open} onOpenChange={setOpen}>
      <PopoverPrimitive.Trigger asChild>
        <button
          ref={ref}
          type="button"
          role="combobox"
          aria-expanded={open}
          aria-haspopup="listbox"
          id={fieldProps.id}
          disabled={fieldProps.disabled}
          aria-invalid={fieldProps["aria-invalid"]}
          aria-describedby={fieldProps["aria-describedby"]}
          aria-label={aria["aria-label"]}
          aria-labelledby={aria["aria-labelledby"]}
          className={cn(
            controlVariants({ size }),
            "flex items-center justify-between gap-2 text-start",
            className,
          )}
        >
          <span
            className={cn(
              "flex min-w-0 items-center gap-2 truncate",
              !selected && "text-muted-foreground",
            )}
          >
            {selected?.icon}
            {selected?.label ?? placeholder}
          </span>
          <ChevronsUpDownIcon className="size-4 shrink-0 text-muted-foreground" />
        </button>
      </PopoverPrimitive.Trigger>
      {name ? <input type="hidden" name={name} value={value ?? ""} /> : null}
      <PopoverPrimitive.Portal container={container}>
        <PopoverPrimitive.Content
          align="start"
          sideOffset={6}
          collisionPadding={8}
          className={cn(
            floatingSurfaceClass,
            "w-(--radix-popover-trigger-width) min-w-56 overflow-hidden p-0",
          )}
        >
          <Command
            shouldFilter={!onSearchChange}
            onSearchChange={onSearchChange}
            loading={loading}
            label={aria["aria-label"]}
          >
            <CommandInput placeholder={searchPlaceholder ?? messages.search} />
            <CommandList>
              <CommandLoading />
              <CommandEmpty>{emptyText}</CommandEmpty>
              {groupOptions(options).map(([group, items]) => (
                <CommandGroup key={group ?? "_"} heading={group}>
                  {items.map((option) => (
                    <CommandItem
                      key={option.value}
                      value={option.label}
                      keywords={[option.value, ...(option.keywords ?? [])]}
                      disabled={option.disabled}
                      selected={option.value === value}
                      icon={option.icon}
                      onSelect={() => {
                        setValue(clearable && option.value === value ? null : option.value);
                        setOpen(false);
                      }}
                    >
                      {renderOption ? (
                        renderOption(option)
                      ) : (
                        <span className="grid">
                          <span className="truncate">{option.label}</span>
                          {option.description ? (
                            <span className="truncate text-xs text-muted-foreground">
                              {option.description}
                            </span>
                          ) : null}
                        </span>
                      )}
                      <CheckIcon
                        className={cn(
                          "ms-auto text-primary!",
                          option.value === value ? "opacity-100" : "opacity-0",
                        )}
                      />
                    </CommandItem>
                  ))}
                </CommandGroup>
              ))}
            </CommandList>
          </Command>
        </PopoverPrimitive.Content>
      </PopoverPrimitive.Portal>
    </PopoverPrimitive.Root>
  );
});

import type { ReactNode } from "react";

export interface ComboboxOption {
  value: string;
  label: string;
  description?: string;
  icon?: ReactNode;
  disabled?: boolean;
  /** Group heading this option belongs to. */
  group?: string;
  keywords?: string[];
}

export function groupOptions(
  options: ComboboxOption[],
): Array<[string | undefined, ComboboxOption[]]> {
  const map = new Map<string | undefined, ComboboxOption[]>();
  for (const option of options) {
    const list = map.get(option.group) ?? [];
    list.push(option);
    map.set(option.group, list);
  }
  return Array.from(map.entries());
}

"use client";
import * as PopoverPrimitive from "@radix-ui/react-popover";
import { useControllableState } from "@ux-sting/hooks";
import { CheckIcon, ChevronsUpDownIcon, XIcon } from "@ux-sting/icons";
import { cn } from "@ux-sting/utils";
import { forwardRef, useState, type ReactNode } from "react";
import { useFieldControlProps } from "../../lib/field.js";
import { floatingSurfaceClass } from "../../lib/overlay.js";
import { useMessages, usePortalContainer } from "../../provider/context.js";
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "../command/command.js";
import { groupOptions, type ComboboxOption } from "../combobox/combobox.types.js";

export interface MultiSelectProps {
  options: ComboboxOption[];
  value?: string[];
  defaultValue?: string[];
  onValueChange?: (value: string[]) => void;
  placeholder?: string;
  searchPlaceholder?: string;
  emptyText?: ReactNode;
  /** Maximum chips shown in the trigger before a `+n` summary. */
  maxVisible?: number;
  /** Maximum number of selections. */
  maxSelected?: number;
  disabled?: boolean;
  invalid?: boolean;
  name?: string;
  id?: string;
  className?: string;
  "aria-label"?: string;
  "aria-labelledby"?: string;
}

/** Searchable multiple selection with removable chips. */
export const MultiSelect = forwardRef<HTMLDivElement, MultiSelectProps>(function MultiSelect(
  {
    options,
    value: valueProp,
    defaultValue = [],
    onValueChange,
    placeholder = "Select…",
    searchPlaceholder,
    emptyText,
    maxVisible = 3,
    maxSelected,
    disabled,
    invalid,
    name,
    id,
    className,
    ...aria
  },
  ref,
) {
  const [open, setOpen] = useState(false);
  const [value, setValue] = useControllableState({
    value: valueProp,
    defaultValue,
    onChange: onValueChange,
  });
  const container = usePortalContainer();
  const messages = useMessages();
  const fieldProps = useFieldControlProps({ id, disabled, "aria-invalid": invalid || undefined });
  const selected = value
    .map((v) => options.find((o) => o.value === v))
    .filter((o): o is ComboboxOption => Boolean(o));
  const visible = selected.slice(0, maxVisible);
  const hidden = selected.length - visible.length;
  const toggle = (v: string) =>
    setValue((prev) =>
      prev.includes(v)
        ? prev.filter((x) => x !== v)
        : maxSelected && prev.length >= maxSelected
          ? prev
          : [...prev, v],
    );

  return (
    <PopoverPrimitive.Root open={open} onOpenChange={setOpen}>
      <div
        ref={ref}
        className={cn(
          "flex min-h-(--ui-height-md) w-full items-center gap-1 rounded-md border border-input bg-background px-1.5 py-1 shadow-xs transition-[border-color,box-shadow]",
          "focus-within:border-ring focus-within:ring-3 focus-within:ring-ring/30 has-[[aria-invalid=true]]:border-destructive",
          fieldProps.disabled && "opacity-60",
          className,
        )}
      >
        <div className="flex min-w-0 flex-1 flex-wrap items-center gap-1">
          {visible.map((option) => (
            <span
              key={option.value}
              className="inline-flex h-6 max-w-full items-center gap-1 rounded-sm bg-secondary ps-2 pe-1 text-xs font-medium text-secondary-foreground"
            >
              <span className="truncate">{option.label}</span>
              <button
                type="button"
                disabled={fieldProps.disabled}
                aria-label={messages.removeItem(option.label)}
                onClick={() => toggle(option.value)}
                className="ui-hit-area inline-flex size-4 items-center justify-center rounded-xs outline-none hover:bg-secondary-hover focus-visible:ring-2 focus-visible:ring-ring [&_svg]:size-3"
              >
                <XIcon />
              </button>
            </span>
          ))}
          {hidden > 0 ? (
            <span className="px-1 text-xs text-muted-foreground">+{hidden}</span>
          ) : null}
          <PopoverPrimitive.Trigger asChild>
            <button
              type="button"
              role="combobox"
              aria-expanded={open}
              aria-haspopup="listbox"
              id={fieldProps.id}
              disabled={fieldProps.disabled}
              aria-invalid={fieldProps["aria-invalid"]}
              aria-describedby={fieldProps["aria-describedby"]}
              aria-label={aria["aria-label"]}
              aria-labelledby={aria["aria-labelledby"]}
              // ux-audit-ignore: the wrapper shows a focus-within ring
              className="flex h-6 min-w-16 flex-1 items-center justify-between gap-2 rounded-sm px-1.5 text-start text-sm text-muted-foreground outline-none"
            >
              <span className="truncate">
                {selected.length ? messages.selected(selected.length) : placeholder}
              </span>
              <ChevronsUpDownIcon className="size-4 shrink-0" />
            </button>
          </PopoverPrimitive.Trigger>
        </div>
      </div>
      {name ? value.map((v) => <input key={v} type="hidden" name={name} value={v} />) : null}
      <PopoverPrimitive.Portal container={container}>
        <PopoverPrimitive.Content
          align="start"
          sideOffset={6}
          collisionPadding={8}
          className={cn(
            floatingSurfaceClass,
            "w-(--radix-popover-trigger-width) min-w-64 overflow-hidden p-0",
          )}
        >
          <Command label={aria["aria-label"]}>
            <CommandInput placeholder={searchPlaceholder ?? messages.search} />
            <CommandList aria-multiselectable>
              <CommandEmpty>{emptyText}</CommandEmpty>
              {groupOptions(options).map(([group, items]) => (
                <CommandGroup key={group ?? "_"} heading={group}>
                  {items.map((option) => {
                    const isSelected = value.includes(option.value);
                    return (
                      <CommandItem
                        key={option.value}
                        value={option.label}
                        keywords={[option.value]}
                        disabled={
                          option.disabled ||
                          (!isSelected &&
                            Boolean(maxSelected) &&
                            value.length >= (maxSelected ?? 0))
                        }
                        selected={isSelected}
                        onSelect={() => toggle(option.value)}
                      >
                        <span
                          aria-hidden
                          className={cn(
                            "flex size-4 items-center justify-center rounded-xs border border-input",
                            isSelected &&
                              "border-primary bg-primary text-primary-foreground [&_svg]:text-primary-foreground!",
                          )}
                        >
                          {isSelected ? <CheckIcon className="size-3!" /> : null}
                        </span>
                        {option.icon}
                        <span className="truncate">{option.label}</span>
                      </CommandItem>
                    );
                  })}
                </CommandGroup>
              ))}
            </CommandList>
          </Command>
        </PopoverPrimitive.Content>
      </PopoverPrimitive.Portal>
    </PopoverPrimitive.Root>
  );
});

"use client";
import * as PopoverPrimitive from "@radix-ui/react-popover";
import { useControllableState } from "@ux-sting/hooks";
import { cn, fuzzyScore } from "@ux-sting/utils";
import { forwardRef, useId, useMemo, useState, type KeyboardEvent, type ReactNode } from "react";
import { menuItemClass } from "../../lib/menu-styles.js";
import { floatingSurfaceClass } from "../../lib/overlay.js";
import { useMessages, usePortalContainer } from "../../provider/context.js";
import { Input, type InputProps } from "../input/input.js";
import { Spinner } from "../spinner/spinner.js";

export interface AutocompleteProps extends Omit<
  InputProps,
  "value" | "defaultValue" | "onChange" | "onSelect"
> {
  /** Suggestions. Filtered locally unless `onSearchChange` handles it. */
  suggestions: string[];
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /** Called when a suggestion is chosen. */
  onSelect?: (value: string) => void;
  /** Disable local filtering (async/server suggestions). */
  filterLocally?: boolean;
  loading?: boolean;
  emptyText?: ReactNode;
  /** Maximum suggestions to render. */
  limit?: number;
}

/**
 * Free-text input with suggestions (the value need not be one of them).
 * Implements the ARIA combobox pattern with `aria-activedescendant`.
 */
export const Autocomplete = forwardRef<HTMLInputElement, AutocompleteProps>(function Autocomplete(
  {
    suggestions,
    value: valueProp,
    defaultValue = "",
    onValueChange,
    onSelect,
    filterLocally = true,
    loading,
    emptyText,
    limit = 8,
    className,
    onKeyDown,
    ...props
  },
  ref,
) {
  const [value, setValue] = useControllableState({
    value: valueProp,
    defaultValue,
    onChange: onValueChange,
  });
  const [open, setOpen] = useState(false);
  const [active, setActive] = useState(0);
  const listId = `ac${useId().replace(/:/g, "")}`;
  const container = usePortalContainer();
  const messages = useMessages();

  const results = useMemo(() => {
    if (!filterLocally || !value) return suggestions.slice(0, limit);
    return suggestions
      .map((s) => [s, fuzzyScore(value, s)] as const)
      .filter(([, score]) => score > 0)
      .sort((a, b) => b[1] - a[1])
      .slice(0, limit)
      .map(([s]) => s);
  }, [suggestions, value, filterLocally, limit]);

  const choose = (s: string) => {
    setValue(s);
    onSelect?.(s);
    setOpen(false);
  };

  const handleKeyDown = (e: KeyboardEvent<HTMLInputElement>) => {
    onKeyDown?.(e);
    if (e.key === "ArrowDown") {
      e.preventDefault();
      if (!open) setOpen(true);
      else setActive((i) => (i + 1) % Math.max(results.length, 1));
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      setActive((i) => (i - 1 + results.length) % Math.max(results.length, 1));
    } else if (e.key === "Enter" && open && results[active]) {
      e.preventDefault();
      choose(results[active]);
    } else if (e.key === "Escape" && open) {
      e.preventDefault();
      setOpen(false);
    }
  };

  const showPanel = open && (results.length > 0 || loading || Boolean(value && emptyText));

  return (
    <PopoverPrimitive.Root open={showPanel} onOpenChange={setOpen}>
      <PopoverPrimitive.Anchor asChild>
        <div className={cn("relative w-full", className)}>
          <Input
            ref={ref}
            role="combobox"
            aria-autocomplete="list"
            aria-expanded={showPanel}
            aria-controls={listId}
            aria-activedescendant={showPanel && results[active] ? `${listId}-${active}` : undefined}
            autoComplete="off"
            value={value}
            onChange={(e) => {
              setValue(e.target.value);
              setActive(0);
              setOpen(true);
            }}
            onFocus={() => setOpen(true)}
            onKeyDown={handleKeyDown}
            {...props}
          />
          {loading ? (
            <Spinner
              size="sm"
              label={null}
              className="absolute end-3 top-1/2 -translate-y-1/2 text-muted-foreground"
            />
          ) : null}
        </div>
      </PopoverPrimitive.Anchor>
      <PopoverPrimitive.Portal container={container}>
        <PopoverPrimitive.Content
          align="start"
          sideOffset={6}
          onOpenAutoFocus={(e) => e.preventDefault()}
          onInteractOutside={(e) => {
            if ((e.target as HTMLElement).closest?.(`[aria-controls="${listId}"]`))
              e.preventDefault();
          }}
          className={cn(floatingSurfaceClass, "w-(--radix-popover-trigger-width) p-1")}
        >
          <div id={listId} role="listbox" aria-busy={loading || undefined}>
            {results.map((s, i) => (
              <div
                key={s}
                id={`${listId}-${i}`}
                role="option"
                tabIndex={-1}
                aria-selected={i === active}
                data-highlighted={i === active ? "" : undefined}
                onPointerMove={() => setActive(i)}
                onPointerDown={(e) => e.preventDefault()}
                onClick={() => choose(s)}
                className={cn(menuItemClass, "cursor-pointer")}
              >
                {s}
              </div>
            ))}
            {!loading && results.length === 0 && emptyText ? (
              <div role="status" className="px-2 py-3 text-sm text-muted-foreground">
                {emptyText ?? messages.noResults}
              </div>
            ) : null}
          </div>
        </PopoverPrimitive.Content>
      </PopoverPrimitive.Portal>
    </PopoverPrimitive.Root>
  );
});

"use client";
import * as SliderPrimitive from "@radix-ui/react-slider";
import { cn } from "@ux-sting/utils";
import { forwardRef, type ComponentPropsWithoutRef } from "react";
import { useLocale } from "../../provider/context.js";

export interface SliderProps extends ComponentPropsWithoutRef<typeof SliderPrimitive.Root> {
  /** Accessible names for each thumb, e.g. `["Minimum price", "Maximum price"]`. */
  thumbLabels?: string[];
  /** Formats the value for `aria-valuetext` and the optional visible output. */
