      {...props}
    />
  );
});

"use client";
import { useControllableState } from "@ux-sting/hooks";
import { cn } from "@ux-sting/utils";
import { forwardRef, useRef, type ClipboardEvent, type KeyboardEvent } from "react";
import { useFieldControlProps } from "../../lib/field.js";

export interface OTPInputProps {
  length?: number;
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /** Called once all digits are filled. */
  onComplete?: (value: string) => void;
  /** `numeric` (default) or `alphanumeric`. */
  type?: "numeric" | "alphanumeric";
  /** Mask the characters (e.g. PINs). */
  mask?: boolean;
  disabled?: boolean;
  invalid?: boolean;
  name?: string;
  id?: string;
  className?: string;
  /** Accessible name for the group, e.g. "Verification code". */
  "aria-label"?: string;
  /** Insert a visual separator after this index (e.g. 3 for 123-456). */
  groupAfter?: number;
}

/**
 * One-time code entry. Supports paste of the full code, SMS autofill
 * (`autocomplete="one-time-code"`), arrow keys and Backspace navigation.
 */
export const OTPInput = forwardRef<HTMLDivElement, OTPInputProps>(function OTPInput(
  {
    length = 6,
    value: valueProp,
    defaultValue = "",
    onValueChange,
    onComplete,
    type = "numeric",
    mask,
    disabled,
    invalid,
    name,
    id,
    className,
    groupAfter,
    ...aria
  },
  ref,
) {
  const [value, setValue] = useControllableState({
    value: valueProp,
    defaultValue,
    onChange: onValueChange,
  });
  const inputs = useRef<Array<HTMLInputElement | null>>([]);
  const fieldProps = useFieldControlProps({ id, disabled, "aria-invalid": invalid || undefined });
  const pattern = type === "numeric" ? /[0-9]/ : /[0-9a-z]/i;

  const update = (next: string) => {
    const clean = next.slice(0, length);
    setValue(clean);
    if (clean.length === length) onComplete?.(clean);
  };

  const setChar = (index: number, char: string) => {
    const chars = value.padEnd(length, " ").split("");
    chars[index] = char;
    update(chars.join("").replace(/\s+$/, ""));
  };

  const focusAt = (i: number) => inputs.current[Math.max(0, Math.min(length - 1, i))]?.focus();

  const onKeyDown = (i: number) => (e: KeyboardEvent<HTMLInputElement>) => {
    if (e.key === "Backspace") {
      e.preventDefault();
      if (value[i] && value[i] !== " ") setChar(i, " ");
      else {
        setChar(Math.max(0, i - 1), " ");
        focusAt(i - 1);
      }
    } else if (e.key === "ArrowLeft") {
      e.preventDefault();
      focusAt(i - 1);
    } else if (e.key === "ArrowRight") {
      e.preventDefault();
      focusAt(i + 1);
    }
  };

  const onPaste = (e: ClipboardEvent<HTMLInputElement>) => {
    e.preventDefault();
    const pasted = e.clipboardData
      .getData("text")
      .split("")
      .filter((c) => pattern.test(c))
      .join("");
    if (!pasted) return;
    update(pasted);
    focusAt(pasted.length);
  };

  return (
    <div
      ref={ref}
      role="group"
      aria-label={aria["aria-label"]}
      className={cn("flex items-center gap-2", className)}
      dir="ltr"
    >
      {Array.from({ length }, (_, i) => (
        <span key={i} className="contents">
          <input
            ref={(el) => {
              inputs.current[i] = el;
            }}
            id={i === 0 ? fieldProps.id : undefined}
            type={mask ? "password" : "text"}
            inputMode={type === "numeric" ? "numeric" : "text"}
            autoComplete={i === 0 ? "one-time-code" : "off"}
            maxLength={length}
            disabled={fieldProps.disabled}
            aria-invalid={fieldProps["aria-invalid"]}
            aria-describedby={i === 0 ? fieldProps["aria-describedby"] : undefined}
            aria-label={`${aria["aria-label"] ?? "Code"} ${i + 1}/${length}`}
            value={value[i]?.trim() ?? ""}
            onFocus={(e) => e.currentTarget.select()}
            onChange={(e) => {
              const chars = e.target.value.split("").filter((c) => pattern.test(c));
              if (chars.length > 1) {
                update(chars.join(""));
                focusAt(chars.length);
                return;
              }
              const char = chars[0];
              if (!char) return;
              setChar(i, type === "numeric" ? char : char.toUpperCase());
              focusAt(i + 1);
            }}
            onKeyDown={onKeyDown(i)}
            onPaste={onPaste}
            className={cn(
              "size-11 rounded-md border border-input bg-background text-center text-lg font-semibold tabular-nums shadow-xs outline-none transition-[border-color,box-shadow]",
              "focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/30 aria-invalid:border-destructive disabled:opacity-50",
            )}
          />
          {groupAfter && i === groupAfter - 1 ? (
            <span aria-hidden className="text-muted-foreground">
              –
            </span>
          ) : null}
        </span>
      ))}
      {name ? <input type="hidden" name={name} value={value} /> : null}
    </div>
  );
});

"use client";
import { useControllableState } from "@ux-sting/hooks";
import { FileIcon, UploadCloudIcon, XIcon } from "@ux-sting/icons";
import { cn, formatFileSize } from "@ux-sting/utils";
import { forwardRef, useId, useRef, useState, type DragEvent, type ReactNode } from "react";
import { useFieldControlProps } from "../../lib/field.js";
import { useLocale, useMessages } from "../../provider/context.js";
import { Progress } from "../progress/progress.js";

export interface FileRejection {
  file: File;
  reason: "type" | "size" | "count";
}

export interface DropzoneProps {
  /** Accepted types, e.g. `"image/*,.pdf"`. */
  accept?: string;
  multiple?: boolean;
  /** Max size per file in bytes. */
  maxSize?: number;
  maxFiles?: number;
  disabled?: boolean;
  invalid?: boolean;
  onFilesAccepted?: (files: File[]) => void;
  onFilesRejected?: (rejections: FileRejection[]) => void;
  /** Main prompt text. */
  label?: ReactNode;
  /** Hint text: types and limits. */
  description?: ReactNode;
  name?: string;
  id?: string;
  className?: string;
  children?: ReactNode;
}

function matchesAccept(file: File, accept?: string) {
  if (!accept) return true;
  return accept.split(",").some((rule) => {
    const r = rule.trim().toLowerCase();
    if (r.startsWith(".")) return file.name.toLowerCase().endsWith(r);
    if (r.endsWith("/*")) return file.type.toLowerCase().startsWith(r.slice(0, -1));
    return file.type.toLowerCase() === r;
  });
}

export function validateFiles(
  files: File[],
  { accept, maxSize, maxFiles }: Pick<DropzoneProps, "accept" | "maxSize" | "maxFiles">,
) {
  const accepted: File[] = [];
  const rejected: FileRejection[] = [];
  for (const file of files) {
    if (!matchesAccept(file, accept)) rejected.push({ file, reason: "type" });
    else if (maxSize && file.size > maxSize) rejected.push({ file, reason: "size" });
    else if (maxFiles && accepted.length >= maxFiles) rejected.push({ file, reason: "count" });
    else accepted.push(file);
  }
  return { accepted, rejected };
}

/**
 * Drag-and-drop area that is also a regular button/file input, so it works
 * with keyboard, screen readers and touch (drag is never required).
 */
export const Dropzone = forwardRef<HTMLDivElement, DropzoneProps>(function Dropzone(
  {
    accept,
    multiple = true,
    maxSize,
    maxFiles,
    disabled,
    invalid,
    onFilesAccepted,
    onFilesRejected,
    label,
    description,
    name,
    id,
    className,
    children,
  },
  ref,
) {
  const inputRef = useRef<HTMLInputElement>(null);
  const [dragging, setDragging] = useState(false);
  const messages = useMessages();
  const fieldProps = useFieldControlProps({ id, disabled, "aria-invalid": invalid || undefined });
  const descId = useId();

  const handle = (list: FileList | null) => {
    if (!list || disabled) return;
    const { accepted, rejected } = validateFiles(Array.from(list), {
      accept,
      maxSize,
      maxFiles: multiple ? maxFiles : 1,
    });
    if (accepted.length) onFilesAccepted?.(accepted);
    if (rejected.length) onFilesRejected?.(rejected);
  };

  const onDrop = (e: DragEvent) => {
    e.preventDefault();
    setDragging(false);
    handle(e.dataTransfer.files);
  };

  return (
    <div
      ref={ref}
      data-dragging={dragging ? "" : undefined}
      data-disabled={disabled ? "" : undefined}
      onDragOver={(e) => {
        e.preventDefault();
        if (!disabled) setDragging(true);
      }}
      onDragLeave={() => setDragging(false)}
      onDrop={onDrop}
      className={cn(
        "relative flex flex-col items-center justify-center gap-2 rounded-lg border-2 border-dashed border-input bg-surface px-6 py-8 text-center transition-colors",
        "focus-within:border-ring focus-within:ring-3 focus-within:ring-ring/30 data-dragging:border-primary data-dragging:bg-primary-subtle",
        "data-disabled:cursor-not-allowed data-disabled:opacity-60 has-[[aria-invalid=true]]:border-destructive",
        className,
      )}
    >
      {children ?? (
        <>
          <span className="flex size-10 items-center justify-center rounded-full bg-background text-muted-foreground shadow-xs [&_svg]:size-5">
            <UploadCloudIcon />
          </span>
          <p className="text-sm font-medium">{label ?? messages.dropFiles}</p>
          {description ? (
            <p id={descId} className="text-xs text-muted-foreground">
              {description}
            </p>
          ) : null}
        </>
      )}
      <button
        type="button"
        disabled={fieldProps.disabled}
        onClick={() => inputRef.current?.click()}
        aria-describedby={
          cn(fieldProps["aria-describedby"], description ? descId : undefined) || undefined
        }
        className="mt-1 rounded-md text-sm font-medium text-primary underline-offset-4 outline-none hover:underline focus-visible:ring-2 focus-visible:ring-ring after:absolute after:inset-0"
        id={fieldProps.id}
      >
        {messages.browseFiles}
      </button>
      <input
        ref={inputRef}
        type="file"
        name={name}
        accept={accept}
        multiple={multiple}
        disabled={disabled}
        tabIndex={-1}
        aria-hidden
        aria-invalid={fieldProps["aria-invalid"]}
        className="sr-only"
        onChange={(e) => {
          handle(e.target.files);
          e.target.value = "";
        }}
      />
    </div>
  );
});

export interface UploadItem {
  id: string;
  file: File;
  /** 0–100; omit when not uploading. */
  progress?: number;
  status?: "pending" | "uploading" | "done" | "error";
  error?: string;
}

export interface FileUploadProps extends Omit<DropzoneProps, "onFilesAccepted"> {
  value?: UploadItem[];
  defaultValue?: UploadItem[];
  onValueChange?: (items: UploadItem[]) => void;
  /** Called with newly added items (start uploads here). */
  onAdd?: (items: UploadItem[]) => void;
}

let uploadCounter = 0;

/** Dropzone plus a managed file list with progress, errors and removal. */
export const FileUpload = forwardRef<HTMLDivElement, FileUploadProps>(function FileUpload(
  { value: valueProp, defaultValue = [], onValueChange, onAdd, className, ...props },
  ref,
) {
  const [items, setItems] = useControllableState({
    value: valueProp,
    defaultValue,
    onChange: onValueChange,
  });
  const { locale } = useLocale();
  const messages = useMessages();
  return (
    <div ref={ref} className={cn("grid grid-cols-[minmax(0,1fr)] gap-3", className)}>
      <Dropzone
        {...props}
        onFilesAccepted={(files) => {
          const added = files.map((file) => ({
            id: `upload-${++uploadCounter}`,
            file,
            status: "pending" as const,
          }));
          setItems([...(props.multiple === false ? [] : items), ...added]);
          onAdd?.(added);
        }}
      />
      {items.length ? (
        <ul className="grid gap-2" aria-live="polite">
          {items.map((item) => (
            <li
              key={item.id}
              className="flex items-center gap-3 rounded-lg border border-border bg-card p-3"
            >
              <span className="flex size-9 shrink-0 items-center justify-center rounded-md bg-muted text-muted-foreground [&_svg]:size-4">
                <FileIcon />
              </span>
              <div className="grid min-w-0 flex-1 gap-1">
                <div className="flex items-baseline justify-between gap-2">
                  <span className="truncate text-sm font-medium">{item.file.name}</span>
                  <span className="shrink-0 text-xs tabular-nums text-muted-foreground">
                    {formatFileSize(item.file.size, locale)}
                  </span>
                </div>
                {item.status === "uploading" ? (
                  <Progress size="xs" value={item.progress ?? null} aria-label={item.file.name} />
                ) : null}
                {item.status === "error" ? (
                  <span className="text-xs font-medium text-destructive">{item.error}</span>
                ) : null}
              </div>
              <button
                type="button"
                aria-label={messages.removeItem(item.file.name)}
                onClick={() => setItems(items.filter((i) => i.id !== item.id))}
                className="ui-hit-area inline-flex size-8 items-center justify-center rounded-md text-muted-foreground outline-none hover:bg-accent hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring [&_svg]:size-4"
              >
                <XIcon />
              </button>
            </li>
          ))}
        </ul>
      ) : null}
    </div>
  );
});

"use client";
import { useControllableState } from "@ux-sting/hooks";
import { ChevronLeftIcon, ChevronRightIcon } from "@ux-sting/icons";
import {
  addDays,
  addMonths,
  compareDays,
  getMonthGrid,
  getWeekdayNames,
  getWeekStart,
  isDateDisabled,
  isSameDay,
  isSameMonth,
  isWithinRange,
  startOfMonth,
  startOfWeek,
  type WeekDay,
} from "@ux-sting/primitives";
import { cn } from "@ux-sting/utils";
import { useEffect, useRef, useState, type KeyboardEvent } from "react";
import { useLocale, useMessages } from "../../provider/context.js";

export interface DateRange {
  from: Date | null;
  to: Date | null;
}

interface CalendarBaseProps {
  /** Month shown initially (defaults to the selected date or today). */
  defaultMonth?: Date;
  month?: Date;
  onMonthChange?: (month: Date) => void;
  min?: Date | null;
  max?: Date | null;
  /** Return `true` to disable a date (e.g. closed days). */
  isDisabled?: (date: Date) => boolean;
  weekStartsOn?: WeekDay;
  numberOfMonths?: 1 | 2;
  showOutsideDays?: boolean;
  className?: string;
  /** Today's date (injectable for tests/SSR consistency). */
  today?: Date;
  "aria-label"?: string;
}

export interface CalendarSingleProps extends CalendarBaseProps {
  mode?: "single";
  value?: Date | null;
  defaultValue?: Date | null;
  onValueChange?: (value: Date | null) => void;
}

export interface CalendarRangeProps extends CalendarBaseProps {
  mode: "range";
  value?: DateRange;
  defaultValue?: DateRange;
  onValueChange?: (value: DateRange) => void;
}

export type CalendarProps = CalendarSingleProps | CalendarRangeProps;

/**
 * Accessible month grid (ARIA grid pattern). Keyboard: arrows move by
 * day/week (mirrored in RTL), Home/End to week edges, PageUp/PageDown by
 * month (+Shift by year), Enter/Space selects. Locale sets names and the
 * first day of the week.
 */
export function Calendar(props: CalendarProps) {
  const { locale, dir } = useLocale();
  const messages = useMessages();
  const today = props.today ?? new Date();
  const weekStartsOn = props.weekStartsOn ?? getWeekStart(locale);
  const numberOfMonths = props.numberOfMonths ?? 1;

  const [single, setSingle] = useControllableState<Date | null>({
    value: props.mode !== "range" ? props.value : undefined,
    defaultValue: props.mode !== "range" ? (props.defaultValue ?? null) : null,
    onChange: props.mode !== "range" ? props.onValueChange : undefined,
  });
  const [range, setRange] = useControllableState<DateRange>({
    value: props.mode === "range" ? props.value : undefined,
    defaultValue:
      props.mode === "range"
        ? (props.defaultValue ?? { from: null, to: null })
        : { from: null, to: null },
    onChange: props.mode === "range" ? props.onValueChange : undefined,
  });
  const anchor = props.mode === "range" ? range.from : single;
  const [month, setMonth] = useControllableState({
    value: props.month,
    defaultValue: startOfMonth(props.defaultMonth ?? anchor ?? today),
    onChange: props.onMonthChange,
  });
  const [focused, setFocused] = useState<Date>(anchor ?? today);
  const [hovered, setHovered] = useState<Date | null>(null);
  const focusRequested = useRef(false);
  const gridRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!focusRequested.current) return;
    focusRequested.current = false;
    gridRef.current?.querySelector<HTMLButtonElement>('[data-focused="true"]')?.focus();
  }, [focused, month]);

  const disabled = (d: Date) =>
    isDateDisabled(d, { min: props.min, max: props.max }) || Boolean(props.isDisabled?.(d));

  const moveFocus = (next: Date) => {
    focusRequested.current = true;
    setFocused(next);
    const lastVisible = addMonths(month, numberOfMonths - 1);
    if (
      compareDays(next, startOfMonth(month)) < 0 ||
      compareDays(next, addMonths(startOfMonth(lastVisible), 1)) >= 0
    ) {
      setMonth(startOfMonth(next));
    }
  };

  const select = (date: Date) => {
    if (disabled(date)) return;
    if (props.mode === "range") {
      if (!range.from || range.to) setRange({ from: date, to: null });
      else if (compareDays(date, range.from) < 0) setRange({ from: date, to: range.from });
      else setRange({ from: range.from, to: date });
    } else {
      setSingle(isSameDay(single, date) ? single : date);
    }
  };

  const onKeyDown = (e: KeyboardEvent) => {
    const rtl = dir === "rtl" ? -1 : 1;
    const keys: Record<string, () => Date> = {
      ArrowLeft: () => addDays(focused, -1 * rtl),
      ArrowRight: () => addDays(focused, 1 * rtl),
      ArrowUp: () => addDays(focused, -7),
      ArrowDown: () => addDays(focused, 7),
      Home: () => startOfWeek(focused, weekStartsOn),
      End: () => addDays(startOfWeek(focused, weekStartsOn), 6),
      PageUp: () => addMonths(focused, e.shiftKey ? -12 : -1),
      PageDown: () => addMonths(focused, e.shiftKey ? 12 : 1),
    };
    if (keys[e.key]) {
      e.preventDefault();
      moveFocus(keys[e.key]!());
    } else if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      select(focused);
    }
  };

  const monthFmt = new Intl.DateTimeFormat(locale, { month: "long", year: "numeric" });
  const dayFmt = new Intl.DateTimeFormat(locale, {
    weekday: "long",
    day: "numeric",
    month: "long",
    year: "numeric",
  });
  const numFmt = new Intl.DateTimeFormat(locale, { day: "numeric" });
  const weekdays = getWeekdayNames(locale, weekStartsOn, "short");
  const weekdaysLong = getWeekdayNames(locale, weekStartsOn, "long");
  const months = Array.from({ length: numberOfMonths }, (_, i) => addMonths(month, i));
  const rangeEnd = props.mode === "range" ? (range.to ?? hovered) : null;

  const navButton =
    "ui-hit-area inline-flex size-8 items-center justify-center rounded-md text-muted-foreground outline-none hover:bg-accent hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring disabled:opacity-40 [&_svg]:size-4 rtl:[&_svg]:rotate-180";

  return (
    <div
      ref={gridRef}
      className={cn("inline-flex flex-col gap-3 p-3", props.className)}
      aria-label={props["aria-label"]}
    >
      <div className={cn("grid gap-6", numberOfMonths === 2 && "sm:grid-cols-2")}>
        {months.map((m, mi) => {
          const labelId = `cal-${m.getFullYear()}-${m.getMonth()}`;
          return (
            <div key={labelId} className="grid gap-2">
              <div className="flex items-center justify-between gap-2">
                {mi === 0 ? (
                  <button
                    type="button"
                    aria-label={messages.previousMonth}
                    className={navButton}
                    onClick={() => setMonth(addMonths(month, -1))}
                    disabled={Boolean(
                      props.min && compareDays(startOfMonth(month), startOfMonth(props.min)) <= 0,
                    )}
                  >
                    <ChevronLeftIcon />
                  </button>
                ) : (
                  <span className="size-8" />
                )}
                <h2 id={labelId} aria-live="polite" className="text-sm font-semibold capitalize">
                  {monthFmt.format(m)}
                </h2>
                {mi === months.length - 1 ? (
                  <button
                    type="button"
                    aria-label={messages.nextMonth}
                    className={navButton}
                    onClick={() => setMonth(addMonths(month, 1))}
                    disabled={Boolean(
                      props.max && compareDays(addMonths(startOfMonth(m), 1), props.max) > 0,
                    )}
                  >
                    <ChevronRightIcon />
                  </button>
                ) : (
                  <span className="size-8" />
                )}
              </div>
              <table
                role="grid"
                aria-labelledby={labelId}
                className="border-collapse"
                onKeyDown={onKeyDown}
              >
                <thead>
                  <tr>
                    {weekdays.map((d, i) => (
                      <th
                        key={d}
                        scope="col"
                        abbr={weekdaysLong[i]}
                        className="size-9 text-center text-xs font-medium text-muted-foreground"
                      >
                        {d}
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {getMonthGrid(m, weekStartsOn).map((week, wi) => (
                    <tr key={wi}>
                      {week.map((day) => {
                        const outside = !isSameMonth(day, m);
                        if (outside && !props.showOutsideDays)
                          return <td key={day.toISOString()} className="size-9 p-0" />;
                        const isDisabled = disabled(day);
                        const selectedSingle = props.mode !== "range" && isSameDay(single, day);
                        const isStart = props.mode === "range" && isSameDay(range.from, day);
                        const isEnd = props.mode === "range" && isSameDay(range.to, day);
                        const inRange =
                          props.mode === "range" && isWithinRange(day, range.from, rangeEnd);
                        const selected = selectedSingle || isStart || isEnd;
                        const isFocused = isSameDay(day, focused) && isSameMonth(day, m);
                        return (
                          <td
                            key={day.toISOString()}
                            role="gridcell"
                            aria-selected={selected || inRange || undefined}
                            className={cn(
                              "relative size-9 p-0 text-center",
                              inRange && !isStart && !isEnd && "bg-primary-subtle",
                              isStart && rangeEnd && "rounded-s-md bg-primary-subtle",
                              isEnd && "rounded-e-md bg-primary-subtle",
                            )}
                          >
                            <button
                              type="button"
                              tabIndex={isFocused ? 0 : -1}
                              data-focused={isFocused}
                              disabled={isDisabled}
                              aria-label={dayFmt.format(day)}
                              aria-current={isSameDay(day, today) ? "date" : undefined}
                              onClick={() => {
                                setFocused(day);
                                select(day);
                              }}
                              onFocus={() => setFocused(day)}
                              onPointerEnter={() => setHovered(day)}
                              className={cn(
                                "inline-flex size-9 items-center justify-center rounded-md text-sm tabular-nums outline-none transition-colors",
                                "hover:bg-accent focus-visible:ring-2 focus-visible:ring-ring disabled:pointer-events-none disabled:text-muted-foreground disabled:line-through disabled:opacity-50",
                                outside && "text-muted-foreground",
                                isSameDay(day, today) && !selected && "font-semibold text-primary",
                                inRange && "text-primary-subtle-foreground",
                                selected &&
                                  "bg-primary text-primary-foreground hover:bg-primary-hover",
                              )}
                            >
                              {numFmt.format(day)}
                            </button>
                          </td>
                        );
                      })}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          );
        })}
      </div>
    </div>
  );
}

"use client";
import { useControllableState } from "@ux-sting/hooks";
import { ChevronLeftIcon, ChevronRightIcon } from "@ux-sting/icons";
import { getMonthNames } from "@ux-sting/primitives";
import { cn } from "@ux-sting/utils";
import { useState } from "react";
import { useLocale, useMessages } from "../../provider/context.js";

const cellClass =
  "inline-flex h-10 items-center justify-center rounded-md text-sm capitalize outline-none transition-colors hover:bg-accent focus-visible:ring-2 focus-visible:ring-ring aria-pressed:bg-primary aria-pressed:text-primary-foreground disabled:opacity-40";
const navClass =
  "ui-hit-area inline-flex size-8 items-center justify-center rounded-md text-muted-foreground hover:bg-accent focus-visible:ring-2 focus-visible:ring-ring [&_svg]:size-4 rtl:[&_svg]:rotate-180";

export interface MonthPickerProps {
  /** Selected month as the first day of that month. */
  value?: Date | null;
  defaultValue?: Date | null;
  onValueChange?: (value: Date) => void;
  className?: string;
}

/** Pick a month and year (billing periods, reports). */
export function MonthPicker({
  value: valueProp,
  defaultValue = null,
  onValueChange,
  className,
}: MonthPickerProps) {
  const { locale } = useLocale();
  const messages = useMessages();
  const [value, setValue] = useControllableState({
    value: valueProp,
    defaultValue,
    onChange: (v) => v && onValueChange?.(v),
  });
  const [year, setYear] = useState((value ?? new Date()).getFullYear());
  const names = getMonthNames(locale, "short");
  const yearFmt = new Intl.NumberFormat(locale, { useGrouping: false });
  return (
    <div className={cn("grid w-64 gap-3 p-3", className)}>
      <div className="flex items-center justify-between">
        <button
          type="button"
          className={navClass}
          aria-label={messages.previous}
          onClick={() => setYear(year - 1)}
        >
          <ChevronLeftIcon />
        </button>
        <span aria-live="polite" className="text-sm font-semibold tabular-nums">
          {yearFmt.format(year)}
        </span>
        <button
          type="button"
          className={navClass}
          aria-label={messages.next}
          onClick={() => setYear(year + 1)}
        >
          <ChevronRightIcon />
        </button>
      </div>
      <div role="group" className="grid grid-cols-3 gap-1">
        {names.map((name, i) => (
          <button
            key={name}
            type="button"
            className={cellClass}
            aria-pressed={value?.getFullYear() === year && value?.getMonth() === i}
            onClick={() => setValue(new Date(year, i, 1))}
          >
            {name}
          </button>
        ))}
      </div>
    </div>
  );
}

export interface YearPickerProps {
  value?: number | null;
  defaultValue?: number | null;
  onValueChange?: (value: number) => void;
  min?: number;
  max?: number;
  className?: string;
}

/** Pick a year from a paged 12-year grid. */
export function YearPicker({
  value: valueProp,
  defaultValue = null,
  onValueChange,
  min = 1900,
  max = 2100,
  className,
}: YearPickerProps) {
  const { locale } = useLocale();
  const messages = useMessages();
  const [value, setValue] = useControllableState({
    value: valueProp,
    defaultValue,
    onChange: (v) => v !== null && onValueChange?.(v),
  });
  const [start, setStart] = useState(Math.floor((value ?? new Date().getFullYear()) / 12) * 12);
  const fmt = new Intl.NumberFormat(locale, { useGrouping: false });
  return (
    <div className={cn("grid w-64 gap-3 p-3", className)}>
      <div className="flex items-center justify-between">
        <button
          type="button"
          className={navClass}
          aria-label={messages.previous}
          onClick={() => setStart(start - 12)}
          disabled={start <= min}
        >
          <ChevronLeftIcon />
        </button>
        <span aria-live="polite" className="text-sm font-semibold tabular-nums">
          {fmt.format(start)} – {fmt.format(start + 11)}
        </span>
        <button
          type="button"
          className={navClass}
          aria-label={messages.next}
          onClick={() => setStart(start + 12)}
          disabled={start + 11 >= max}
        >
          <ChevronRightIcon />
        </button>
      </div>
      <div role="group" className="grid grid-cols-3 gap-1">
        {Array.from({ length: 12 }, (_, i) => start + i).map((y) => (
          <button
            key={y}
            type="button"
            className={cn(cellClass, "tabular-nums")}
            aria-pressed={value === y}
            disabled={y < min || y > max}
            onClick={() => setValue(y)}
          >
            {fmt.format(y)}
          </button>
        ))}
      </div>
    </div>
  );
}

"use client";
import * as PopoverPrimitive from "@radix-ui/react-popover";
import { useControllableState } from "@ux-sting/hooks";
import { CalendarIcon } from "@ux-sting/icons";
import { toISODate } from "@ux-sting/primitives";
import { cn } from "@ux-sting/utils";
import { forwardRef, useState, type ReactNode } from "react";
import { controlVariants, type ControlSize } from "../../lib/control.js";
import { useFieldControlProps } from "../../lib/field.js";
import { floatingSurfaceClass } from "../../lib/overlay.js";
import { useLocale, useMessages, usePortalContainer } from "../../provider/context.js";
import { Calendar, type DateRange } from "../calendar/calendar.js";
import { TimePicker } from "../time-picker/time-picker.js";

interface PickerBaseProps {
  placeholder?: string;
  size?: ControlSize;
  disabled?: boolean;
  invalid?: boolean;
  min?: Date | null;
  max?: Date | null;
  isDisabled?: (date: Date) => boolean;
  /** Intl format for the trigger text. */
  formatOptions?: Intl.DateTimeFormatOptions;
  /** Hidden input name for form submission (ISO `YYYY-MM-DD`). */
  name?: string;
  id?: string;
  className?: string;
  "aria-label"?: string;
  "aria-labelledby"?: string;
  /** Extra content under the calendar (presets, time). */
  footer?: ReactNode;
}

function TriggerButton({
  label,
  empty,
  open,
  size,
  className,
  fieldProps,
  aria,
  ...rest
}: {
  label: string;
  empty: boolean;
  open: boolean;
  size?: ControlSize;
  className?: string;
  fieldProps: ReturnType<typeof useFieldControlProps>;
  aria: { "aria-label"?: string; "aria-labelledby"?: string };
}) {
  return (
    <PopoverPrimitive.Trigger asChild>
      <button
        type="button"
        aria-haspopup="dialog"
        aria-expanded={open}
        id={fieldProps.id}
        disabled={fieldProps.disabled}
        data-invalid={fieldProps["aria-invalid"] ? "" : undefined}
        aria-describedby={fieldProps["aria-describedby"]}
        {...aria}
        className={cn(
          controlVariants({ size }),
          "flex items-center gap-2 text-start data-invalid:border-destructive",
          empty && "text-muted-foreground",
          className,
        )}
        {...rest}
      >
        <CalendarIcon className="size-4 shrink-0 text-muted-foreground" />
        <span className="truncate tabular-nums">{label}</span>
      </button>
    </PopoverPrimitive.Trigger>
  );
}

export interface DatePickerProps extends PickerBaseProps {
  value?: Date | null;
  defaultValue?: Date | null;
  onValueChange?: (value: Date | null) => void;
}

/** Date field that opens a calendar popover. Typing-free and keyboard-accessible. */
export const DatePicker = forwardRef<HTMLDivElement, DatePickerProps>(function DatePicker(
  {
    value: valueProp,
    defaultValue = null,
    onValueChange,
    placeholder,
    size,
    disabled,
    invalid,
    min,
    max,
    isDisabled,
    formatOptions = { dateStyle: "medium" },
    name,
    id,
    className,
    footer,
    ...aria
  },
  ref,
) {
  const [open, setOpen] = useState(false);
  const [value, setValue] = useControllableState({
    value: valueProp,
    defaultValue,
    onChange: onValueChange,
  });
  const { locale } = useLocale();
  const messages = useMessages();
  const container = usePortalContainer();
  const fieldProps = useFieldControlProps({ id, disabled, "aria-invalid": invalid || undefined });
  const label = value
    ? new Intl.DateTimeFormat(locale, formatOptions).format(value)
    : (placeholder ?? messages.chooseDate);

  return (
    <div ref={ref} className="contents">
      <PopoverPrimitive.Root open={open} onOpenChange={setOpen}>
        <TriggerButton
          label={label}
          empty={!value}
          open={open}
          size={size}
          className={className}
          fieldProps={fieldProps}
          aria={aria}
        />
        <PopoverPrimitive.Portal container={container}>
          <PopoverPrimitive.Content
            align="start"
            sideOffset={6}
            collisionPadding={8}
            className={cn(floatingSurfaceClass, "p-0")}
          >
            <Calendar
              value={value}
              onValueChange={(d) => {
                setValue(d);
                setOpen(false);
              }}
              min={min}
              max={max}
              isDisabled={isDisabled}
            />
            {footer ? <div className="border-t border-border p-3">{footer}</div> : null}
          </PopoverPrimitive.Content>
        </PopoverPrimitive.Portal>
      </PopoverPrimitive.Root>
      {name ? <input type="hidden" name={name} value={value ? toISODate(value) : ""} /> : null}
    </div>
  );
});

export interface DateRangePickerProps extends PickerBaseProps {
  value?: DateRange;
  defaultValue?: DateRange;
  onValueChange?: (value: DateRange) => void;
  numberOfMonths?: 1 | 2;
}

/** Start/end date selection (bookings, reports). Two months on wide screens. */
export const DateRangePicker = forwardRef<HTMLDivElement, DateRangePickerProps>(
  function DateRangePicker(
    {
      value: valueProp,
      defaultValue = { from: null, to: null },
      onValueChange,
      placeholder,
      size,
      disabled,
      invalid,
      min,
      max,
      isDisabled,
      formatOptions = { dateStyle: "medium" },
      name,
      id,
      className,
      footer,
      numberOfMonths = 2,
      ...aria
    },
    ref,
  ) {
    const [open, setOpen] = useState(false);
    const [value, setValue] = useControllableState({
      value: valueProp,
      defaultValue,
      onChange: onValueChange,
    });
    const { locale } = useLocale();
    const messages = useMessages();
    const container = usePortalContainer();
    const fieldProps = useFieldControlProps({ id, disabled, "aria-invalid": invalid || undefined });
    const fmt = new Intl.DateTimeFormat(locale, formatOptions);
    const label =
      value.from && value.to
        ? fmt.formatRange(value.from, value.to)
        : value.from
          ? `${fmt.format(value.from)} – …`
          : (placeholder ?? messages.chooseDate);

    return (
      <div ref={ref} className="contents">
        <PopoverPrimitive.Root open={open} onOpenChange={setOpen}>
          <TriggerButton
            label={label}
            empty={!value.from}
            open={open}
            size={size}
            className={className}
            fieldProps={fieldProps}
            aria={aria}
          />
          <PopoverPrimitive.Portal container={container}>
            <PopoverPrimitive.Content
              align="start"
              sideOffset={6}
              collisionPadding={8}
              className={cn(floatingSurfaceClass, "max-w-[calc(100vw-1rem)] overflow-auto p-0")}
            >
              <Calendar
                mode="range"
                numberOfMonths={numberOfMonths}
                value={value}
                onValueChange={(r) => {
                  setValue(r);
                  if (r.from && r.to) setOpen(false);
                }}
                min={min}
                max={max}
                isDisabled={isDisabled}
              />
              {footer ? <div className="border-t border-border p-3">{footer}</div> : null}
            </PopoverPrimitive.Content>
          </PopoverPrimitive.Portal>
        </PopoverPrimitive.Root>
        {name ? (
          <>
            <input
              type="hidden"
              name={`${name}From`}
              value={value.from ? toISODate(value.from) : ""}
            />
            <input type="hidden" name={`${name}To`} value={value.to ? toISODate(value.to) : ""} />
          </>
        ) : null}
      </div>
    );
  },
);

export interface DateTimePickerProps extends Omit<DatePickerProps, "footer"> {
  timeStep?: number;
}

/** Date + time selection combined into one `Date` value. */
export const DateTimePicker = forwardRef<HTMLDivElement, DateTimePickerProps>(
  function DateTimePicker(
    {
      value: valueProp,
      defaultValue = null,
      onValueChange,
      timeStep = 30,
      formatOptions = { dateStyle: "medium", timeStyle: "short" },
      name,
      ...props
    },
    ref,
  ) {
    const [value, setValue] = useControllableState({
      value: valueProp,
      defaultValue,
      onChange: onValueChange,
    });
    const time = value
      ? `${String(value.getHours()).padStart(2, "0")}:${String(value.getMinutes()).padStart(2, "0")}`
      : null;
    const merge = (date: Date | null, t: string | null) => {
      if (!date) return null;
      const [h = 0, m = 0] = (t ?? "09:00").split(":").map(Number);
      return new Date(date.getFullYear(), date.getMonth(), date.getDate(), h, m);
    };
    return (
      <>
        <DatePicker
          ref={ref}
          value={value}
          onValueChange={(d) => setValue(merge(d, time))}
          formatOptions={formatOptions}
          footer={
            <TimePicker
              aria-label="Time"
              size="sm"
              step={timeStep}
              value={time}
              onValueChange={(t) => setValue(merge(value ?? new Date(), t))}
            />
          }
          {...props}
        />
        {name ? <input type="hidden" name={name} value={value ? value.toISOString() : ""} /> : null}
      </>
    );
  },
);

"use client";
import { ClockIcon } from "@ux-sting/icons";
import { forwardRef, useMemo } from "react";
import { useLocale } from "../../provider/context.js";
import { Combobox, type ComboboxProps } from "../combobox/combobox.js";

export interface TimePickerProps extends Omit<
  ComboboxProps,
  "options" | "value" | "defaultValue" | "onValueChange"
> {
  /** Time as `HH:mm` (24h), independent of display locale. */
  value?: string | null;
  defaultValue?: string | null;
  onValueChange?: (value: string | null) => void;
  /** Minutes between options. */
  step?: number;
  /** Earliest/latest selectable time, `HH:mm`. */
  min?: string;
  max?: string;
  /** Force 12h/24h display; defaults to the locale's convention. */
  hour12?: boolean;
}

const toMinutes = (t: string) => {
  const [h = "0", m = "0"] = t.split(":");
  return Number(h) * 60 + Number(m);
};

/** Searchable time selector with locale-formatted options (type "9:30" or "14"). */
export const TimePicker = forwardRef<HTMLButtonElement, TimePickerProps>(function TimePicker(
  { step = 30, min = "00:00", max = "23:59", hour12, placeholder = "--:--", ...props },
  ref,
) {
  const { locale } = useLocale();
  const options = useMemo(() => {
    const fmt = new Intl.DateTimeFormat(locale, { hour: "numeric", minute: "2-digit", hour12 });
    const list = [];
    for (let t = toMinutes(min); t <= toMinutes(max); t += step) {
      const h = Math.floor(t / 60);
      const m = t % 60;
      const value = `${String(h).padStart(2, "0")}:${String(m).padStart(2, "0")}`;
      list.push({
        value,
        label: fmt.format(new Date(2024, 0, 1, h, m)),
        keywords: [value, `${h}${String(m).padStart(2, "0")}`],
      });
    }
    return list;
  }, [locale, step, min, max, hour12]);
  return (
    <Combobox
      ref={ref}
      options={options}
      placeholder={placeholder}
      {...props}
      renderOption={(o) => (
        <span className="flex items-center gap-2 tabular-nums">
          <ClockIcon className="size-3.5 text-muted-foreground" />
          {o.label}
        </span>
      )}
    />
  );
});

"use client";
import * as DialogPrimitive from "@radix-ui/react-dialog";
