"use client";
import { useControllableState } from "@ux-sting/hooks";
import { ChevronLeftIcon, ChevronRightIcon, EllipsisIcon } from "@ux-sting/icons";
import { cn, getPaginationRange } from "@ux-sting/utils";
import { forwardRef, type HTMLAttributes, type ReactNode } from "react";
import { useLocale, useMessages } from "../../provider/context.js";
import { buttonVariants } from "../button/button.variants.js";

export interface PaginationProps extends Omit<HTMLAttributes<HTMLElement>, "onChange"> {
  totalPages: number;
  page?: number;
  defaultPage?: number;
  onPageChange?: (page: number) => void;
  /** Link mode (crawlable): return the URL for a page. */
  getHref?: (page: number) => string;
  /** Render links with a router component, e.g. Next.js `Link`. */
  renderLink?: (props: {
    href: string;
    className: string;
    children: ReactNode;
    "aria-current"?: "page";
    "aria-label": string;
  }) => ReactNode;
  siblings?: number;
  size?: "sm" | "md";
  /** `compact` shows "Page x of y" (auto on small screens). */
  variant?: "default" | "compact";
}

/**
 * Page navigation. Use `getHref` for SEO-friendly links (listings, search)
 * or `onPageChange` for in-place tables. Collapses to a compact summary on
 * narrow screens.
 */
export const Pagination = forwardRef<HTMLElement, PaginationProps>(function Pagination(
  {
    totalPages,
    page: pageProp,
    defaultPage = 1,
    onPageChange,
    getHref,
    renderLink,
    siblings = 1,
    size = "md",
    variant = "default",
    className,
    ...props
  },
  ref,
) {
  const [page, setPage] = useControllableState({
    value: pageProp,
    defaultValue: defaultPage,
    onChange: onPageChange,
  });
  const messages = useMessages();
  const { locale } = useLocale();
  const nf = new Intl.NumberFormat(locale);
  if (totalPages <= 1) return null;

  const item = (
    target: number,
    children: ReactNode,
    opts: { label: string; current?: boolean; disabled?: boolean; className?: string },
  ) => {
    const className = cn(
      buttonVariants({
        variant: opts.current ? "outline" : "ghost",
        size: size === "sm" ? "sm" : "md",
      }),
      "min-w-(--ui-height-md) px-2 tabular-nums",
      size === "sm" && "min-w-(--ui-height-sm)",
      opts.current && "border-primary text-primary",
      opts.className,
    );
    if (opts.disabled) {
      return (
        <span aria-disabled="true" className={cn(className, "pointer-events-none opacity-40")}>
          {children}
        </span>
      );
    }
    if (getHref) {
      const href = getHref(target);
      const linkProps = {
        href,
        className,
        children,
        "aria-label": opts.label,
        ...(opts.current ? { "aria-current": "page" as const } : {}),
      };
      return renderLink ? renderLink(linkProps) : <a {...linkProps} />;
    }
    return (
      <button
        type="button"
        className={className}
        aria-label={opts.label}
        aria-current={opts.current ? "page" : undefined}
        onClick={() => setPage(target)}
      >
        {children}
      </button>
    );
  };

  const prev = item(page - 1, <ChevronLeftIcon className="rtl:rotate-180" />, {
    label: messages.previous,
    disabled: page <= 1,
  });
  const next = item(page + 1, <ChevronRightIcon className="rtl:rotate-180" />, {
    label: messages.next,
    disabled: page >= totalPages,
  });

  return (
    <nav
      ref={ref}
      aria-label={messages.pagination}
      className={cn("flex items-center justify-center", className)}
      {...props}
    >
      <ul className="flex items-center gap-1">
        <li>{prev}</li>
        <li
          className={cn(
            "px-2 text-sm tabular-nums text-muted-foreground",
            variant === "compact" ? "block" : "sm:hidden",
          )}
          aria-live="polite"
        >
          {messages.pageOf(page, totalPages)}
        </li>
        {variant === "default"
          ? getPaginationRange(page, totalPages, siblings).map((p, i) =>
              p === "ellipsis" ? (
                <li
                  key={`e${i}`}
                  aria-hidden
                  className="hidden size-9 items-center justify-center text-muted-foreground sm:flex [&_svg]:size-4"
                >
                  <EllipsisIcon />
                </li>
              ) : (
                <li key={p} className="hidden sm:block">
                  {item(p, nf.format(p), { label: messages.goToPage(p), current: p === page })}
                </li>
              ),
            )
          : null}
        <li>{next}</li>
      </ul>
    </nav>
  );
});

import { CheckIcon } from "@ux-sting/icons";
import { cn } from "@ux-sting/utils";
import { forwardRef, type HTMLAttributes, type ReactNode } from "react";

export interface StepperStep {
  title: ReactNode;
  description?: ReactNode;
  /** Mark a step as having an error. */
  error?: boolean;
}

export interface StepperProps extends HTMLAttributes<HTMLOListElement> {
  steps: StepperStep[];
  /** Zero-based index of the current step. */
  current: number;
  orientation?: "horizontal" | "vertical";
  /** Render steps as buttons to allow jumping back (completed steps only). */
  onStepClick?: (index: number) => void;
  /** Screen reader text for completed steps (localize it). */
  completedLabel?: string;
}

/**
 * Progress through a multi-step flow. The current step is announced with
 * `aria-current="step"`; completed steps can be revisited.
 */
export const Stepper = forwardRef<HTMLOListElement, StepperProps>(function Stepper(
  {
    steps,
    current,
    orientation = "horizontal",
    onStepClick,
    completedLabel = "completed",
    className,
    ...props
  },
  ref,
) {
  return (
    <ol
      ref={ref}
      className={cn(
        "flex gap-4",
        orientation === "horizontal" ? "flex-col sm:flex-row sm:items-start" : "flex-col",
        className,
      )}
      {...props}
    >
      {steps.map((step, i) => {
        const state = step.error
          ? "error"
          : i < current
            ? "complete"
            : i === current
              ? "current"
              : "upcoming";
        const Indicator = (
          <span
            className={cn(
              "flex size-8 shrink-0 items-center justify-center rounded-full border-2 text-sm font-semibold tabular-nums transition-colors [&_svg]:size-4",
              state === "complete" && "border-primary bg-primary text-primary-foreground",
              state === "current" && "border-primary text-primary",
              state === "upcoming" && "border-border-strong text-muted-foreground",
              state === "error" && "border-destructive bg-destructive text-destructive-foreground",
            )}
          >
            {state === "complete" ? <CheckIcon /> : i + 1}
          </span>
        );
        const content = (
          <>
            {Indicator}
            <span className="grid gap-0.5 text-start">
              <span
                className={cn(
                  "text-sm font-medium",
                  state === "upcoming" ? "text-muted-foreground" : "text-foreground",
                )}
              >
                {step.title}
                {state === "complete" ? <span className="sr-only"> ({completedLabel})</span> : null}
              </span>
              {step.description ? (
                <span className="text-xs text-muted-foreground">{step.description}</span>
              ) : null}
            </span>
          </>
        );
        return (
          <li
            key={i}
            aria-current={i === current ? "step" : undefined}
            data-state={state}
            className={cn(
              "relative flex flex-1 items-start gap-3",
              orientation === "horizontal" &&
                "sm:after:mt-4 sm:after:h-0.5 sm:after:flex-1 sm:after:bg-border sm:last:after:hidden",
              state === "complete" && "sm:after:bg-primary",
            )}
          >
            {onStepClick && i < current ? (
              <button
                type="button"
                onClick={() => onStepClick(i)}
                className="flex items-start gap-3 rounded-md outline-none focus-visible:ring-2 focus-visible:ring-ring"
              >
                {content}
              </button>
            ) : (
              content
            )}
          </li>
        );
      })}
    </ol>
  );
});

