    showValue,
    formatValue,
    className,
    id,
    ...props
  },
  ref,
) {
  const indeterminate = value === null;
  const pct = indeterminate ? 0 : clamp((value / max) * 100, 0, 100);
  const text = indeterminate ? undefined : (formatValue?.(value, max) ?? `${Math.round(pct)}%`);
