      aria-valuemax={max}
      aria-valuenow={indeterminate ? undefined : value}
      aria-valuetext={text}
      aria-labelledby={label ? labelId : undefined}
      data-state={indeterminate ? "indeterminate" : pct >= 100 ? "complete" : "loading"}
