export const TableRow = forwardRef<
  HTMLTableRowElement,
  HTMLAttributes<HTMLTableRowElement> & { selected?: boolean }
>(function TableRow({ selected, className, ...props }, ref) {
  return (
    <tr
      ref={ref}
      data-selected={selected ? "" : undefined}
      aria-selected={selected}
      className={cn(
