        className,
      )}
      {...props}
    />
  );
});

export type SortDirection = "asc" | "desc" | false;

export interface TableHeadProps extends Omit<ThHTMLAttributes<HTMLTableCellElement>, "align"> {
  /** Current sort; renders `aria-sort` and a sort button when `onSort` is set. */
  sortDirection?: SortDirection;
  onSort?: () => void;
  align?: "start" | "center" | "end";
}

export const TableHead = forwardRef<HTMLTableCellElement, TableHeadProps>(function TableHead(
  { sortDirection, onSort, align = "start", className, children, scope = "col", ...props },
  ref,
) {
  const alignClass =
    align === "end" ? "text-end" : align === "center" ? "text-center" : "text-start";
  return (
    <th
      ref={ref}
      scope={scope}
      aria-sort={
        onSort
          ? sortDirection === "asc"
            ? "ascending"
            : sortDirection === "desc"
              ? "descending"
              : "none"
          : undefined
      }
      className={cn(
        "h-10 whitespace-nowrap px-(--ui-cell-px) align-middle text-xs font-semibold uppercase tracking-wide text-muted-foreground",
        alignClass,
        className,
      )}
      {...props}
    >
      {onSort ? (
        <button
          type="button"
          onClick={onSort}
          className={cn(
            "-mx-1 inline-flex items-center gap-1 rounded-sm px-1 uppercase outline-none hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring [&_svg]:size-3.5",
            align === "end" && "flex-row-reverse",
          )}
        >
          {children}
          {sortDirection === "asc" ? (
            <ArrowUpIcon />
          ) : sortDirection === "desc" ? (
            <ArrowDownIcon />
          ) : (
            <ArrowUpDownIcon className="opacity-50" />
          )}
        </button>
      ) : (
        children
      )}
    </th>
  );
});

export const TableCell = forwardRef<
  HTMLTableCellElement,
  Omit<TdHTMLAttributes<HTMLTableCellElement>, "align"> & { align?: "start" | "center" | "end" }
>(function TableCell({ align = "start", className, ...props }, ref) {
  return (
    <td
      ref={ref}
      className={cn(
        "px-(--ui-cell-px) py-(--ui-cell-py) align-middle",
        align === "end"
          ? "text-end tabular-nums"
          : align === "center"
            ? "text-center"
            : "text-start",
        className,
      )}
      {...props}
    />
  );
});

export const TableCaption = forwardRef<
  HTMLTableCaptionElement,
  HTMLAttributes<HTMLTableCaptionElement>
>(function TableCaption({ className, ...props }, ref) {
  return (
    <caption ref={ref} className={cn("mt-3 text-sm text-muted-foreground", className)} {...props} />
