"use client";
import { useControllableState } from "@ux-sting/hooks";
import { Columns3Icon } from "./columns-icon.js";
import { cn } from "@ux-sting/utils";
import { useMemo, useRef, useState, type KeyboardEvent, type ReactNode } from "react";
import { useMessages } from "../../provider/context.js";
import { Button } from "../button/button.js";
import { Checkbox } from "../checkbox/checkbox.js";
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuLabel,
  DropdownMenuTrigger,
} from "../dropdown-menu/dropdown-menu.js";
import { Pagination } from "../pagination/pagination.js";
import { SearchInput } from "../search-input/search-input.js";
import { NativeSelect } from "../native-select/native-select.js";
import { Skeleton } from "../skeleton/skeleton.js";
import { EmptyState } from "../state/state.js";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "../table/table.js";
import type { DataTableColumn, DataTableProps, SortState } from "./data-table.types.js";

function getValue<T>(row: T, column: DataTableColumn<T>): unknown {
  const { accessor } = column;
  if (typeof accessor === "function") return accessor(row);
  if (accessor !== undefined) return row[accessor];
  return (row as Record<string, unknown>)[column.id];
}

const collator = new Intl.Collator(undefined, { numeric: true, sensitivity: "base" });

function compare(a: unknown, b: unknown): number {
  if (a == null) return b == null ? 0 : 1;
  if (b == null) return -1;
  if (typeof a === "number" && typeof b === "number") return a - b;
  if (a instanceof Date && b instanceof Date) return a.getTime() - b.getTime();
  return collator.compare(String(a), String(b));
}

/**
 * Feature-complete data table: search, sort, filter, pagination, row
 * selection with bulk actions, column visibility, loading and empty states,
 * responsive stacking. Works client-side or in `manual` (server) mode.
 */
export function DataTable<T>({
  data,
  columns,
  getRowId,
  label,
  selectable,
  selectedIds: selectedProp,
  onSelectedIdsChange,
  bulkActions,
  searchable,
  searchPlaceholder,
  filter,
  sort: sortProp,
  defaultSort = null,
  onSortChange,
  pageSize: pageSizeProp = 10,
  pageSizeOptions = [10, 25, 50],
  manual,
  totalRows,
  page: pageProp,
  onPageChange,
  loading,
  empty,
  toolbar,
  columnToggle,
  onRowClick,
  responsive = "scroll",
  stickyHeader,
  striped,
  className,
  grid,
}: DataTableProps<T>) {
  const messages = useMessages();
  const [search, setSearch] = useState("");
  const [sort, setSort] = useControllableState<SortState | null>({
    value: sortProp,
    defaultValue: defaultSort,
    onChange: onSortChange,
  });
  const [selected, setSelected] = useControllableState<string[]>({
    value: selectedProp,
    defaultValue: [],
    onChange: onSelectedIdsChange,
  });
  const [page, setPage] = useControllableState({
    value: pageProp,
    defaultValue: 1,
    onChange: onPageChange,
  });
  const [pageSize, setPageSize] = useState(pageSizeProp || 0);
  // The initial page size is always selectable, even when it is not a default option.
  const sizeOptions = [...new Set([...pageSizeOptions, pageSizeProp || 0])]
    .filter((n) => n > 0)
    .sort((a, b) => a - b);
  const [hidden, setHidden] = useState<Set<string>>(
    () => new Set(columns.filter((c) => c.hidden).map((c) => c.id)),
  );
  const tableRef = useRef<HTMLTableElement>(null);

  const visibleColumns = columns.filter((c) => !hidden.has(c.id));

  const processed = useMemo(() => {
    if (manual) return data;
    let rows = filter ? data.filter(filter) : data;
    const q = search.trim().toLowerCase();
    if (q) {
      rows = rows.filter((row) =>
        columns.some((c) => {
          if (c.searchable === false) return false;
          const v = getValue(row, c);
          return (
            (typeof v === "string" || typeof v === "number") && String(v).toLowerCase().includes(q)
          );
        }),
      );
    }
    if (sort) {
      const column = columns.find((c) => c.id === sort.id);
      if (column) {
        const dir = sort.direction === "asc" ? 1 : -1;
        rows = [...rows].sort(
          (a, b) =>
            dir *
            (column.sortFn
              ? column.sortFn(a, b)
              : compare(getValue(a, column), getValue(b, column))),
        );
      }
    }
    return rows;
  }, [data, columns, filter, search, sort, manual]);

  const total = manual ? (totalRows ?? data.length) : processed.length;
  const totalPages = pageSize ? Math.max(1, Math.ceil(total / pageSize)) : 1;
  const currentPage = Math.min(page, totalPages);
  const rows =
    manual || !pageSize
      ? processed
      : processed.slice((currentPage - 1) * pageSize, currentPage * pageSize);
  const rowIds = rows.map((r, i) => getRowId(r, i));
  const allSelected = rowIds.length > 0 && rowIds.every((id) => selected.includes(id));
  const someSelected = rowIds.some((id) => selected.includes(id));

  const toggleSort = (id: string) => {
    setPage(1);
    setSort(
      !sort || sort.id !== id
        ? { id, direction: "asc" }
        : sort.direction === "asc"
          ? { id, direction: "desc" }
          : null,
    );
  };

  const onGridKeyDown = (e: KeyboardEvent<HTMLTableElement>) => {
    if (!grid) return;
    const cell = (e.target as HTMLElement).closest("td,th") as HTMLTableCellElement | null;
    if (!cell) return;
    const row = cell.parentElement as HTMLTableRowElement;
    const table = tableRef.current;
    if (!table) return;
    const allRows = Array.from(table.rows);
    let r = allRows.indexOf(row);
    let c = cell.cellIndex;
    const rtl = getComputedStyle(table).direction === "rtl";
    if (e.key === "ArrowDown") r++;
    else if (e.key === "ArrowUp") r--;
    else if (e.key === (rtl ? "ArrowLeft" : "ArrowRight")) c++;
    else if (e.key === (rtl ? "ArrowRight" : "ArrowLeft")) c--;
    else if (e.key === "Home") c = 0;
    else if (e.key === "End") c = row.cells.length - 1;
    else return;
    const target = allRows[r]?.cells[Math.max(0, c)];
    if (!target) return;
    e.preventDefault();
    const focusable = target.querySelector<HTMLElement>("button, a, input, [tabindex]");
    (focusable ?? target).focus();
  };

  const selectionCount = selected.length;
  const colSpan = visibleColumns.length + (selectable ? 1 : 0);

  let body: ReactNode;
  if (loading) {
    body = Array.from({ length: Math.min(pageSize || 5, 8) }, (_, i) => (
      <TableRow key={`s${i}`}>
        {selectable ? (
          <TableCell className="w-10">
            <Skeleton className="size-4" />
          </TableCell>
        ) : null}
        {visibleColumns.map((c) => (
          <TableCell key={c.id}>
            <Skeleton shape="text" className="max-w-40" />
          </TableCell>
        ))}
      </TableRow>
    ));
  } else if (rows.length === 0) {
    body = (
      <tr>
        <td colSpan={colSpan}>{empty ?? <EmptyState size="sm" title={messages.noResults} />}</td>
      </tr>
    );
  } else {
    body = rows.map((row, i) => {
      const id = rowIds[i]!;
      const isSelected = selected.includes(id);
      return (
        <TableRow
          key={id}
          selected={selectable ? isSelected : undefined}
          onClick={onRowClick ? () => onRowClick(row) : undefined}
          className={cn(onRowClick && "cursor-pointer")}
        >
          {selectable ? (
            <TableCell
              className="w-10"
              role={grid ? "gridcell" : undefined}
              onClick={(e) => e.stopPropagation()}
            >
              <Checkbox
                aria-label={messages.selectRow}
                checked={isSelected}
                onCheckedChange={(v) =>
                  setSelected(v === true ? [...selected, id] : selected.filter((s) => s !== id))
                }
              />
            </TableCell>
          ) : null}
          {visibleColumns.map((c) => {
            const value = getValue(row, c);
            return (
              <TableCell
                key={c.id}
                align={c.align}
                tabIndex={grid ? -1 : undefined}
                role={grid ? "gridcell" : undefined}
                data-label={c.mobileLabel ?? (typeof c.header === "string" ? c.header : undefined)}
                className={c.className}
              >
                {c.cell ? c.cell(row, value) : value == null ? "—" : String(value)}
              </TableCell>
            );
          })}
        </TableRow>
      );
    });
  }

  return (
    <div className={cn("grid grid-cols-[minmax(0,1fr)] gap-3", className)}>
      {searchable || toolbar || columnToggle || (bulkActions && selectionCount > 0) ? (
        <div className="flex flex-wrap items-center gap-2">
          {selectionCount > 0 && bulkActions ? (
            <div
              className="flex flex-wrap items-center gap-2 rounded-md bg-primary-subtle px-3 py-1.5 text-sm text-primary-subtle-foreground"
              role="status"
            >
              <span className="font-medium">{messages.selected(selectionCount)}</span>
              {bulkActions(selected, () => setSelected([]))}
            </div>
          ) : searchable ? (
            <SearchInput
              className="w-full sm:max-w-xs"
              size="sm"
              placeholder={searchPlaceholder}
              value={search}
              onValueChange={(v) => {
                setSearch(v);
                setPage(1);
              }}
            />
          ) : null}
          <div className="ms-auto flex flex-wrap items-center gap-2">
            {toolbar}
            {columnToggle ? (
              <DropdownMenu>
                <DropdownMenuTrigger asChild>
                  <Button variant="outline" size="sm" startIcon={<Columns3Icon />}>
                    {messages.columns}
                  </Button>
                </DropdownMenuTrigger>
                <DropdownMenuContent align="end">
                  <DropdownMenuLabel>{messages.columns}</DropdownMenuLabel>
                  {columns
                    .filter((c) => c.hideable !== false)
                    .map((c) => (
                      <DropdownMenuCheckboxItem
                        key={c.id}
                        checked={!hidden.has(c.id)}
                        onSelect={(e: Event) => e.preventDefault()}
                        onCheckedChange={(v: boolean) =>
                          setHidden((prev) => {
                            const next = new Set(prev);
                            if (v) next.delete(c.id);
                            else next.add(c.id);
                            return next;
                          })
                        }
                      >
                        {c.header}
                      </DropdownMenuCheckboxItem>
                    ))}
                </DropdownMenuContent>
              </DropdownMenu>
            ) : null}
          </div>
        </div>
      ) : null}

      <div className="rounded-lg border border-border">
        <Table
          ref={tableRef}
          label={label}
          role={grid ? "grid" : undefined}
          aria-busy={loading || undefined}
          aria-rowcount={manual ? total : undefined}
          responsive={responsive}
          stickyHeader={stickyHeader}
          striped={striped}
          onKeyDown={onGridKeyDown}
        >
          <TableHeader>
            <TableRow className="hover:bg-transparent">
              {selectable ? (
                <TableHead className="w-10">
                  <Checkbox
                    aria-label={messages.selectAll}
                    checked={allSelected ? true : someSelected ? "indeterminate" : false}
                    onCheckedChange={(v) =>
                      setSelected(
                        v === true
                          ? Array.from(new Set([...selected, ...rowIds]))
                          : selected.filter((s) => !rowIds.includes(s)),
                      )
                    }
                  />
                </TableHead>
              ) : null}
              {visibleColumns.map((c) => (
                <TableHead
                  key={c.id}
                  align={c.align}
                  tabIndex={grid ? -1 : undefined}
                  sortDirection={sort?.id === c.id ? sort.direction : false}
                  onSort={c.sortable ? () => toggleSort(c.id) : undefined}
                >
                  {c.header}
                </TableHead>
              ))}
            </TableRow>
          </TableHeader>
          <TableBody>{body}</TableBody>
        </Table>
      </div>

      {pageSize && total > 0 ? (
        <div className="flex flex-col-reverse items-center justify-between gap-3 sm:flex-row">
          <label className="flex items-center gap-2 text-sm text-muted-foreground">
            {messages.rowsPerPage}
            <NativeSelect
              size="sm"
              className="w-20"
              value={String(pageSize)}
              onChange={(e) => {
                setPageSize(Number(e.target.value));
                setPage(1);
              }}
            >
              {sizeOptions.map((n) => (
                <option key={n} value={n}>
                  {n}
                </option>
              ))}
            </NativeSelect>
          </label>
          <Pagination totalPages={totalPages} page={currentPage} onPageChange={setPage} size="sm" />
        </div>
      ) : null}
    </div>
  );
}

/** DataTable with grid semantics and arrow-key cell navigation (spreadsheet-like). */
export function DataGrid<T>(props: Omit<DataTableProps<T>, "grid">) {
  return <DataTable {...props} grid />;
}

import type { ReactNode } from "react";

export interface DataTableColumn<T> {
  id: string;
  header: ReactNode;
  /** Property key or function returning the raw value (used for sort/filter). */
  accessor?: keyof T | ((row: T) => unknown);
  /** Custom cell renderer. */
  cell?: (row: T, value: unknown) => ReactNode;
  sortable?: boolean;
  sortFn?: (a: T, b: T) => number;
  align?: "start" | "center" | "end";
  /** Can be hidden from the columns menu. Defaults to true. */
  hideable?: boolean;
  hidden?: boolean;
  /** Included in the global search. Defaults to true for string/number values. */
  searchable?: boolean;
  className?: string;
  /** Label for stacked (mobile) layout; defaults to `header` when it is a string. */
  mobileLabel?: string;
}

export interface SortState {
  id: string;
  direction: "asc" | "desc";
}

export interface DataTableProps<T> {
  data: T[];
  columns: DataTableColumn<T>[];
  /** Stable row id. */
  getRowId: (row: T, index: number) => string;
  /** Accessible table caption/label. */
  label: string;
  /** Enables row checkboxes. */
  selectable?: boolean;
  selectedIds?: string[];
  onSelectedIdsChange?: (ids: string[]) => void;
  /** Rendered in the toolbar while rows are selected. */
  bulkActions?: (selectedIds: string[], clear: () => void) => ReactNode;
  /** Show a global search box. */
  searchable?: boolean;
  searchPlaceholder?: string;
  /** Additional predicate filter (e.g. from a FilterPanel). */
  filter?: (row: T) => boolean;
  sort?: SortState | null;
  defaultSort?: SortState | null;
  onSortChange?: (sort: SortState | null) => void;
  /** Rows per page; `false` disables pagination. */
  pageSize?: number | false;
  pageSizeOptions?: number[];
  /** Server-side mode: data is already filtered/sorted/paged. */
  manual?: boolean;
  /** Total rows for server-side pagination. */
  totalRows?: number;
  page?: number;
  onPageChange?: (page: number) => void;
  loading?: boolean;
  empty?: ReactNode;
  /** Toolbar content (filters, export button). */
  toolbar?: ReactNode;
  /** Show the column visibility menu. */
  columnToggle?: boolean;
  onRowClick?: (row: T) => void;
  responsive?: "scroll" | "stack";
  stickyHeader?: boolean;
  striped?: boolean;
  className?: string;
  /** Enables grid keyboard navigation (arrow keys between cells). */
  grid?: boolean;
}

import { Slot } from "@ux-sting/primitives";
import { cn } from "@ux-sting/utils";
import { forwardRef, type HTMLAttributes, type LiHTMLAttributes, type ReactNode } from "react";

export interface ListProps extends HTMLAttributes<HTMLUListElement> {
  ordered?: boolean;
  /** Visual style: plain rows, dividers between rows, or bordered container. */
  variant?: "plain" | "divided" | "bordered";
}

export const List = forwardRef<HTMLUListElement, ListProps>(function List(
  { ordered, variant = "plain", className, ...props },
  ref,
) {
  const Comp = ordered ? "ol" : "ul";
  return (
    <Comp
      ref={ref as never}
      className={cn(
        "flex flex-col",
        variant === "divided" && "divide-y divide-border",
        variant === "bordered" &&
          "divide-y divide-border overflow-hidden rounded-lg border border-border",
        className,
      )}
      {...props}
    />
  );
});

export interface ListItemProps extends Omit<LiHTMLAttributes<HTMLLIElement>, "title"> {
  /** Leading visual (avatar, icon). */
  start?: ReactNode;
  /** Trailing content (badge, action, chevron). */
  end?: ReactNode;
  title?: ReactNode;
  description?: ReactNode;
  /** Render the content as the child element (e.g. a link) for full-row clicks. */
  asChild?: boolean;
}

export const ListItem = forwardRef<HTMLLIElement, ListItemProps>(function ListItem(
  { start, end, title, description, asChild, className, children, ...props },
  ref,
) {
  const content =
    title || description ? (
      <div className="min-w-0 flex-1">
        {title ? <div className="truncate text-sm font-medium text-foreground">{title}</div> : null}
        {description ? <div className="text-sm text-muted-foreground">{description}</div> : null}
        {children}
      </div>
    ) : (
      <div className="min-w-0 flex-1">{children}</div>
    );
  const rowClass = "flex items-center gap-3 px-card-p py-(--ui-list-item-py)";
  return (
    <li ref={ref} className={cn(!asChild && rowClass, className)} {...props}>
      {asChild ? (
        <Slot
          className={cn(
            rowClass,
            "outline-none transition-colors hover:bg-accent focus-visible:bg-accent focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring",
          )}
        >
          {children}
        </Slot>
      ) : (
        <>
          {start ? <div className="shrink-0">{start}</div> : null}
          {content}
          {end ? <div className="shrink-0 text-muted-foreground">{end}</div> : null}
        </>
      )}
    </li>
  );
});

import { TrendingDownIcon, TrendingUpIcon } from "@ux-sting/icons";
import { cn } from "@ux-sting/utils";
import { forwardRef, type HTMLAttributes, type ReactNode } from "react";
import { Card } from "../card/card.js";

export interface StatProps extends HTMLAttributes<HTMLDivElement> {
  label: ReactNode;
  value: ReactNode;
  /** Change indicator, e.g. `"+12%"`. */
  delta?: ReactNode;
  /** Direction of change; `positive`/`negative` describe meaning, not direction. */
  trend?: "up" | "down" | "neutral";
  /** Whether "up" is good (revenue) or bad (churn). */
  trendMeaning?: "positive-up" | "positive-down";
  helpText?: ReactNode;
  icon?: ReactNode;
}

/** Key figure with optional trend. Uses tabular numbers and icon+text for trend (not color alone). */
export const Stat = forwardRef<HTMLDivElement, StatProps>(function Stat(
  {
    label,
    value,
    delta,
    trend = "neutral",
    trendMeaning = "positive-up",
    helpText,
    icon,
    className,
    ...props
  },
  ref,
) {
  const good = trend === "neutral" ? null : (trend === "up") === (trendMeaning === "positive-up");
  return (
    <div ref={ref} className={cn("grid gap-1", className)} {...props}>
      <dt className="flex items-center justify-between gap-2 text-sm font-medium text-muted-foreground">
        {label}
        {icon ? (
          <span aria-hidden className="[&_svg]:size-4">
            {icon}
          </span>
        ) : null}
      </dt>
      <dd className="text-2xl font-semibold tracking-tight tabular-nums">
        <bdi>{value}</bdi>
      </dd>
      {delta || helpText ? (
        <dd className="flex flex-wrap items-center gap-2 text-xs text-muted-foreground">
          {delta ? (
            <span
              className={cn(
                "inline-flex items-center gap-1 rounded-sm px-1.5 py-0.5 font-medium tabular-nums [&_svg]:size-3.5",
                good === null
                  ? "bg-muted text-muted-foreground"
                  : good
                    ? "bg-success-subtle text-success-subtle-foreground"
                    : "bg-destructive-subtle text-destructive-subtle-foreground",
              )}
            >
              {trend === "up" ? <TrendingUpIcon /> : trend === "down" ? <TrendingDownIcon /> : null}
              <bdi>{delta}</bdi>
            </span>
          ) : null}
          {helpText}
        </dd>
      ) : null}
    </div>
  );
});

/** Stat wrapped in a card; use in dashboard KPI rows. */
export const StatCard = forwardRef<HTMLDivElement, StatProps>(function StatCard(
  { className, ...props },
  ref,
) {
  return (
    <Card ref={ref} className={cn("p-card-p", className)}>
      <dl>
        <Stat {...props} />
      </dl>
    </Card>
  );
});

/** Compact inline metric: label + value pair. */
export function Metric({
  label,
  value,
  className,
}: {
  label: ReactNode;
  value: ReactNode;
  className?: string;
}) {
  return (
    <div className={cn("flex flex-col", className)}>
      <span className="text-xs text-muted-foreground">{label}</span>
      <span className="text-md font-semibold tabular-nums">
        <bdi>{value}</bdi>
      </span>
    </div>
  );
}

/** Semantic wrapper for a group of `Stat`s (renders a `<dl>`). */
export const StatGroup = forwardRef<HTMLDListElement, HTMLAttributes<HTMLDListElement>>(
  function StatGroup({ className, ...props }, ref) {
    return (
      <dl
        ref={ref}
        className={cn("grid gap-6 sm:grid-cols-2 lg:grid-cols-4", className)}
        {...props}
      />
    );
  },
);

"use client";
import { cn } from "@ux-sting/utils";
import { forwardRef, type HTMLAttributes, type ReactNode, type Ref } from "react";
import {
  ChartLegend,
  ChartTable,
  ChartTooltip,
  useActiveIndex,
  useChartFormat,
  useElementWidth,
} from "./chart-core.js";
import { niceTicks, slotColor, textWidth, tickIndices, type ChartSeries } from "./chart-utils.js";

export interface BarChartProps<T extends object> extends Omit<
  HTMLAttributes<HTMLDivElement>,
  "children"
> {
  data: T[];
  /** Field holding each column's category / date. */
  index: Extract<keyof T, string>;
  series: ChartSeries<T>[];
  /** Accessible name: what the chart shows. */
  label: string;
  /** Stack series in one column (parts of a whole) instead of side by side. */
  stacked?: boolean;
  height?: number;
  valueFormatter?: (value: number) => string;
  indexFormatter?: (value: T[Extract<keyof T, string>]) => string;
  /** Print each column's value on its cap (single, unstacked series only). */
  showValues?: boolean;
  showLegend?: boolean;
  empty?: ReactNode;
}

const M = { top: 16, end: 8, bottom: 26 };
const MAX_BAR = 24;
const GAP = 2;
const RADIUS = 4;

/** Column path: square at the baseline, 4px rounded data end. */
function column(x: number, w: number, top: number, bottom: number, round: boolean) {
  const h = bottom - top;
  if (h <= 0) return "";
  const r = round ? Math.min(RADIUS, w / 2, h) : 0;
  return `M${x},${bottom}V${top + r}Q${x},${top} ${x + r},${top}H${x + w - r}Q${x + w},${top} ${x + w},${top + r}V${bottom}Z`;
}

function BarChartInner<T extends object>(
  {
    data,
    index,
    series,
    label,
    stacked = false,
    height = 240,
    valueFormatter,
    indexFormatter,
    showValues = false,
    showLegend,
    empty,
    className,
    ...props
  }: BarChartProps<T>,
  ref: Ref<HTMLDivElement>,
) {
  const [boxRef, width] = useElementWidth<HTMLDivElement>();
  const { active, setActive, onKeyDown } = useActiveIndex(data.length);
  const fmt = useChartFormat(valueFormatter);
  const xLabel = (d: T) => (indexFormatter ? indexFormatter(d[index]) : String(d[index]));
  const value = (d: T, key: string) => {
    const v = (d as Record<string, unknown>)[key];
    return typeof v === "number" && Number.isFinite(v) ? Math.max(0, v) : 0;
  };
  const colors = series.map((s, i) => slotColor(s.colorSlot, i));
  const legend = showLegend ?? series.length > 1;
  const fmtFor = (s: ChartSeries<T>) => s.format ?? fmt.value;

  const maxV = Math.max(
    0,
    ...data.map((d) =>
      stacked
        ? series.reduce((sum, s) => sum + value(d, s.key), 0)
        : Math.max(0, ...series.map((s) => value(d, s.key))),
    ),
  );
  const ticks = niceTicks(0, maxV || 1);
  const yMax = ticks[ticks.length - 1] ?? 1;
  const tickFmt = series.length === 1 && series[0]?.format ? series[0].format : fmt.tick;
  const start = Math.max(...ticks.map((t) => textWidth(tickFmt(t)))) + 10;
  const plotW = Math.max(0, width - start - M.end);
  const plotH = height - M.top - M.bottom;
  const band = data.length ? plotW / data.length : 0;
  const y = (v: number) => M.top + (1 - v / yMax) * plotH;
  const base = M.top + plotH;
  const groupW = Math.min(
    band * 0.7,
    stacked ? MAX_BAR : MAX_BAR * series.length + GAP * (series.length - 1),
  );
  const barW = stacked ? groupW : Math.max(1, (groupW - GAP * (series.length - 1)) / series.length);
  const xTicks = tickIndices(data.length, plotW, 64);
  const labels = showValues && !stacked && series.length === 1 && band >= 28;

  const activeRow = active !== null ? data[active] : undefined;
  const tipX = active !== null ? start + band * (active + 0.5) : 0;
  const flip = tipX > width / 2;

  return (
    <div ref={ref} className={cn("grid gap-3", className)} {...props}>
      {legend && (
        <ChartLegend
          mark="square"
          items={series.map((s, i) => ({ label: s.label, color: colors[i]! }))}
        />
      )}
      {data.length === 0 ? (
        <div
          className="flex items-center justify-center rounded-md border border-dashed border-border text-sm text-muted-foreground"
          style={{ height }}
        >
          {empty ?? "No data"}
        </div>
      ) : (
        <div
          ref={boxRef}
          dir="ltr"
          // Focusable so keyboard users can walk the points (arrows/Home/End,
          // announced via the live region); screen readers also get the table.
          // eslint-disable-next-line jsx-a11y/no-noninteractive-tabindex
          tabIndex={0}
          role="group"
          aria-roledescription="chart"
          aria-label={label}
          onKeyDown={onKeyDown}
          onBlur={() => setActive(null)}
          className="relative rounded-sm outline-none focus-visible:ring-2 focus-visible:ring-ring"
          style={{ height }}
        >
          {width > 0 && (
            <svg width={width} height={height} aria-hidden className="block overflow-visible">
              {ticks.map((t) => (
                <g key={t}>
                  <line
                    x1={start}
                    x2={start + plotW}
                    y1={y(t)}
                    y2={y(t)}
                    stroke="var(--ui-border)"
                    strokeWidth={1}
                  />
                  <text
                    x={start - 8}
                    y={y(t)}
                    textAnchor="end"
                    dominantBaseline="middle"
                    className="fill-muted-foreground text-[11px] tabular-nums"
                  >
                    {tickFmt(t)}
                  </text>
                </g>
              ))}
              {data.map((d, i) => {
                const left = start + band * i + (band - groupW) / 2;
                let acc = 0;
                const total = series.reduce((sum, s) => sum + value(d, s.key), 0);
                return (
                  <g
                    key={i}
                    onPointerEnter={() => setActive(i)}
                    onPointerDown={() => setActive(i)}
                    onPointerLeave={() => setActive(null)}
                  >
                    {/* Hit target: the whole band, not just the painted bar. */}
                    <rect
                      x={start + band * i}
                      y={M.top}
                      width={band}
                      height={plotH}
                      fill={active === i ? "var(--ui-muted)" : "transparent"}
                      opacity={0.6}
                    />
                    {series.map((s, si) => {
                      const v = value(d, s.key);
                      if (stacked) {
                        const bottom = y(acc) - (acc > 0 ? GAP / 2 : 0);
                        acc += v;
                        const top = y(acc) + (acc < total ? GAP / 2 : 0);
                        return (
                          <path
                            key={s.key}
                            d={column(left, barW, top, bottom, acc >= total)}
                            fill={colors[si]}
                          />
                        );
                      }
                      const bx = left + si * (barW + GAP);
                      return (
                        <path
                          key={s.key}
                          d={column(bx, barW, y(v), base, true)}
                          fill={colors[si]}
                        />
                      );
                    })}
                    {labels && (
                      <text
                        x={left + groupW / 2}
                        y={y(value(d, series[0]!.key)) - 5}
                        textAnchor="middle"
                        className="fill-muted-foreground text-[10px] tabular-nums"
                      >
                        {tickFmt(value(d, series[0]!.key))}
                      </text>
                    )}
                  </g>
                );
              })}
              <line
                x1={start}
                x2={start + plotW}
                y1={base}
                y2={base}
                stroke="var(--ui-border-strong)"
                strokeWidth={1}
              />
              {xTicks.map((i) => (
                <text
                  key={i}
                  x={start + band * (i + 0.5)}
                  y={height - 6}
                  textAnchor="middle"
                  className="fill-muted-foreground text-[11px]"
                >
                  {xLabel(data[i]!)}
                </text>
              ))}
            </svg>
          )}
          {activeRow && (
            <ChartTooltip
              mark="square"
              title={xLabel(activeRow)}
              rows={series.map((s, i) => ({
                label: s.label,
                value: fmtFor(s)(value(activeRow, s.key)),
                color: colors[i]!,
              }))}
              style={{
                top: M.top,
                ...(flip
                  ? { right: width - tipX + groupW / 2 + 8 }
                  : { left: tipX + groupW / 2 + 8 }),
              }}
            />
          )}
          <div aria-live="polite" className="sr-only">
            {activeRow
              ? `${xLabel(activeRow)}: ${series.map((s) => `${s.label} ${fmtFor(s)(value(activeRow, s.key))}`).join(", ")}`
              : ""}
          </div>
        </div>
      )}
      <ChartTable
        caption={label}
        head={[index, ...series.map((s) => s.label)]}
        rows={data.map((d) => [xLabel(d), ...series.map((s) => fmtFor(s)(value(d, s.key)))])}
      />
    </div>
  );
}

