export interface BarListItem {
  /** Stable key; defaults to `name` when it is a string. */
  key?: string;
  name: ReactNode;
  value: number;
  /** Makes the name a link. */
  href?: string;
  /** Overrides the list's slot for this row (e.g. highlight the home market). */
