"use client";
import { useIsomorphicLayoutEffect } from "@ux-sting/hooks";
import { cn, formatCompact, formatNumber } from "@ux-sting/utils";
import { useCallback, useRef, useState, type ReactNode } from "react";
import { useLocale } from "../../provider/context.js";
import type { ChartSeries } from "./chart-utils.js";

export type { ChartSeries };

/*
 * Client pieces shared by the chart family: number formats from the
 * provider locale, width measurement, the legend, the tooltip card, the
 * screen-reader table and keyboard focus. Pure helpers live in chart-utils.
 */

export function useChartFormat(valueFormatter?: (value: number) => string) {
  const { locale } = useLocale();
  return {
    value: valueFormatter ?? ((v: number) => formatNumber(v, locale, { maximumFractionDigits: 2 })),
    tick: valueFormatter ?? ((v: number) => formatCompact(v, locale)),
  };
}

/** Width of the element, measured after layout and on every resize. */
export function useElementWidth<E extends HTMLElement>() {
  const ref = useRef<E>(null);
  const [width, setWidth] = useState(0);
  useIsomorphicLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    setWidth(el.getBoundingClientRect().width);
    if (typeof ResizeObserver === "undefined") return;
    const ro = new ResizeObserver(([entry]) => {
      if (entry) setWidth(entry.contentRect.width);
    });
    ro.observe(el);
    return () => ro.disconnect();
  }, []);
  return [ref, width] as const;
}

export function ChartLegend({
  items,
  mark,
  className,
}: {
  items: { label: string; color: string }[];
  mark: "line" | "square";
  className?: string;
}) {
  return (
    <ul
      className={cn(
        "flex flex-wrap items-center gap-x-4 gap-y-1 text-xs text-muted-foreground",
        className,
      )}
    >
      {items.map((it) => (
        <li key={it.label} className="inline-flex items-center gap-1.5">
          <span
            aria-hidden
            className={mark === "line" ? "h-0.5 w-3 rounded-full" : "size-2.5 rounded-[3px]"}
            style={{ background: it.color }}
          />
          {it.label}
        </li>
      ))}
    </ul>
  );
}

/**
 * Tooltip card. Values lead (strong, foreground) and series names follow
 * (muted), each row keyed by a short stroke of the series color.
 */
export function ChartTooltip({
  title,
  rows,
  style,
  mark = "line",
}: {
  title: ReactNode;
  rows: { label: string; value: string; color: string }[];
  style?: React.CSSProperties;
  mark?: "line" | "square";
}) {
  return (
    <div
      aria-hidden
      className="pointer-events-none absolute z-10 min-w-36 rounded-md border border-border bg-popover px-3 py-2 text-xs text-popover-foreground shadow-md"
      style={style}
    >
      <div className="mb-1 text-muted-foreground">{title}</div>
      <ul className="grid gap-1">
        {rows.map((r) => (
          <li key={r.label} className="flex items-center gap-2">
            <span
              aria-hidden
              className={
                mark === "line"
                  ? "h-0.5 w-2.5 shrink-0 rounded-full"
                  : "size-2 shrink-0 rounded-[2px]"
              }
              style={{ background: r.color }}
            />
            <span className="font-semibold tabular-nums text-foreground">{r.value}</span>
            <span className="truncate text-muted-foreground">{r.label}</span>
          </li>
        ))}
      </ul>
    </div>
  );
}

/** Visually hidden data table: the non-visual (and copyable) view of a chart. */
export function ChartTable({
  caption,
  head,
  rows,
}: {
  caption: string;
  head: string[];
  rows: string[][];
}) {
  return (
    <table className="sr-only">
      <caption>{caption}</caption>
      <thead>
        <tr>
          {head.map((h) => (
            <th key={h} scope="col">
              {h}
            </th>
          ))}
        </tr>
      </thead>
      <tbody>
        {rows.map((r, i) => (
          <tr key={i}>
            {r.map((c, j) =>
              j === 0 ? (
                <th key={j} scope="row">
                  {c}
                </th>
              ) : (
                <td key={j}>{c}</td>
              ),
            )}
          </tr>
        ))}
      </tbody>
    </table>
  );
}

/**
 * Keyboard + pointer focus over an indexed chart: arrows move, Home/End jump,
 * Escape clears. Returns the active index and handlers for the plot element.
 */
export function useActiveIndex(length: number) {
  const [active, setActive] = useState<number | null>(null);
  const onKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      if (length === 0) return;
      const keys: Record<string, (i: number) => number | null> = {
        ArrowRight: (i) => Math.min(length - 1, i + 1),
        ArrowLeft: (i) => Math.max(0, i - 1),
        Home: () => 0,
        End: () => length - 1,
        Escape: () => null,
      };
      const move = keys[e.key];
      if (!move) return;
      e.preventDefault();
      setActive((i) => move(i ?? (e.key === "ArrowLeft" ? length : -1)));
    },
    [length],
  );
  return { active, setActive, onKeyDown };
}

"use client";
import { useControllableState } from "@ux-sting/hooks";
import { TrendingDownIcon, TrendingUpIcon } from "@ux-sting/icons";
import { cn } from "@ux-sting/utils";
import { forwardRef, useRef, type HTMLAttributes, type KeyboardEvent, type ReactNode } from "react";
import { slotColor, type ChartSlot } from "./chart-utils.js";

export interface ChartMetric {
  key: string;
  label: ReactNode;
  /** The headline figure for the period, already formatted. */
  value: ReactNode;
  /** Change vs the previous period, e.g. "+12.4%". */
  delta?: ReactNode;
  /** Direction of the change. */
  trend?: "up" | "down" | "neutral";
  /** Whether "up" is good (clicks) or bad (average position). */
  trendMeaning?: "positive-up" | "positive-down";
  /** Color of the plotted line when this metric is selected. */
  colorSlot?: ChartSlot;
}

export interface ChartMetricsProps extends Omit<
  HTMLAttributes<HTMLDivElement>,
  "defaultValue" | "onChange"
> {
  metrics: ChartMetric[];
  value?: string;
  defaultValue?: string;
  onValueChange?: (key: string) => void;
  /** Accessible name for the picker, e.g. "Metric". */
  label: string;
}

/**
 * Row of metric tiles that picks what the chart below plots (the Search
 * Console pattern). Exactly one metric is plotted at a time, so the chart
 * keeps one y axis. A radio group: arrow keys move and select; the selected
 * tile carries the series color as a top rule, and its figure and delta stay
 * in text colors.
 */
export const ChartMetrics = forwardRef<HTMLDivElement, ChartMetricsProps>(function ChartMetrics(
  { metrics, value: valueProp, defaultValue, onValueChange, label, className, ...props },
  ref,
) {
  const [value, setValue] = useControllableState({
    value: valueProp,
    defaultValue: defaultValue ?? metrics[0]?.key ?? "",
    onChange: onValueChange,
  });
  const buttons = useRef<(HTMLButtonElement | null)[]>([]);

  const onKeyDown = (e: KeyboardEvent, i: number) => {
    const n = metrics.length;
    const next =
      e.key === "ArrowRight" || e.key === "ArrowDown"
        ? (i + 1) % n
        : e.key === "ArrowLeft" || e.key === "ArrowUp"
          ? (i - 1 + n) % n
          : e.key === "Home"
            ? 0
            : e.key === "End"
              ? n - 1
              : null;
    if (next === null) return;
    e.preventDefault();
    setValue(metrics[next]!.key);
    buttons.current[next]?.focus();
  };

  return (
    <div
      ref={ref}
      role="radiogroup"
      aria-label={label}
      className={cn(
        "grid grid-cols-2 gap-2 sm:grid-cols-[repeat(auto-fit,minmax(9rem,1fr))]",
        className,
      )}
      {...props}
    >
      {metrics.map((m, i) => {
        const on = m.key === value;
        const good =
          !m.trend || m.trend === "neutral"
            ? null
            : (m.trend === "up") === ((m.trendMeaning ?? "positive-up") === "positive-up");
        return (
          <button
            key={m.key}
            ref={(el) => {
              buttons.current[i] = el;
            }}
            type="button"
            role="radio"
            aria-checked={on}
            tabIndex={on ? 0 : -1}
            onClick={() => setValue(m.key)}
            onKeyDown={(e) => onKeyDown(e, i)}
            className={cn(
              "relative grid gap-1 overflow-hidden rounded-md border px-3 pb-2.5 pt-3 text-start outline-none transition-colors",
              "focus-visible:ring-2 focus-visible:ring-ring",
              on
                ? "border-border-strong bg-card shadow-xs"
                : "border-border bg-transparent hover:bg-muted/60",
            )}
          >
            <span
              aria-hidden
              className="absolute inset-x-0 top-0 h-[3px] transition-opacity"
              style={{ background: slotColor(m.colorSlot, i), opacity: on ? 1 : 0 }}
            />
            <span className="text-xs font-medium text-muted-foreground">{m.label}</span>
            <span className="text-xl font-semibold tracking-tight text-foreground">{m.value}</span>
            {m.delta ? (
              <span
                className={cn(
                  "inline-flex items-center gap-1 text-xs font-medium tabular-nums [&_svg]:size-3.5",
                  good === null
                    ? "text-muted-foreground"
                    : good
                      ? "text-success-subtle-foreground"
                      : "text-destructive-subtle-foreground",
                )}
              >
                {m.trend === "up" ? (
                  <TrendingUpIcon aria-hidden />
                ) : m.trend === "down" ? (
                  <TrendingDownIcon aria-hidden />
                ) : null}
                {m.delta}
              </span>
            ) : null}
          </button>
        );
      })}
    </div>
  );
});

/*
 * Pure helpers of the chart family (no hooks, server-safe), shared by the
 * client charts in chart-core.tsx and the server-safe Sparkline.
 *
 * Color rules (see --ui-chart-* in @ux-sting/tokens): series take the eight
 * categorical slots in order and are never cycled; a series past the eighth
 * renders in the muted ink, so callers fold extras into "Other". Text never
 * wears a series color: legends, ticks and tooltips use text tokens and key
 * the series with a colored mark beside the text.
 */

/** Categorical slot 1–8, or `"muted"` for an "Other"/baseline series. */
export type ChartSlot = 1 | 2 | 3 | 4 | 5 | 6 | 7 | 8 | "muted";

export interface ChartSeries<T> {
  /** Field of each datum that holds this series' numeric value. */
  key: Extract<keyof T, string>;
  label: string;
  /**
   * Categorical color slot. Defaults to the series' position (1, 2, …). Pin
   * it when a filter can hide series, so survivors keep their color.
   */
  colorSlot?: ChartSlot;
  /** Per-series value format (tooltip, table, ticks when it is the only series). */
  format?: (value: number) => string;
}

export function slotColor(slot: ChartSlot | undefined, index: number): string {
  const s = slot ?? (index < 8 ? ((index + 1) as ChartSlot) : "muted");
  return s === "muted" ? "var(--ui-muted-foreground)" : `var(--ui-chart-${s})`;
}

/** 0, 1, 2, 2.5 or 5 × 10ⁿ steps covering [min, max] in about `count` ticks. */
export function niceTicks(min: number, max: number, count = 4): number[] {
  if (!Number.isFinite(min) || !Number.isFinite(max)) return [0];
  if (min === max) {
    if (min === 0) return [0, 1];
    const pad = Math.abs(min) * 0.1;
    min -= pad;
    max += pad;
  }
  const raw = (max - min) / Math.max(count, 1);
  const mag = 10 ** Math.floor(Math.log10(raw));
  const step = ([1, 2, 2.5, 5, 10].find((m) => m * mag >= raw) ?? 10) * mag;
  const start = Math.floor(min / step) * step;
  const end = Math.ceil(max / step) * step;
  const ticks: number[] = [];
  for (let v = start; v <= end + step / 2; v += step) ticks.push(Number(v.toFixed(10)));
  return ticks;
}

/** Evenly spaced subset of indices that fits `width` at ~`minGap`px per label. */
export function tickIndices(length: number, width: number, minGap = 72): number[] {
  if (length === 0) return [];
  const fit = Math.max(1, Math.floor(width / minGap));
  if (length <= fit) return Array.from({ length }, (_, i) => i);
  const step = Math.ceil((length - 1) / (fit - 1 || 1));
  const out: number[] = [];
  for (let i = 0; i < length; i += step) out.push(i);
  if (out[out.length - 1] !== length - 1) {
    // Keep the last label (the latest value) and drop the one it would crowd.
    if (length - 1 - (out[out.length - 1] ?? 0) < step / 2) out.pop();
    out.push(length - 1);
  }
  return out;
}

/** Rough text width for axis labels at 11px (avoids measuring the DOM). */
export const textWidth = (s: string) => s.length * 6.4;

"use client";
import { cn } from "@ux-sting/utils";
import { forwardRef, useState, type HTMLAttributes, type ReactNode } from "react";
import { ChartTable, useChartFormat } from "./chart-core.js";
import { slotColor, type ChartSlot } from "./chart-utils.js";

export interface DonutChartItem {
  key?: string;
  name: string;
  value: number;
  colorSlot?: ChartSlot;
}

export interface DonutChartProps extends Omit<HTMLAttributes<HTMLDivElement>, "children"> {
  data: DonutChartItem[];
  /** Accessible name, e.g. "Sessions by device". */
  label: string;
  valueFormatter?: (value: number) => string;
  /** Text in the hole; defaults to the formatted total. */
  center?: ReactNode;
  /** Small caption under the center value. */
  centerLabel?: ReactNode;
  /** Diameter in px. */
  size?: number;
}

const TAU = Math.PI * 2;

function arc(cx: number, cy: number, r0: number, r1: number, a0: number, a1: number) {
  const large = a1 - a0 > Math.PI ? 1 : 0;
  const p = (r: number, a: number) =>
    `${(cx + r * Math.sin(a)).toFixed(2)},${(cy - r * Math.cos(a)).toFixed(2)}`;
  return `M${p(r1, a0)}A${r1},${r1} 0 ${large} 1 ${p(r1, a1)}L${p(r0, a1)}A${r0},${r0} 0 ${large} 0 ${p(r0, a0)}Z`;
}

/**
 * Parts of a whole, for a handful of categories (≤ 5 reads best; fold the
 * rest into "Other"). Slices are split by a 2px surface gap, and a legend
 * with values and shares sits beside the ring, so identity never relies on
 * color alone.
 */
export const DonutChart = forwardRef<HTMLDivElement, DonutChartProps>(function DonutChart(
  { data, label, valueFormatter, center, centerLabel, size = 128, className, ...props },
  ref,
) {
  const fmt = useChartFormat(valueFormatter);
  const [active, setActive] = useState<number | null>(null);
  const total = data.reduce((s, d) => s + Math.max(0, d.value), 0);
  const r1 = size / 2;
  const r0 = r1 * 0.66;
  let a = 0;
  const slices = data.map((d, i) => {
    const sweep = total > 0 ? (Math.max(0, d.value) / total) * TAU : 0;
    const s = { d, i, a0: a, a1: a + sweep, color: slotColor(d.colorSlot, i) };
    a += sweep;
    return s;
  });
  const shown = active !== null ? data[active] : undefined;

  return (
    <div ref={ref} className={cn("flex flex-wrap items-center gap-6", className)} {...props}>
      <div className="relative shrink-0" style={{ width: size, height: size }}>
        <svg width={size} height={size} role="img" aria-label={label} className="block">
          {total === 0 ? (
            <circle
              cx={r1}
              cy={r1}
              r={(r0 + r1) / 2}
              fill="none"
              stroke="var(--ui-muted)"
              strokeWidth={r1 - r0}
            />
          ) : (
            slices.map((s) =>
              s.a1 - s.a0 >= TAU - 1e-6 ? (
                <circle
                  key={s.i}
                  cx={r1}
                  cy={r1}
                  r={(r0 + r1) / 2}
                  fill="none"
                  stroke={s.color}
                  strokeWidth={r1 - r0}
                />
              ) : s.a1 > s.a0 ? (
                <path
                  key={s.i}
                  d={arc(r1, r1, r0, r1, s.a0, s.a1)}
                  fill={s.color}
                  stroke="var(--ui-card)"
                  strokeWidth={2}
                  strokeLinejoin="round"
                  opacity={active === null || active === s.i ? 1 : 0.45}
                  onPointerEnter={() => setActive(s.i)}
                  onPointerLeave={() => setActive(null)}
                />
              ) : null,
            )
          )}
        </svg>
        <div className="pointer-events-none absolute inset-0 flex flex-col items-center justify-center text-center">
          <span className="text-base font-semibold tabular-nums text-foreground">
            {shown ? fmt.value(shown.value) : (center ?? fmt.value(total))}
          </span>
          <span className="max-w-[70%] truncate text-[11px] text-muted-foreground">
            {shown ? shown.name : centerLabel}
          </span>
        </div>
      </div>
      <ul className="grid min-w-40 flex-1 gap-1.5 text-sm">
        {slices.map((s) => (
          <li
            key={s.d.key ?? s.d.name}
            className="flex items-center gap-2"
            onPointerEnter={() => setActive(s.i)}
            onPointerLeave={() => setActive(null)}
          >
            <span
              aria-hidden
              className="size-2.5 shrink-0 rounded-[3px]"
              style={{ background: s.color }}
            />
            <span className="min-w-0 flex-1 truncate text-foreground">{s.d.name}</span>
            <span className="font-medium tabular-nums text-foreground">{fmt.value(s.d.value)}</span>
            <span className="w-12 text-end text-xs tabular-nums text-muted-foreground">
              {total > 0 ? `${((s.d.value / total) * 100).toFixed(1)}%` : "—"}
            </span>
          </li>
        ))}
      </ul>
      <ChartTable
        caption={label}
        head={["Category", "Value", "Share"]}
        rows={data.map((d) => [
          d.name,
          fmt.value(d.value),
          total > 0 ? `${((d.value / total) * 100).toFixed(1)}%` : "—",
        ])}
      />
    </div>
  );
});

export * from "./chart-utils.js";
export { ChartLegend, ChartTooltip, ChartTable } from "./chart-core.js";
export * from "./line-chart.js";
export * from "./bar-chart.js";
export * from "./bar-list.js";
export * from "./donut-chart.js";
export * from "./sparkline.js";
export * from "./chart-metrics.js";

"use client";
import { cn } from "@ux-sting/utils";
import { forwardRef, useId, type HTMLAttributes, type ReactNode, type Ref } from "react";
import {
  ChartLegend,
  ChartTable,
  ChartTooltip,
  useActiveIndex,
  useChartFormat,
  useElementWidth,
} from "./chart-core.js";
import { niceTicks, slotColor, textWidth, tickIndices, type ChartSeries } from "./chart-utils.js";

export interface LineChartProps<T extends object> extends Omit<
  HTMLAttributes<HTMLDivElement>,
  "children"
> {
  data: T[];
  /** Field holding each datum's x value (a date string, a label…). */
  index: Extract<keyof T, string>;
  series: ChartSeries<T>[];
  /** Accessible name: what the chart shows, e.g. "Clicks per day". */
  label: string;
  /** Adds a ~10% wash under each line. */
  area?: boolean;
  /** Plot height in px (legend excluded). */
  height?: number;
  valueFormatter?: (value: number) => string;
  /** Formats x values for ticks, tooltip titles and the table. */
  indexFormatter?: (value: T[Extract<keyof T, string>]) => string;
  /** Draw the y axis upside down (rank / position charts: 1 at the top). */
  reversed?: boolean;
  /** Start the y axis at zero (default) or fit it to the data. */
  zeroBaseline?: boolean;
  /** Legend above the plot; defaults to on for two or more series. */
  showLegend?: boolean;
  /** Shown instead of the plot when `data` is empty. */
  empty?: ReactNode;
}

const M = { top: 10, end: 12, bottom: 26 };

function LineChartInner<T extends object>(
  {
    data,
    index,
    series,
    label,
    area = false,
    height = 240,
    valueFormatter,
    indexFormatter,
    reversed = false,
    zeroBaseline = true,
    showLegend,
    empty,
    className,
    ...props
  }: LineChartProps<T>,
  ref: Ref<HTMLDivElement>,
) {
  const [boxRef, width] = useElementWidth<HTMLDivElement>();
  const { active, setActive, onKeyDown } = useActiveIndex(data.length);
  const fmt = useChartFormat(valueFormatter);
  const gradientId = useId();
  const xLabel = (d: T) => (indexFormatter ? indexFormatter(d[index]) : String(d[index]));
  const value = (d: T, key: string) => {
    const v = (d as Record<string, unknown>)[key];
    return typeof v === "number" && Number.isFinite(v) ? v : null;
  };
  const colors = series.map((s, i) => slotColor(s.colorSlot, i));
  const legend = showLegend ?? series.length > 1;

  const all = data.flatMap((d) =>
    series.map((s) => value(d, s.key)).filter((v): v is number => v !== null),
  );
  const lo = all.length ? Math.min(...all) : 0;
  const hi = all.length ? Math.max(...all) : 1;
  const ticks = niceTicks(zeroBaseline ? Math.min(0, lo) : lo, zeroBaseline ? Math.max(0, hi) : hi);
  const yMin = ticks[0] ?? 0;
  const yMax = ticks[ticks.length - 1] ?? 1;
  const tickFmt = series.length === 1 && series[0]?.format ? series[0].format : fmt.tick;
  const start = Math.max(...ticks.map((t) => textWidth(tickFmt(t)))) + 10;
  const plotW = Math.max(0, width - start - M.end);
  const plotH = height - M.top - M.bottom;
  const x = (i: number) => start + (data.length <= 1 ? plotW / 2 : (i / (data.length - 1)) * plotW);
  const y = (v: number) => {
    const t = (v - yMin) / (yMax - yMin || 1);
    return M.top + (reversed ? t : 1 - t) * plotH;
  };
  const baseY = reversed ? M.top : M.top + plotH;

  const pathFor = (key: string) => {
    let d = "";
    let pen = false;
    data.forEach((row, i) => {
      const v = value(row, key);
      if (v === null) {
        pen = false;
        return;
      }
      d += `${pen ? "L" : "M"}${x(i).toFixed(1)},${y(v).toFixed(1)}`;
      pen = true;
    });
    return d;
  };

  const xTicks = tickIndices(data.length, plotW, 80);
  const onPointer = (e: React.PointerEvent<SVGRectElement>) => {
    const rect = e.currentTarget.getBoundingClientRect();
    const px = e.clientX - rect.left;
    const i = data.length <= 1 ? 0 : Math.round((px / rect.width) * (data.length - 1));
    setActive(Math.max(0, Math.min(data.length - 1, i)));
  };

  const activeRow = active !== null ? data[active] : undefined;
  const tipLeft = active !== null ? x(active) : 0;
  const flip = tipLeft > width / 2;
  const fmtFor = (s: ChartSeries<T>) => s.format ?? fmt.value;

  return (
    <div ref={ref} className={cn("grid gap-3", className)} {...props}>
      {legend && (
        <ChartLegend
          mark="line"
          items={series.map((s, i) => ({ label: s.label, color: colors[i]! }))}
        />
      )}
      {data.length === 0 ? (
        <div
          className="flex items-center justify-center rounded-md border border-dashed border-border text-sm text-muted-foreground"
          style={{ height }}
        >
          {empty ?? "No data"}
        </div>
      ) : (
        <div
          ref={boxRef}
          dir="ltr"
          // Focusable so keyboard users can walk the points (arrows/Home/End,
          // announced via the live region); screen readers also get the table.
          // eslint-disable-next-line jsx-a11y/no-noninteractive-tabindex
          tabIndex={0}
          role="group"
          aria-roledescription="chart"
          aria-label={label}
          onKeyDown={onKeyDown}
          onBlur={() => setActive(null)}
          className="relative rounded-sm outline-none focus-visible:ring-2 focus-visible:ring-ring"
          style={{ height }}
        >
          {width > 0 && (
            <svg width={width} height={height} aria-hidden className="block overflow-visible">
              {area && (
                <defs>
                  {series.map((s, i) => (
                    <linearGradient
                      key={s.key}
                      id={`${gradientId}-${i}`}
                      x1="0"
                      x2="0"
                      y1="0"
                      y2="1"
                    >
                      <stop offset="0%" stopColor={colors[i]} stopOpacity={0.14} />
                      <stop offset="100%" stopColor={colors[i]} stopOpacity={0.02} />
                    </linearGradient>
                  ))}
                </defs>
              )}
              {ticks.map((t) => (
                <g key={t}>
                  <line
                    x1={start}
                    x2={start + plotW}
                    y1={y(t)}
                    y2={y(t)}
                    stroke="var(--ui-border)"
                    strokeWidth={1}
                  />
                  <text
                    x={start - 8}
                    y={y(t)}
                    textAnchor="end"
                    dominantBaseline="middle"
                    className="fill-muted-foreground text-[11px] tabular-nums"
                  >
                    {tickFmt(t)}
                  </text>
                </g>
              ))}
              {xTicks.map((i) => (
                <text
                  key={i}
                  x={x(i)}
                  y={height - 6}
                  textAnchor={
                    i === 0 && data.length > 1
                      ? "start"
                      : i === data.length - 1 && data.length > 1
                        ? "end"
                        : "middle"
                  }
                  className="fill-muted-foreground text-[11px]"
                >
                  {xLabel(data[i]!)}
                </text>
              ))}
              {area &&
                series.map((s, i) => {
                  const d = pathFor(s.key);
                  if (!d) return null;
                  const first = data.findIndex((row) => value(row, s.key) !== null);
                  const last =
                    data.length -
                    1 -
                    [...data].reverse().findIndex((row) => value(row, s.key) !== null);
                  return (
                    <path
                      key={s.key}
                      d={`${d}L${x(last).toFixed(1)},${baseY}L${x(first).toFixed(1)},${baseY}Z`}
                      fill={`url(#${gradientId}-${i})`}
                    />
                  );
                })}
              {series.map((s, i) => (
                <path
                  key={s.key}
                  d={pathFor(s.key)}
                  fill="none"
                  stroke={colors[i]}
                  strokeWidth={2}
                  strokeLinejoin="round"
                  strokeLinecap="round"
                />
              ))}
              {active !== null && (
                <line
                  x1={x(active)}
                  x2={x(active)}
                  y1={M.top}
                  y2={M.top + plotH}
                  stroke="var(--ui-border-strong)"
                  strokeWidth={1}
                />
              )}
              {series.map((s, i) => {
                // End dot on the latest value; the active point when hovering.
                const at = active ?? data.length - 1;
                const v = value(data[at]!, s.key);
                if (v === null || (active === null && data.length < 2)) return null;
                return (
                  <circle
                    key={s.key}
                    cx={x(at)}
                    cy={y(v)}
                    r={4}
                    fill={colors[i]}
                    stroke="var(--ui-card)"
                    strokeWidth={2}
                  />
                );
              })}
              <rect
                x={start}
                y={0}
                width={plotW}
                height={height}
                fill="transparent"
                onPointerMove={onPointer}
                onPointerDown={onPointer}
                onPointerLeave={() => setActive(null)}
              />
            </svg>
          )}
          {activeRow && (
            <ChartTooltip
              title={xLabel(activeRow)}
              rows={series.flatMap((s, i) => {
                const v = value(activeRow, s.key);
                return v === null
                  ? []
                  : [{ label: s.label, value: fmtFor(s)(v), color: colors[i]! }];
              })}
              style={{
                top: M.top,
                ...(flip ? { right: width - tipLeft + 12 } : { left: tipLeft + 12 }),
              }}
            />
          )}
          <div aria-live="polite" className="sr-only">
            {activeRow
              ? `${xLabel(activeRow)}: ${series
                  .map((s) => {
                    const v = value(activeRow, s.key);
                    return `${s.label} ${v === null ? "—" : fmtFor(s)(v)}`;
                  })
                  .join(", ")}`
              : ""}
          </div>
        </div>
      )}
      <ChartTable
        caption={label}
        head={[index, ...series.map((s) => s.label)]}
        rows={data.map((d) => [
          xLabel(d),
          ...series.map((s) => {
            const v = value(d, s.key);
            return v === null ? "—" : fmtFor(s)(v);
          }),
        ])}
      />
    </div>
  );
}

/**
 * Line chart for change over time: 2px lines on one y axis, hairline grid,
 * a crosshair that snaps to the nearest x with one tooltip for every series,
 * arrow-key navigation, and a visually hidden data table. Up to eight series
 * in the categorical chart colors; never two y scales. Set `area` for a wash
 * under the lines (an area chart).
 */
export const LineChart = forwardRef(LineChartInner) as unknown as <T extends object>(
  props: LineChartProps<T> & { ref?: Ref<HTMLDivElement> },
) => ReturnType<typeof LineChartInner>;

/** `LineChart` with `area` on. */
export const AreaChart = forwardRef(function AreaChart<T extends object>(
  props: LineChartProps<T>,
  ref: Ref<HTMLDivElement>,
) {
  return <LineChart ref={ref} area {...props} />;
}) as unknown as <T extends object>(
  props: LineChartProps<T> & { ref?: Ref<HTMLDivElement> },
) => ReturnType<typeof LineChartInner>;

import { cn } from "@ux-sting/utils";
import { forwardRef, type SVGAttributes } from "react";
import { slotColor, type ChartSlot } from "./chart-utils.js";

export interface SparklineProps extends Omit<SVGAttributes<SVGSVGElement>, "children"> {
  data: number[];
  /** Accessible name, e.g. "Clicks, last 28 days". */
  label: string;
  /** Categorical slot, or `"muted"` for the de-emphasis ink (default 1). */
  colorSlot?: ChartSlot;
  /** Adds a ~10% wash under the line. */
  area?: boolean;
  /** Marks the latest value with a dot. */
  showEnd?: boolean;
}

/**
 * Word-sized trend line for stat tiles and table cells. No axes and no
 * hover: pair it with the figure it summarizes. Scales to its box (set the
 * size with `className`, default 100% × 32px).
 */
export const Sparkline = forwardRef<SVGSVGElement, SparklineProps>(function Sparkline(
  { data, label, colorSlot = 1, area = true, showEnd = true, className, ...props },
  ref,
) {
  const w = 100;
  const h = 32;
  const color = slotColor(colorSlot, 0);
  if (data.length < 2) {
    return (
      <svg
        ref={ref}
        role="img"
        aria-label={label}
        className={cn("h-8 w-full", className)}
        {...props}
      />
    );
  }
  const max = Math.max(...data);
  const min = Math.min(...data);
  const span = max - min || 1;
  const pts = data.map(
    (v, i) => [(i / (data.length - 1)) * w, h - 3 - ((v - min) / span) * (h - 6)] as const,
  );
  const line = pts.map(([x, y], i) => `${i ? "L" : "M"}${x.toFixed(2)},${y.toFixed(2)}`).join("");
  const last = pts[pts.length - 1]!;
  return (
    <svg
      ref={ref}
      viewBox={`0 0 ${w} ${h}`}
      preserveAspectRatio="none"
      role="img"
      aria-label={label}
      className={cn("h-8 w-full overflow-visible", className)}
      {...props}
    >
      {area && <path d={`${line}L${w},${h}L0,${h}Z`} fill={color} opacity={0.1} />}
      <path
        d={line}
        fill="none"
        stroke={color}
        strokeWidth={1.5}
        strokeLinejoin="round"
        strokeLinecap="round"
        vectorEffect="non-scaling-stroke"
      />
      {showEnd && (
        <line
          x1={last[0]}
          y1={last[1]}
          x2={last[0]}
          y2={last[1]}
          stroke={color}
          strokeWidth={6}
          strokeLinecap="round"
          vectorEffect="non-scaling-stroke"
        />
      )}
    </svg>
  );
});

import { cn } from "@ux-sting/utils";
