"use client";
import { useInterval, usePrefersReducedMotion } from "@ux-sting/hooks";
import { ChevronLeftIcon, ChevronRightIcon, PauseIcon, PlayIcon } from "@ux-sting/icons";
import { cn } from "@ux-sting/utils";
import {
  Children,
  createContext,
  forwardRef,
  isValidElement,
  useCallback,
  useContext,
  useEffect,
  useRef,
  useState,
  type ButtonHTMLAttributes,
  type HTMLAttributes,
  type KeyboardEvent,
  type RefObject,
} from "react";
import { useMessages } from "../../provider/context.js";

interface CarouselContextValue {
  index: number;
  count: number;
  setCount: (n: number) => void;
  scrollTo: (i: number) => void;
  trackRef: RefObject<HTMLDivElement | null>;
  playing: boolean;
  setPlaying: (v: boolean) => void;
  autoplay: boolean;
  loop: boolean;
  setIndex: (i: number) => void;
}

const CarouselContext = createContext<CarouselContextValue | null>(null);

function useCarousel() {
  const ctx = useContext(CarouselContext);
  if (!ctx) throw new Error("Carousel parts must be used inside <Carousel>.");
  return ctx;
}

export interface CarouselProps extends HTMLAttributes<HTMLElement> {
  /** Auto-advance interval in ms. Pauses on hover, focus and reduced motion. */
  autoplay?: number | false;
  loop?: boolean;
  /** Accessible name of the carousel. */
  label?: string;
}

/**
 * Scroll-snap carousel: native touch scrolling, keyboard arrows, visible
 * previous/next controls (swipe is never required) and pausable autoplay.
 */
export const Carousel = forwardRef<HTMLElement, CarouselProps>(function Carousel(
  { autoplay = false, loop = true, label, className, children, onKeyDown, ...props },
  ref,
) {
  const messages = useMessages();
  const trackRef = useRef<HTMLDivElement>(null);
  const [index, setIndex] = useState(0);
  const [count, setCount] = useState(0);
  const reducedMotion = usePrefersReducedMotion();
  const [playing, setPlaying] = useState(Boolean(autoplay) && !reducedMotion);
  const [hovered, setHovered] = useState(false);

  useEffect(() => {
    if (reducedMotion) setPlaying(false);
  }, [reducedMotion]);

  const scrollTo = useCallback(
    (i: number) => {
      const track = trackRef.current;
      if (!track || count === 0) return;
      const target = loop ? (i + count) % count : Math.max(0, Math.min(count - 1, i));
      const slide = track.children[target] as HTMLElement | undefined;
      if (slide) {
        const delta = slide.getBoundingClientRect().left - track.getBoundingClientRect().left;
        track.scrollBy({ left: delta, behavior: reducedMotion ? "auto" : "smooth" });
      }
      setIndex(target);
    },
    [count, loop, reducedMotion],
  );

  useInterval(() => scrollTo(index + 1), autoplay && playing && !hovered ? autoplay : null);

  const handleKeyDown = (e: KeyboardEvent<HTMLElement>) => {
    onKeyDown?.(e);
    const rtl = getComputedStyle(e.currentTarget).direction === "rtl";
    if (e.key === (rtl ? "ArrowLeft" : "ArrowRight")) {
      e.preventDefault();
      scrollTo(index + 1);
    } else if (e.key === (rtl ? "ArrowRight" : "ArrowLeft")) {
      e.preventDefault();
      scrollTo(index - 1);
    }
  };

  return (
    <CarouselContext.Provider
      value={{
        index,
        count,
        setCount,
        scrollTo,
        trackRef,
        playing,
        setPlaying,
        autoplay: Boolean(autoplay),
        loop,
        setIndex,
      }}
    >
      <section
        ref={ref}
        aria-roledescription="carousel"
        aria-label={label ?? messages.carousel}
        onKeyDown={handleKeyDown}
        onPointerEnter={() => setHovered(true)}
        onPointerLeave={() => setHovered(false)}
        onFocus={() => setHovered(true)}
        onBlur={(e) => !e.currentTarget.contains(e.relatedTarget as Node) && setHovered(false)}
        className={cn("relative min-w-0", className)}
        {...props}
      >
        {children}
      </section>
    </CarouselContext.Provider>
  );
});

export const CarouselContent = forwardRef<
  HTMLDivElement,
  HTMLAttributes<HTMLDivElement> & {
    /** Items per view on large screens; phones show one (with a peek), tablets two. */
    itemsPerView?: 1 | 2 | 3 | 4;
  }
>(function CarouselContent({ itemsPerView = 1, className, children, ...props }, ref) {
  const { trackRef, setCount, setIndex, playing, autoplay } = useCarousel();
  const count = Children.toArray(children).filter(isValidElement).length;
  useEffect(() => setCount(count), [count, setCount]);

  useEffect(() => {
    const track = trackRef.current;
    if (!track || typeof IntersectionObserver === "undefined") return;
    const observer = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          if (entry.isIntersecting) setIndex(Array.from(track.children).indexOf(entry.target));
        }
      },
      { root: track, threshold: 0.6 },
    );
    Array.from(track.children).forEach((c) => observer.observe(c));
    return () => observer.disconnect();
  }, [trackRef, setIndex, count]);

  return (
    <div
      ref={(node) => {
        trackRef.current = node;
        if (typeof ref === "function") ref(node);
        else if (ref) ref.current = node;
      }}
      aria-live={autoplay && playing ? "off" : "polite"}
      // The scroll container must be keyboard-reachable (WCAG 2.1.1); arrows are handled by Carousel.
      // eslint-disable-next-line jsx-a11y/no-noninteractive-tabindex
      tabIndex={0}
      className={cn(
        "ui-scroll-snap flex gap-4 overflow-x-auto rounded-lg outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2",
        // Multi-item carousels stay readable on phones: one item plus a peek of
        // the next, then two per view from `sm`, and the full count from `lg`.
        itemsPerView > 1 && "[&>*]:basis-[85%] sm:[&>*]:basis-[calc((100%-1rem)/2)]",
        itemsPerView === 3 && "lg:[&>*]:basis-[calc((100%-2rem)/3)]",
        itemsPerView === 4 && "lg:[&>*]:basis-[calc((100%-3rem)/4)]",
        className,
      )}
      {...props}
    >
      {children}
    </div>
  );
});

export const CarouselItem = forwardRef<
  HTMLDivElement,
  HTMLAttributes<HTMLDivElement> & { index?: number }
>(function CarouselItem({ index, className, ...props }, ref) {
  const { count } = useCarousel();
  const messages = useMessages();
  return (
    <div
      ref={ref}
      role="group"
      aria-roledescription="slide"
      aria-label={index !== undefined ? messages.slideOf(index + 1, count) : undefined}
      // Items are equal height: the item stretches with the track and its content fills it.
      className={cn("flex min-w-0 shrink-0 grow-0 basis-full flex-col *:flex-1", className)}
      {...props}
    />
  );
});

const navClass =
  "ui-hit-area absolute top-1/2 z-10 inline-flex size-9 -translate-y-1/2 items-center justify-center rounded-full border border-border bg-background/90 text-foreground shadow-md outline-none backdrop-blur transition-opacity hover:bg-background focus-visible:ring-2 focus-visible:ring-ring disabled:opacity-0 [&_svg]:size-4 rtl:[&_svg]:rotate-180";

export function CarouselPrevious({ className, ...props }: ButtonHTMLAttributes<HTMLButtonElement>) {
  const { index, scrollTo, loop } = useCarousel();
  const messages = useMessages();
  return (
    <button
      type="button"
      aria-label={messages.previous}
      disabled={!loop && index === 0}
      onClick={() => scrollTo(index - 1)}
      className={cn(navClass, "start-2", className)}
      {...props}
    >
      <ChevronLeftIcon />
    </button>
  );
}

export function CarouselNext({ className, ...props }: ButtonHTMLAttributes<HTMLButtonElement>) {
  const { index, count, scrollTo, loop } = useCarousel();
  const messages = useMessages();
  return (
    <button
      type="button"
      aria-label={messages.next}
      disabled={!loop && index >= count - 1}
      onClick={() => scrollTo(index + 1)}
      className={cn(navClass, "end-2", className)}
      {...props}
    >
      <ChevronRightIcon />
    </button>
  );
}

/** Slide picker dots; each dot is a labelled button. */
export function CarouselDots({ className }: { className?: string }) {
  const { index, count, scrollTo } = useCarousel();
  const messages = useMessages();
  return (
    <div className={cn("mt-3 flex justify-center", className)}>
      {Array.from({ length: count }, (_, i) => (
        // The button is the full 24px target (WCAG 2.5.8) with no overlap
        // between neighbours; the dot inside is only the visual.
        <button
          key={i}
          type="button"
          aria-label={messages.slideOf(i + 1, count)}
          aria-current={i === index ? "true" : undefined}
          onClick={() => scrollTo(i)}
          className="group/dot inline-flex h-6 min-w-6 items-center justify-center rounded-full px-1 outline-none focus-visible:ring-2 focus-visible:ring-ring"
        >
          <span
            aria-hidden="true"
            className="h-2 w-2 rounded-full bg-border-strong transition-[width,background-color] group-aria-[current=true]/dot:w-5 group-aria-[current=true]/dot:bg-primary"
          />
        </button>
      ))}
    </div>
  );
}

/** Play/pause control required for auto-advancing content (WCAG 2.2.2). */
export function CarouselPlayToggle({ className }: { className?: string }) {
  const { playing, setPlaying, autoplay } = useCarousel();
  const messages = useMessages();
  if (!autoplay) return null;
  return (
    <button
      type="button"
      aria-label={playing ? messages.pauseAutoplay : messages.playAutoplay}
      onClick={() => setPlaying(!playing)}
      className={cn(
        "ui-hit-area inline-flex size-8 items-center justify-center rounded-full border border-border bg-background/90 shadow-sm outline-none focus-visible:ring-2 focus-visible:ring-ring [&_svg]:size-3.5",
        className,
      )}
    >
      {playing ? <PauseIcon /> : <PlayIcon />}
    </button>
  );
}

"use client";
import { cn } from "@ux-sting/utils";
import { useState } from "react";
import { Image } from "./image.js";
import { Lightbox, type LightboxImage } from "./lightbox.js";

export interface ImageGalleryProps {
  images: LightboxImage[];
  /** Grid columns on ≥ sm screens. */
  columns?: 2 | 3 | 4;
  /**
   * `mosaic` shows one large image plus groups of four (four columns from
   * `sm`), so the grid never has gaps; extra images go behind the "+n" tile.
   * With fewer than five images it falls back to `grid`.
   */
  layout?: "grid" | "mosaic";
  ratio?: number;
  className?: string;
  /** Maximum thumbnails shown; the last one shows "+n". */
  max?: number;
}

/** Thumbnail grid that opens a Lightbox. Each thumbnail is a button. */
export function ImageGallery({
  images,
  columns = 3,
  layout = "grid",
  ratio = 4 / 3,
  className,
  max,
}: ImageGalleryProps) {
  const [open, setOpen] = useState(false);
  const [index, setIndex] = useState(0);
  const limit = Math.min(max ?? images.length, images.length);
  const mosaic = layout === "mosaic" && limit >= 5;
  // Mosaic: 1 large (2×2) + multiples of 4 small tiles fill 2 and 4 columns exactly.
  const count = mosaic ? 1 + Math.floor((limit - 1) / 4) * 4 : limit;
  const shown = images.slice(0, count);
  const rest = images.length - shown.length;
  const cols = mosaic
    ? 4
    : layout === "mosaic"
      ? limit === 4
        ? 2
        : Math.min(Math.max(limit, 2), 3)
      : columns;
  return (
    <>
      <ul
        className={cn(
          "grid grid-cols-2 gap-2",
          cols === 3 && "sm:grid-cols-3",
          cols === 4 && "sm:grid-cols-4",
          mosaic && "[&>li:first-child]:col-span-2 [&>li:first-child]:row-span-2",
          className,
        )}
      >
        {shown.map((image, i) => (
          <li key={image.src}>
            <button
              type="button"
              onClick={() => {
                setIndex(i);
                setOpen(true);
              }}
              className="relative block size-full overflow-hidden rounded-md outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
            >
              <Image
                src={image.src}
                alt={image.alt}
                ratio={mosaic && i === 0 ? undefined : ratio}
                containerClassName="size-full"
                className="transition-transform duration-(--ui-duration-slow) hover:scale-[1.03]"
              />
              {rest > 0 && i === shown.length - 1 ? (
                <span className="absolute inset-0 flex items-center justify-center bg-black/55 text-lg font-semibold text-white">
                  +{rest}
                </span>
              ) : null}
            </button>
          </li>
        ))}
      </ul>
      <Lightbox
        images={images}
        open={open}
        onOpenChange={setOpen}
        index={index}
        onIndexChange={setIndex}
      />
    </>
  );
}

