    onError,
    style,
    ...props
  },
  ref,
) {
  const [status, setStatus] = useState<"loading" | "loaded" | "error">("loading");
  const imgRef = useRef<HTMLImageElement>(null);
  // Server-rendered or cached images can finish loading before React attaches
  // onLoad/onError during hydration; read the element's state once mounted so
  // they never stay hidden behind the loading skeleton.
  useEffect(() => {
    const img = imgRef.current;
    if (!img || !img.complete) return;
    setStatus(img.naturalWidth > 0 ? "loaded" : "error");
  }, [props.src]);
  const radiusClass = {
    none: "rounded-none",
    sm: "rounded-sm",
    md: "rounded-md",
    lg: "rounded-lg",
    xl: "rounded-xl",
    full: "rounded-full",
  }[radius];
  return (
    <span
      className={cn(
        "relative block overflow-hidden bg-muted",
        radiusClass,
        status === "loading" && "ui-skeleton",
        containerClassName,
      )}
      style={ratio ? { aspectRatio: String(ratio) } : undefined}
    >
      {status === "error" ? (
        <span
          role={alt ? "img" : undefined}
          aria-label={alt || undefined}
          className="flex size-full min-h-24 items-center justify-center text-muted-foreground [&_svg]:size-6"
        >
          {fallback ?? <ImageIcon />}
        </span>
      ) : (
        <img
          ref={mergeRefs(ref, imgRef)}
          alt={alt}
          loading={loading}
          decoding={decoding}
          onLoad={(e) => {
            setStatus("loaded");
            onLoad?.(e);
          }}
          onError={(e) => {
            setStatus("error");
            onError?.(e);
          }}
          className={cn(
            "size-full transition-opacity duration-(--ui-duration-slow)",
            fit === "cover" ? "object-cover" : "object-contain",
            status === "loading" ? "opacity-0" : "opacity-100",
            className,
          )}
          style={style}
          {...props}
        />
      )}
    </span>
  );
});

export * from "./image.js";
export * from "./image-gallery.js";
export * from "./lightbox.js";
export * from "./video.js";

"use client";
import * as DialogPrimitive from "@radix-ui/react-dialog";
import { useControllableState } from "@ux-sting/hooks";
import { ChevronLeftIcon, ChevronRightIcon } from "@ux-sting/icons";
import { cn } from "@ux-sting/utils";
import type { KeyboardEvent } from "react";
import { CloseButton } from "../../lib/overlay.js";
import { useLocale, useMessages, usePortalContainer } from "../../provider/context.js";

export interface LightboxImage {
  src: string;
  alt: string;
  caption?: string;
  srcSet?: string;
}

export interface LightboxProps {
  images: LightboxImage[];
  open: boolean;
  onOpenChange: (open: boolean) => void;
  index?: number;
  defaultIndex?: number;
  onIndexChange?: (index: number) => void;
}

/** Full-screen image viewer with keyboard navigation (←/→, Esc). */
export function Lightbox({
  images,
  open,
  onOpenChange,
  index: indexProp,
  defaultIndex = 0,
  onIndexChange,
}: LightboxProps) {
  const [index, setIndex] = useControllableState({
    value: indexProp,
    defaultValue: defaultIndex,
    onChange: onIndexChange,
  });
  const container = usePortalContainer();
  const messages = useMessages();
  const { dir } = useLocale();
  const image = images[index];
  const go = (delta: number) => setIndex((index + delta + images.length) % images.length);
  const onKeyDown = (e: KeyboardEvent) => {
    if (e.key === (dir === "rtl" ? "ArrowLeft" : "ArrowRight")) go(1);
    if (e.key === (dir === "rtl" ? "ArrowRight" : "ArrowLeft")) go(-1);
  };
  const nav =
    "ui-hit-area absolute top-1/2 inline-flex size-11 -translate-y-1/2 items-center justify-center rounded-full bg-black/50 text-white outline-none hover:bg-black/70 focus-visible:ring-2 focus-visible:ring-white [&_svg]:size-5 rtl:[&_svg]:rotate-180";
  return (
    <DialogPrimitive.Root open={open} onOpenChange={onOpenChange}>
      <DialogPrimitive.Portal container={container}>
        <DialogPrimitive.Overlay className="ui-anim-overlay fixed inset-0 z-(--ui-z-modal) bg-black/90" />
        <DialogPrimitive.Content
          onKeyDown={onKeyDown}
          aria-describedby={undefined}
          className="ui-anim-pop fixed inset-0 z-(--ui-z-modal) flex flex-col items-center justify-center p-4 outline-none sm:p-12"
        >
          <DialogPrimitive.Title className="sr-only">{image?.alt}</DialogPrimitive.Title>
          {image ? (
            <figure className="flex max-h-full max-w-full flex-col items-center gap-3">
              <img
                src={image.src}
                srcSet={image.srcSet}
                alt={image.alt}
                className="max-h-[80dvh] max-w-full rounded-md object-contain"
              />
              <figcaption className="text-center text-sm text-white/80">
                {image.caption}
                <span className="ms-2 tabular-nums text-white/60">
                  {messages.slideOf(index + 1, images.length)}
                </span>
              </figcaption>
            </figure>
          ) : null}
          {images.length > 1 ? (
            <>
              <button
                type="button"
                aria-label={messages.previous}
                className={cn(nav, "start-3")}
                onClick={() => go(-1)}
              >
                <ChevronLeftIcon />
              </button>
              <button
                type="button"
                aria-label={messages.next}
                className={cn(nav, "end-3")}
                onClick={() => go(1)}
              >
                <ChevronRightIcon />
              </button>
            </>
          ) : null}
          <DialogPrimitive.Close asChild>
            <CloseButton className="absolute end-3 top-3 bg-black/50 text-white hover:bg-black/70 hover:text-white" />
          </DialogPrimitive.Close>
        </DialogPrimitive.Content>
      </DialogPrimitive.Portal>
    </DialogPrimitive.Root>
  );
}

import { cn } from "@ux-sting/utils";
import { forwardRef, type AudioHTMLAttributes, type VideoHTMLAttributes } from "react";

export interface MediaTrack {
  src: string;
  kind?: "captions" | "subtitles" | "descriptions";
  srcLang: string;
  label: string;
  default?: boolean;
}

export interface VideoProps extends VideoHTMLAttributes<HTMLVideoElement> {
  /** Aspect ratio reserved for the player. */
  ratio?: number;
  /** Caption/subtitle tracks (WebVTT). Provide captions for spoken content. */
  tracks?: MediaTrack[];
  /** Accessible title. */
  title?: string;
}

/**
 * Native video with reserved aspect ratio and caption tracks. Autoplay is
 * only allowed muted and respects reduced motion (use `autoPlay` sparingly).
 */
export const Video = forwardRef<HTMLVideoElement, VideoProps>(function Video(
  {
    ratio = 16 / 9,
    tracks = [],
    controls = true,
    preload = "metadata",
    playsInline = true,
    className,
    children,
    ...props
  },
  ref,
) {
  return (
    <div
      className="relative overflow-hidden rounded-lg bg-black"
      style={{ aspectRatio: String(ratio) }}
    >
      {/* Caption tracks are passed via `tracks`. */}
      {/* eslint-disable-next-line jsx-a11y/media-has-caption */}
      <video
        ref={ref}
        controls={controls}
        preload={preload}
        playsInline={playsInline}
        className={cn("size-full", className)}
        {...props}
      >
        {tracks.map((t) => (
          <track
            key={t.src}
            kind={t.kind ?? "captions"}
            src={t.src}
            srcLang={t.srcLang}
            label={t.label}
            default={t.default}
          />
        ))}
        {children}
      </video>
    </div>
  );
});

export interface AudioProps extends AudioHTMLAttributes<HTMLAudioElement> {
  /** Visible title for the audio clip. */
  title?: string;
  /** Link to a transcript for accessibility. */
  transcriptHref?: string;
  transcriptLabel?: string;
}

/** Native audio player with visible title and optional transcript link. */
export const Audio = forwardRef<HTMLAudioElement, AudioProps>(function Audio(
  {
    title,
    transcriptHref,
    transcriptLabel = "Transcript",
    controls = true,
    preload = "metadata",
    className,
    ...props
  },
  ref,
) {
  return (
    <figure className={cn("grid gap-2 rounded-lg border border-border bg-card p-3", className)}>
      {title ? <figcaption className="text-sm font-medium">{title}</figcaption> : null}
      {/* Audio uses a transcript link (`transcriptHref`) instead of a caption track. */}
      {/* eslint-disable-next-line jsx-a11y/media-has-caption */}
      <audio
        ref={ref}
        controls={controls}
        preload={preload}
        className="w-full"
        aria-label={title}
        {...props}
      />
      {transcriptHref ? (
        <a href={transcriptHref} className="text-sm text-primary underline underline-offset-4">
          {transcriptLabel}
        </a>
      ) : null}
    </figure>
  );
});

"use client";
import { useControllableState, useHotkey } from "@ux-sting/hooks";
import * as DialogPrimitive from "@radix-ui/react-dialog";
import { VisuallyHidden } from "@ux-sting/primitives";
import { cn } from "@ux-sting/utils";
import type { ReactNode } from "react";
import { overlayClass } from "../../lib/overlay.js";
import { usePortalContainer } from "../../provider/context.js";
import { Command, type CommandProps } from "./command.js";

export interface CommandDialogProps extends Omit<CommandProps, "title"> {
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** Global shortcut to open the palette. Defaults to `mod+k`; `false` disables. */
  shortcut?: string | false;
  title?: ReactNode;
  children?: ReactNode;
}

/** Command palette in a modal dialog, opened with ⌘K / Ctrl+K by default. */
export function CommandDialog({
  open: openProp,
  defaultOpen = false,
  onOpenChange,
  shortcut = "mod+k",
  title = "Command menu",
  className,
  children,
  ...props
}: CommandDialogProps) {
  const [open, setOpen] = useControllableState({
    value: openProp,
    defaultValue: defaultOpen,
    onChange: onOpenChange,
  });
  const container = usePortalContainer();
  useHotkey(shortcut || "", () => setOpen(!open), {
    enabled: Boolean(shortcut),
    enableInInputs: true,
  });
  return (
    <DialogPrimitive.Root open={open} onOpenChange={setOpen}>
      <DialogPrimitive.Portal container={container}>
        <DialogPrimitive.Overlay className={overlayClass} />
        <DialogPrimitive.Content
          aria-describedby={undefined}
          className="ui-anim-pop fixed start-1/2 top-[12dvh] z-(--ui-z-modal) w-[calc(100%-2rem)] max-w-xl -translate-x-1/2 overflow-hidden rounded-xl border border-border shadow-xl outline-none rtl:translate-x-1/2"
        >
          <VisuallyHidden>
            <DialogPrimitive.Title>{title}</DialogPrimitive.Title>
          </VisuallyHidden>
          <Command
            label={typeof title === "string" ? title : undefined}
            className={cn(className)}
            {...props}
          >
            {children}
          </Command>
        </DialogPrimitive.Content>
      </DialogPrimitive.Portal>
    </DialogPrimitive.Root>
  );
}

"use client";
import { useControllableState, useIsomorphicLayoutEffect, useMergedRefs } from "@ux-sting/hooks";
import { SearchIcon } from "@ux-sting/icons";
import { cn, fuzzyScore } from "@ux-sting/utils";
import {
  createContext,
  forwardRef,
  useCallback,
  useContext,
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
  type HTMLAttributes,
  type InputHTMLAttributes,
  type KeyboardEvent,
  type ReactNode,
} from "react";
import {
  menuItemClass,
  menuLabelClass,
  menuSeparatorClass,
  menuShortcutClass,
} from "../../lib/menu-styles.js";
import { useMessages } from "../../provider/context.js";
import { Spinner } from "../spinner/spinner.js";

interface ItemRecord {
  value: string;
  keywords: string[];
  groupId?: string;
  disabled?: boolean;
  onSelect?: (value: string) => void;
}

interface CommandContextValue {
  search: string;
  setSearch: (value: string) => void;
  activeId: string | null;
  setActiveId: (id: string | null) => void;
  register: (id: string, record: ItemRecord) => () => void;
  isVisible: (id: string) => boolean;
  groupVisible: (groupId: string) => boolean;
  visibleCount: number;
  listId: string;
  loading: boolean;
  select: (id: string) => void;
  handleKeyDown: (event: KeyboardEvent) => void;
  label?: string;
}

const defaultFilter = (value: string, search: string, keywords: string[]) =>
  fuzzyScore(search, value, keywords);

const CommandContext = createContext<CommandContextValue | null>(null);
const GroupContext = createContext<string | undefined>(undefined);

function useCommand() {
  const ctx = useContext(CommandContext);
  if (!ctx) throw new Error("Command parts must be used inside <Command>.");
  return ctx;
}

export interface CommandProps extends Omit<HTMLAttributes<HTMLDivElement>, "onChange"> {
  /** Controlled search value. */
  search?: string;
  defaultSearch?: string;
  onSearchChange?: (search: string) => void;
  /** Disable built-in filtering (e.g. for async/server results). */
  shouldFilter?: boolean;
  /** Custom scoring function; return 0 to hide an item. */
  filter?: (value: string, search: string, keywords: string[]) => number;
  /** Wrap keyboard navigation around the ends. */
  loop?: boolean;
  /** Shows `CommandLoading` and marks the list busy. */
  loading?: boolean;
  /** Accessible label for the command menu. */
  label?: string;
}

/**
 * Fast, keyboard-first command/search menu with fuzzy matching, groups,
 * shortcuts and async support. Also the engine behind Combobox and
 * Autocomplete.
 */
export const Command = forwardRef<HTMLDivElement, CommandProps>(function Command(
  {
    search: searchProp,
    defaultSearch = "",
    onSearchChange,
    shouldFilter = true,
    filter = defaultFilter,
    loop = true,
    loading = false,
    label,
    className,
    children,
    onKeyDown,
    ...props
  },
  ref,
) {
  const [search, setSearch] = useControllableState({
    value: searchProp,
    defaultValue: defaultSearch,
    onChange: onSearchChange,
  });
  const [activeId, setActiveId] = useState<string | null>(null);
  const [version, setVersion] = useState(0);
  const items = useRef(new Map<string, ItemRecord>());
  const rootRef = useRef<HTMLDivElement>(null);
  const mergedRef = useMergedRefs(ref, rootRef);
  const listId = `cmd${useId().replace(/:/g, "")}`;

  const register = useCallback((id: string, record: ItemRecord) => {
    items.current.set(id, record);
    setVersion((v) => v + 1);
    return () => {
      items.current.delete(id);
      setVersion((v) => v + 1);
    };
  }, []);

  const visible = useMemo(() => {
    const set = new Set<string>();
    const groups = new Set<string>();
    for (const [id, rec] of items.current) {
      const score = !shouldFilter || !search ? 1 : filter(rec.value, search, rec.keywords);
      if (score > 0) {
        set.add(id);
        if (rec.groupId) groups.add(rec.groupId);
      }
    }
    return { set, groups };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [search, shouldFilter, filter, version]);

  const getNavigable = useCallback(() => {
    return Array.from(
      rootRef.current?.querySelectorAll<HTMLElement>(
        "[data-command-item]:not([data-disabled]):not([hidden])",
      ) ?? [],
    );
  }, []);

  // Highlight the first match whenever the results change.
  useIsomorphicLayoutEffect(() => {
    const [first] = getNavigable();
    if (!activeId || !visible.set.has(activeId)) setActiveId(first?.id ?? null);
  }, [visible]);

  useEffect(() => {
    if (activeId) document.getElementById(activeId)?.scrollIntoView({ block: "nearest" });
  }, [activeId]);

  const select = useCallback((id: string) => {
    const rec = items.current.get(id);
    if (rec && !rec.disabled) rec.onSelect?.(rec.value);
  }, []);

  const handleKeyDown = (event: KeyboardEvent) => {
    const nodes = getNavigable();
    if (!nodes.length) return;
    const index = nodes.findIndex((n) => n.id === activeId);
    const move = (next: number) => {
      event.preventDefault();
      const clamped = loop
        ? (next + nodes.length) % nodes.length
        : Math.max(0, Math.min(nodes.length - 1, next));
      setActiveId(nodes[clamped]?.id ?? null);
    };
    switch (event.key) {
      case "ArrowDown":
        return move(index + 1);
      case "ArrowUp":
        return move(index - 1);
      case "Home":
        return move(0);
      case "End":
        return move(nodes.length - 1);
      case "Enter":
        if (activeId) {
          event.preventDefault();
          select(activeId);
        }
        return;
    }
  };

  const value: CommandContextValue = {
    search,
    setSearch,
    activeId,
    setActiveId,
    register,
    isVisible: (id) => visible.set.has(id),
    groupVisible: (gid) => visible.groups.has(gid),
    visibleCount: visible.set.size,
    listId,
    loading,
    select,
    handleKeyDown,
    label,
  };

  return (
    <CommandContext.Provider value={value}>
      <div
        ref={mergedRef}
        data-command-root=""
        className={cn(
          "flex size-full flex-col overflow-hidden rounded-lg bg-popover text-popover-foreground",
          className,
        )}
        onKeyDown={(e) => {
          onKeyDown?.(e);
          if (!e.defaultPrevented && (e.target as HTMLElement).tagName !== "INPUT")
            handleKeyDown(e);
        }}
        {...props}
      >
        {children}
      </div>
    </CommandContext.Provider>
  );
});

export interface CommandInputProps extends Omit<
  InputHTMLAttributes<HTMLInputElement>,
  "value" | "onChange"
> {
  value?: string;
  onValueChange?: (value: string) => void;
}

export const CommandInput = forwardRef<HTMLInputElement, CommandInputProps>(function CommandInput(
  { className, onValueChange, placeholder, onKeyDown, ...props },
  ref,
) {
  const ctx = useCommand();
  const messages = useMessages();
  return (
    <div className="flex items-center gap-2 border-b border-border px-3">
      {ctx.loading ? (
        <Spinner size="sm" label={null} />
      ) : (
        <SearchIcon className="size-4 shrink-0 text-muted-foreground" />
      )}
      <input
        ref={ref}
        role="combobox"
        aria-expanded
        aria-controls={ctx.listId}
        aria-activedescendant={ctx.activeId ?? undefined}
        aria-autocomplete="list"
        aria-label={props["aria-label"] ?? ctx.label ?? messages.search}
        autoComplete="off"
        autoCorrect="off"
        spellCheck={false}
        value={ctx.search}
        placeholder={placeholder ?? messages.search}
        onChange={(e) => {
          ctx.setSearch(e.target.value);
          onValueChange?.(e.target.value);
        }}
        onKeyDown={(e) => {
          onKeyDown?.(e);
          if (!e.defaultPrevented) ctx.handleKeyDown(e);
        }}
        className={cn(
          // ux-audit-ignore: the caret and highlighted option indicate focus inside the palette
          "flex h-11 w-full bg-transparent py-3 text-md outline-none placeholder:text-muted-foreground disabled:opacity-50 sm:text-sm",
          className,
        )}
        {...props}
      />
    </div>
  );
});

export const CommandList = forwardRef<HTMLDivElement, HTMLAttributes<HTMLDivElement>>(
  function CommandList({ className, ...props }, ref) {
    const ctx = useCommand();
    return (
      <div
        ref={ref}
        id={ctx.listId}
        // An empty listbox is invalid; while there are no options the list only hosts status messages.
        role={ctx.visibleCount > 0 ? "listbox" : undefined}
        aria-label={ctx.label}
        aria-busy={ctx.loading || undefined}
        className={cn("max-h-80 scroll-py-1 overflow-y-auto overflow-x-hidden p-1", className)}
        {...props}
      />
    );
  },
);

export const CommandEmpty = forwardRef<HTMLDivElement, HTMLAttributes<HTMLDivElement>>(
  function CommandEmpty({ className, children, ...props }, ref) {
    const ctx = useCommand();
    const messages = useMessages();
    if (ctx.loading || ctx.visibleCount > 0) return null;
    return (
      <div
        ref={ref}
        role="status"
        className={cn("py-8 text-center text-sm text-muted-foreground", className)}
        {...props}
      >
        {children ?? messages.noResults}
      </div>
    );
  },
);

export const CommandLoading = forwardRef<HTMLDivElement, HTMLAttributes<HTMLDivElement>>(
  function CommandLoading({ className, children, ...props }, ref) {
    const ctx = useCommand();
    const messages = useMessages();
    if (!ctx.loading) return null;
    return (
      <div
        ref={ref}
        role="status"
        className={cn(
          "flex items-center justify-center gap-2 py-6 text-sm text-muted-foreground",
          className,
        )}
        {...props}
      >
        <Spinner size="sm" label={null} />
        {children ?? messages.loading}
      </div>
    );
  },
);

export interface CommandGroupProps extends HTMLAttributes<HTMLDivElement> {
  heading?: ReactNode;
}

export const CommandGroup = forwardRef<HTMLDivElement, CommandGroupProps>(function CommandGroup(
  { heading, className, children, ...props },
  ref,
) {
  const ctx = useCommand();
  const id = useId();
  const headingId = `${id}-heading`;
  return (
    <GroupContext.Provider value={id}>
      <div
        ref={ref}
        role="group"
        aria-labelledby={heading ? headingId : undefined}
        hidden={!ctx.groupVisible(id)}
        className={cn("py-1", className)}
        {...props}
      >
        {heading ? (
          <div id={headingId} className={menuLabelClass} aria-hidden>
            {heading}
          </div>
        ) : null}
        {children}
      </div>
    </GroupContext.Provider>
  );
});

export interface CommandItemProps extends Omit<HTMLAttributes<HTMLDivElement>, "onSelect"> {
  /** Value used for filtering and passed to `onSelect`. Defaults to text content. */
  value: string;
  keywords?: string[];
  disabled?: boolean;
  onSelect?: (value: string) => void;
  icon?: ReactNode;
  shortcut?: ReactNode;
  /** Visual selected state (e.g. current combobox value). */
  selected?: boolean;
}

export const CommandItem = forwardRef<HTMLDivElement, CommandItemProps>(function CommandItem(
  { value, keywords, disabled, onSelect, icon, shortcut, selected, className, children, ...props },
  ref,
) {
  const ctx = useCommand();
  const groupId = useContext(GroupContext);
  const id = `cmdi${useId().replace(/:/g, "")}`;
  const onSelectRef = useRef(onSelect);
  onSelectRef.current = onSelect;
  const keywordKey = keywords?.join("|") ?? "";

  useIsomorphicLayoutEffect(
    () =>
      ctx.register(id, {
        value,
        keywords: keywordKey ? keywordKey.split("|") : [],
        groupId,
        disabled,
        onSelect: (v) => onSelectRef.current?.(v),
      }),

    [id, value, keywordKey, groupId, disabled, ctx.register],
  );

  const active = ctx.activeId === id;
  return (
    <div
      ref={ref}
      id={id}
      role="option"
      tabIndex={-1}
      data-command-item=""
      aria-selected={active}
      aria-disabled={disabled || undefined}
      aria-checked={selected === undefined ? undefined : selected}
      data-disabled={disabled ? "" : undefined}
      data-highlighted={active ? "" : undefined}
      data-selected={selected ? "" : undefined}
      hidden={!ctx.isVisible(id)}
      onPointerMove={() => !disabled && !active && ctx.setActiveId(id)}
      onClick={() => ctx.select(id)}
      className={cn(menuItemClass, "cursor-pointer", className)}
      {...props}
    >
      {icon}
      <span className="flex-1 truncate">{children ?? value}</span>
      {shortcut ? <span className={menuShortcutClass}>{shortcut}</span> : null}
    </div>
  );
});

export const CommandSeparator = forwardRef<HTMLDivElement, HTMLAttributes<HTMLDivElement>>(
  function CommandSeparator({ className, ...props }, ref) {
    const ctx = useCommand();
    if (ctx.search) return null;
    // Listboxes may only contain options and groups, so the separator is purely visual.
    return <div ref={ref} aria-hidden className={cn(menuSeparatorClass, className)} {...props} />;
  },
);

import { cn } from "@ux-sting/utils";

export interface HighlightProps {
  text: string;
  /** Terms to highlight (case/accents-insensitive). */
  query: string | string[];
  className?: string;
  markClassName?: string;
}

const normalize = (s: string) =>
  s
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase();

/** Highlights matched terms with `<mark>` (search results, command menus). */
export function Highlight({ text, query, className, markClassName }: HighlightProps) {
  const terms = (Array.isArray(query) ? query : query.split(/\s+/))
    .map((t) => normalize(t.trim()))
    .filter(Boolean);
  if (!terms.length) return <span className={className}>{text}</span>;
  const normalized = normalize(text);
  const ranges: Array<[number, number]> = [];
  for (const term of terms) {
    let from = 0;
    let i: number;
    while ((i = normalized.indexOf(term, from)) !== -1) {
      ranges.push([i, i + term.length]);
      from = i + term.length;
    }
  }
  ranges.sort((a, b) => a[0] - b[0]);
  const parts: Array<{ text: string; match: boolean }> = [];
  let cursor = 0;
  for (const [start, end] of ranges) {
    if (start < cursor) continue;
    if (start > cursor) parts.push({ text: text.slice(cursor, start), match: false });
    parts.push({ text: text.slice(start, end), match: true });
    cursor = end;
  }
  if (cursor < text.length) parts.push({ text: text.slice(cursor), match: false });
  return (
    <span className={className}>
      {parts.map((p, i) =>
        p.match ? (
          <mark
            key={i}
            className={cn(
              "rounded-xs bg-warning-subtle px-0.5 text-warning-subtle-foreground",
              markClassName,
            )}
          >
            {p.text}
          </mark>
        ) : (
          <span key={i}>{p.text}</span>
        ),
      )}
    </span>
  );
}

import { ExternalLinkIcon } from "@ux-sting/icons";
import { Slot } from "@ux-sting/primitives";
import { cn } from "@ux-sting/utils";
import {
  Children,
  forwardRef,
  Fragment,
  isValidElement,
  type AnchorHTMLAttributes,
  type CSSProperties,
  type HTMLAttributes,
  type ReactNode,
} from "react";

/*
 * Colors come from --footer-* variables so a site can retint the footer
 * without touching the theme: set them on the <Footer> (style/className).
 * `inverse` is a dark band whatever the color mode; `default` follows the
 * theme's surface tokens.
 */
const TONES: Record<"default" | "inverse", CSSProperties> = {
  default: {
    "--footer-bg": "var(--ui-surface)",
    "--footer-fg": "var(--ui-foreground)",
    "--footer-muted": "var(--ui-muted-foreground)",
    "--footer-border": "var(--ui-border)",
    "--footer-accent": "var(--ui-primary)",
  } as CSSProperties,
  inverse: {
    "--footer-bg": "var(--ui-slate-950)",
    "--footer-fg": "var(--ui-slate-50)",
    "--footer-muted": "color-mix(in oklab, var(--ui-slate-50) 66%, transparent)",
    "--footer-border": "color-mix(in oklab, var(--ui-slate-50) 12%, transparent)",
    "--footer-accent": "var(--ui-primary)",
  } as CSSProperties,
};

export interface FooterProps extends HTMLAttributes<HTMLElement> {
  /** `inverse` = dark band in every color mode; `default` = theme surface. */
  tone?: "default" | "inverse";
  /** Max width of the inner container. */
  maxWidth?: "md" | "lg" | "xl" | "full";
}

/**
 * Site footer (`contentinfo` landmark). Compose `FooterCallout` (optional
 * CTA band), `FooterMain` with `FooterBrand` + `FooterNav` of
 * `FooterColumn`s, then `FooterBottom` with `FooterCopyright` and
 * `FooterLegal`. Links use `FooterLink` (`asChild` for router links).
 */
export const Footer = forwardRef<HTMLElement, FooterProps>(function Footer(
  { tone = "inverse", maxWidth = "xl", className, style, children, ...props },
  ref,
) {
  return (
    <footer
      ref={ref}
      data-tone={tone}
      style={{ ...TONES[tone], ...style }}
      className={cn(
        "w-full bg-(--footer-bg) text-(--footer-fg)",
        tone === "default" && "border-t border-(--footer-border)",
        className,
      )}
      {...props}
    >
      <div
        className={cn(
          "mx-auto px-4 py-12 sm:px-6 sm:py-14 lg:px-8",
          maxWidth === "md" && "max-w-5xl",
          maxWidth === "lg" && "max-w-6xl",
          maxWidth === "xl" && "max-w-7xl",
        )}
      >
        {children}
      </div>
    </footer>
  );
});

export interface FooterCalloutProps extends Omit<HTMLAttributes<HTMLDivElement>, "title"> {
  title: ReactNode;
  description?: ReactNode;
  /** Buttons / links shown on the end side. */
  actions?: ReactNode;
}

/** Call-to-action band at the top of the footer (newsletter, sign-up, "list your business"). */
export const FooterCallout = forwardRef<HTMLDivElement, FooterCalloutProps>(function FooterCallout(
  { title, description, actions, className, children, ...props },
  ref,
) {
  return (
    <div
      ref={ref}
      className={cn(
        "mb-12 flex flex-col gap-5 rounded-lg border border-(--footer-border) p-6 sm:p-8 lg:flex-row lg:items-center lg:justify-between",
        "bg-[color-mix(in_oklab,var(--footer-accent)_14%,transparent)]",
        className,
      )}
      {...props}
    >
      <div className="max-w-2xl">
        <p className="text-lg font-semibold tracking-tight sm:text-xl">{title}</p>
        {description ? <p className="mt-1.5 text-sm text-(--footer-muted)">{description}</p> : null}
        {children}
      </div>
      {actions ? <div className="flex shrink-0 flex-wrap items-center gap-3">{actions}</div> : null}
    </div>
  );
});

/** Brand column + navigation grid. */
export const FooterMain = forwardRef<HTMLDivElement, HTMLAttributes<HTMLDivElement>>(
  function FooterMain({ className, ...props }, ref) {
    return (
      <div
        ref={ref}
        className={cn(
          "grid gap-12 lg:grid-cols-[minmax(0,1fr)_minmax(0,2.6fr)] lg:gap-16",
          className,
        )}
        {...props}
      />
    );
  },
);

/** Logo, tagline, contact and newsletter. */
export const FooterBrand = forwardRef<HTMLDivElement, HTMLAttributes<HTMLDivElement>>(
  function FooterBrand({ className, ...props }, ref) {
    return (
      <div ref={ref} className={cn("flex flex-col items-start gap-5", className)} {...props} />
    );
  },
);

export const FooterTagline = forwardRef<HTMLParagraphElement, HTMLAttributes<HTMLParagraphElement>>(
  function FooterTagline({ className, ...props }, ref) {
    return (
      <p
        ref={ref}
        className={cn("max-w-sm text-sm leading-relaxed text-(--footer-muted)", className)}
        {...props}
      />
    );
  },
);

export interface FooterNavProps extends HTMLAttributes<HTMLElement> {
  /** Columns from `lg` up (2 on phones, 3 on tablets). */
  columns?: 2 | 3 | 4 | 5 | 6;
}

/** `<nav>` grid of `FooterColumn`s. Give it an `aria-label`. */
export const FooterNav = forwardRef<HTMLElement, FooterNavProps>(function FooterNav(
  { columns = 4, className, ...props },
  ref,
) {
  return (
    <nav
      ref={ref}
      className={cn(
        "grid grid-cols-2 gap-x-6 gap-y-10 sm:grid-cols-3",
        columns === 2 && "lg:grid-cols-2",
        columns === 3 && "lg:grid-cols-3",
        columns === 4 && "lg:grid-cols-4",
        columns === 5 && "lg:grid-cols-5",
        columns === 6 && "lg:grid-cols-6",
        className,
      )}
      {...props}
    />
  );
});

export interface FooterColumnProps extends Omit<HTMLAttributes<HTMLDivElement>, "title"> {
  title: ReactNode;
  /** Heading level of the column title (default 2). */
  headingLevel?: 2 | 3 | 4;
}

/** Titled list of `FooterLink`s. */
export const FooterColumn = forwardRef<HTMLDivElement, FooterColumnProps>(function FooterColumn(
  { title, headingLevel = 2, className, children, ...props },
  ref,
) {
  const Heading = `h${headingLevel}` as "h2";
  return (
    <div ref={ref} className={cn("min-w-0", className)} {...props}>
      <Heading className="text-sm font-semibold">{title}</Heading>
      <ul className="mt-4 space-y-2.5 text-sm">{children}</ul>
    </div>
  );
});

export interface FooterLinkProps extends AnchorHTMLAttributes<HTMLAnchorElement> {
  asChild?: boolean;
  /** Leading icon (decorative). */
  icon?: ReactNode;
  /** Opens in a new tab with an external-link hint for screen readers. */
  external?: boolean;
  /** Small badge after the label, e.g. "Nouveau". */
  badge?: ReactNode;
  /** Screen-reader hint appended to external links. */
  externalLabel?: string;
}

/** A footer link inside `FooterColumn` (renders its own `<li>`). */
export const FooterLink = forwardRef<HTMLAnchorElement, FooterLinkProps>(function FooterLink(
  {
    asChild,
    icon,
    external,
    badge,
    externalLabel = "(opens in a new tab)",
    className,
    children,
    ...props
  },
  ref,
) {
  const Comp = asChild ? Slot : "a";
  const content = asChild ? (
    children
  ) : (
    <>
      {icon ? (
        <span aria-hidden className="text-(--footer-accent) [&_svg]:size-4">
          {icon}
        </span>
      ) : null}
      {children}
      {badge ? (
        <span className="rounded-full bg-(--footer-accent) px-1.5 py-0.5 text-[10px] leading-none font-semibold text-white">
          {badge}
        </span>
      ) : null}
      {external ? (
        <>
          <ExternalLinkIcon aria-hidden className="size-3 opacity-60" />
          <span className="sr-only"> {externalLabel}</span>
        </>
      ) : null}
    </>
  );
  return (
    <li>
      <Comp
        ref={ref}
        {...(external && !asChild ? { target: "_blank", rel: "noopener noreferrer" } : {})}
        className={cn(
          "inline-flex items-center gap-2 rounded-sm text-(--footer-muted) transition-colors outline-none",
          "hover:text-(--footer-fg) focus-visible:ring-2 focus-visible:ring-(--footer-accent) aria-[current=page]:text-(--footer-fg)",
          className,
        )}
        {...props}
      >
        {content}
      </Comp>
    </li>
  );
});

/** Bottom bar: copyright on the start side, legal links / switches on the end side. */
export const FooterBottom = forwardRef<HTMLDivElement, HTMLAttributes<HTMLDivElement>>(
  function FooterBottom({ className, ...props }, ref) {
    return (
      <div
        ref={ref}
        className={cn(
          "mt-12 flex flex-col gap-4 border-t border-(--footer-border) pt-6 text-xs text-(--footer-muted) md:flex-row md:items-center md:justify-between",
          className,
        )}
        {...props}
      />
    );
  },
);

export const FooterCopyright = forwardRef<
  HTMLParagraphElement,
  HTMLAttributes<HTMLParagraphElement>
>(function FooterCopyright({ className, ...props }, ref) {
  return <p ref={ref} className={cn(className)} {...props} />;
});

/** Inline list of legal links, separated by a small dot. Children: `<a>`s or router links. */
export const FooterLegal = forwardRef<HTMLUListElement, HTMLAttributes<HTMLUListElement>>(
  function FooterLegal({ className, children, ...props }, ref) {
    const items = Children.toArray(children).filter(isValidElement);
    return (
      <ul
        ref={ref}
        className={cn("flex flex-wrap items-center gap-x-3 gap-y-2", className)}
        {...props}
      >
        {items.map((child, i) => (
          <Fragment key={child.key ?? i}>
            {i > 0 ? <li aria-hidden className="size-1 rounded-full bg-(--footer-border)" /> : null}
            <li className="[&_a]:transition-colors [&_a:hover]:text-(--footer-fg)">{child}</li>
          </Fragment>
        ))}
      </ul>
    );
  },
);

import { cn } from "@ux-sting/utils";
import type { ReactNode } from "react";
import { Card, CardLink } from "../card/card.js";
import { Image } from "../media/image.js";
import { Location } from "../location/location.js";
import { PriceLevel } from "../price/price.js";
import { ReviewStars } from "../rating/rating.js";

export interface BusinessCardProps {
  name: string;
  href?: string;
  image?: { src: string; alt: string };
  /** Category label, e.g. "Italian restaurant". */
  category?: ReactNode;
  rating?: number;
  reviewCount?: number;
  priceLevel?: number;
  priceLevelLabel?: string;
  address?: ReactNode;
  distance?: ReactNode;
  /** Open status element, e.g. `<OpenStatus periods={…} />`. */
  status?: ReactNode;
  /** Badges over the image (e.g. `<PremiumBadge />`). */
  badges?: ReactNode;
  /** Short highlights (tags). */
  tags?: ReactNode;
  /** Extra details slot (price per night, cuisine, response time…). */
  meta?: ReactNode;
  /** Actions (save/favorite button). Rendered above the card link. */
  actions?: ReactNode;
  layout?: "vertical" | "horizontal";
  headingLevel?: 2 | 3 | 4;
  className?: string;
  /** Render the title link via a router component. */
  renderLink?: (props: { href: string; children: ReactNode; className: string }) => ReactNode;
}

/**
 * Generic listing card for local businesses and places. The entire card is
 * clickable through one stretched link; secondary actions stay independently
 * focusable. Presets: PlaceCard, RestaurantCard, HotelCard, ServiceCard.
 */
export function BusinessCard({
  name,
  href,
  image,
  category,
  rating,
  reviewCount,
  priceLevel,
  priceLevelLabel,
  address,
  distance,
  status,
  badges,
  tags,
  meta,
  actions,
  layout = "vertical",
  headingLevel = 3,
  className,
  renderLink,
}: BusinessCardProps) {
  const Heading = `h${headingLevel}` as const;
  const linkClass =
    "outline-none after:absolute after:inset-0 after:z-[1] after:content-[''] focus-visible:after:rounded-xl focus-visible:after:ring-2 focus-visible:after:ring-ring hover:underline underline-offset-2";
  const title = href ? (
    renderLink ? (
      renderLink({ href, children: name, className: linkClass })
    ) : (
      <CardLink href={href} className={linkClass}>
        {name}
      </CardLink>
    )
  ) : (
    name
  );
  return (
    <Card
      interactive={Boolean(href)}
      className={cn(layout === "horizontal" && "sm:flex-row", className)}
    >
      {image ? (
        <div className={cn("relative shrink-0", layout === "horizontal" ? "sm:w-56" : "")}>
          <Image
            src={image.src}
            alt={image.alt}
            ratio={layout === "horizontal" ? undefined : 4 / 3}
            radius="none"
            containerClassName={cn(layout === "horizontal" && "h-full min-h-40")}
          />
          {badges ? (
            <div className="absolute start-3 top-3 flex flex-wrap gap-1.5">{badges}</div>
          ) : null}
          {actions ? (
            <div className="absolute end-3 top-3 z-[2] flex gap-1.5">{actions}</div>
          ) : null}
        </div>
      ) : null}
      <div className="flex min-w-0 flex-1 flex-col gap-2 p-4">
        {category ? (
          <p className="text-xs font-medium uppercase tracking-wide text-muted-foreground">
            {category}
          </p>
        ) : null}
        <Heading className="text-md font-semibold leading-snug text-foreground">{title}</Heading>
        {rating !== undefined || priceLevel !== undefined ? (
          <div className="flex flex-wrap items-center gap-x-3 gap-y-1">
            {rating !== undefined ? (
              <ReviewStars value={rating} size="sm" showValue count={reviewCount} />
            ) : null}
            {priceLevel !== undefined ? (
              <PriceLevel level={priceLevel} label={priceLevelLabel} className="text-sm" />
            ) : null}
          </div>
        ) : null}
        {address ? <Location address={address} distance={distance} /> : null}
        {status}
        {meta}
        {tags ? <div className="mt-1 flex flex-wrap gap-1.5">{tags}</div> : null}
        {!image && actions ? (
          <div className="relative z-[2] mt-auto flex gap-2 pt-2">{actions}</div>
        ) : null}
      </div>
    </Card>
  );
}

/** Generic place (park, museum, venue). */
export function PlaceCard(props: BusinessCardProps) {
  return <BusinessCard {...props} />;
}

export interface RestaurantCardProps extends BusinessCardProps {
  cuisine?: ReactNode;
}

/** Restaurant preset: cuisine as category, price level emphasised. */
export function RestaurantCard({ cuisine, category, ...props }: RestaurantCardProps) {
  return <BusinessCard category={cuisine ?? category} {...props} />;
}

export interface HotelCardProps extends BusinessCardProps {
  /** e.g. `<Price amount={120} currency="EUR" period="/ night" />`. */
  nightlyPrice?: ReactNode;
  /** Hotel class, 1–5. */
  stars?: number;
}

/** Hotel preset: nightly price and hotel class. */
export function HotelCard({ nightlyPrice, stars, meta, category, ...props }: HotelCardProps) {
  return (
    <BusinessCard
      category={category ?? (stars ? `${stars}-star hotel` : undefined)}
      meta={
        <>
          {meta}
          {nightlyPrice ? <div className="mt-auto pt-1">{nightlyPrice}</div> : null}
        </>
      }
      {...props}
    />
  );
}

export interface ServiceCardProps extends BusinessCardProps {
  /** e.g. "From €40". */
  startingPrice?: ReactNode;
  /** e.g. "Responds within 1 hour". */
  responseTime?: ReactNode;
}

/** Service provider preset (plumber, tutor, salon). */
export function ServiceCard({ startingPrice, responseTime, meta, ...props }: ServiceCardProps) {
  return (
    <BusinessCard
      meta={
        <>
          {meta}
          {responseTime ? <p className="text-sm text-muted-foreground">{responseTime}</p> : null}
          {startingPrice ? <p className="text-sm font-semibold">{startingPrice}</p> : null}
        </>
      }
      {...props}
    />
  );
}

import { cn } from "@ux-sting/utils";
import type { ReactNode } from "react";
import { Card, CardLink } from "../card/card.js";
import { Image } from "../media/image.js";
import { ReviewStars } from "../rating/rating.js";

export interface ProductCardProps {
  name: string;
  href?: string;
  image: { src: string; alt: string };
  /** Price element, e.g. `<Price amount={49} currency="USD" compareAt={69} />`. */
  price: ReactNode;
  brand?: ReactNode;
  rating?: number;
  reviewCount?: number;
  badges?: ReactNode;
  /** Primary action (add to cart). */
  action?: ReactNode;
  /** Secondary action over the image (wishlist). */
  secondaryAction?: ReactNode;
  /** e.g. "Only 3 left" or color swatches. */
  meta?: ReactNode;
  headingLevel?: 2 | 3 | 4;
  className?: string;
}

/** Marketplace product tile with stretched link and independent actions. */
export function ProductCard({
  name,
  href,
  image,
  price,
  brand,
  rating,
  reviewCount,
  badges,
  action,
  secondaryAction,
  meta,
  headingLevel = 3,
  className,
}: ProductCardProps) {
  const Heading = `h${headingLevel}` as const;
  return (
    <Card interactive={Boolean(href)} variant="ghost" className={cn("gap-3 rounded-xl", className)}>
      <div className="relative overflow-hidden rounded-xl bg-muted">
        <Image
          src={image.src}
          alt={image.alt}
          ratio={1}
          radius="none"
          className="transition-transform duration-(--ui-duration-slow) group-hover/card:scale-[1.03]"
        />
        {badges ? (
          <div className="absolute start-2 top-2 flex flex-wrap gap-1">{badges}</div>
        ) : null}
        {secondaryAction ? (
          <div className="absolute end-2 top-2 z-[2]">{secondaryAction}</div>
        ) : null}
      </div>
      <div className="grid gap-1 px-0.5">
        {brand ? <p className="text-xs text-muted-foreground">{brand}</p> : null}
        <Heading className="line-clamp-2 text-sm font-medium text-foreground">
          {href ? (
            <CardLink href={href} className="after:z-[1]">
              {name}
            </CardLink>
          ) : (
            name
          )}
        </Heading>
        {rating !== undefined ? <ReviewStars value={rating} size="sm" count={reviewCount} /> : null}
        <div className="mt-1">{price}</div>
        {meta}
      </div>
      {action ? <div className="relative z-[2] mt-auto">{action}</div> : null}
    </Card>
  );
}

import { cn } from "@ux-sting/utils";
import type { ReactNode } from "react";
import { Avatar } from "../avatar/avatar.js";
import { Card, CardLink } from "../card/card.js";
import { Image } from "../media/image.js";

export interface ArticleCardProps {
  title: string;
  href: string;
  excerpt?: ReactNode;
  image?: { src: string; alt: string };
  category?: ReactNode;
  author?: { name: string; avatar?: string; href?: string };
  /** Display date string and machine-readable `dateTime`. */
  date?: { display: ReactNode; dateTime: string };
  readingTime?: ReactNode;
  layout?: "vertical" | "horizontal" | "featured";
  headingLevel?: 2 | 3 | 4;
  className?: string;
}

/** Editorial card (blog, news, guides) rendered as an `<article>`. */
export function ArticleCard({
  title,
  href,
  excerpt,
  image,
  category,
  author,
  date,
  readingTime,
  layout = "vertical",
  headingLevel = 3,
  className,
}: ArticleCardProps) {
  const Heading = `h${headingLevel}` as const;
  const featured = layout === "featured";
  return (
    <Card
      asChild
      variant="ghost"
      className={cn("gap-3", layout === "horizontal" && "sm:flex-row sm:gap-5", className)}
    >
      <article>
        {image ? (
          <div
            className={cn(
              "overflow-hidden rounded-xl",
              layout === "horizontal" && "sm:w-2/5 sm:shrink-0",
            )}
          >
            <Image
              src={image.src}
              alt={image.alt}
              ratio={featured ? 16 / 9 : 3 / 2}
              radius="none"
              className="transition-transform duration-(--ui-duration-slow) group-hover/card:scale-[1.02]"
            />
          </div>
        ) : null}
        <div className="grid content-start gap-2">
          {category ? (
            <p className="text-xs font-semibold uppercase tracking-wide text-primary">{category}</p>
          ) : null}
          <Heading
            className={cn(
              "font-semibold leading-snug tracking-tight text-foreground text-balance",
              featured ? "text-2xl sm:text-3xl" : "text-lg",
            )}
          >
            <CardLink href={href}>{title}</CardLink>
          </Heading>
          {excerpt ? (
            <p
              className={cn("text-muted-foreground", featured ? "text-md" : "line-clamp-3 text-sm")}
            >
              {excerpt}
            </p>
          ) : null}
          {author || date || readingTime ? (
            <div className="relative z-[2] mt-1 flex flex-wrap items-center gap-x-2 gap-y-1 text-sm text-muted-foreground">
              {author ? (
                <span className="inline-flex items-center gap-2">
                  <Avatar size="xs" src={author.avatar} name={author.name} alt="" />
                  {author.href ? (
                    <a href={author.href} className="font-medium text-foreground hover:underline">
                      {author.name}
                    </a>
                  ) : (
                    <span className="font-medium text-foreground">{author.name}</span>
                  )}
                </span>
              ) : null}
              {date ? (
                <>
                  {author ? <span aria-hidden>·</span> : null}
                  <time dateTime={date.dateTime}>{date.display}</time>
                </>
              ) : null}
              {readingTime ? (
                <>
                  <span aria-hidden>·</span>
                  <span>{readingTime}</span>
                </>
              ) : null}
            </div>
          ) : null}
        </div>
      </article>
    </Card>
  );
}

"use client";
import { ClockIcon } from "@ux-sting/icons";
import { cn } from "@ux-sting/utils";
import type { ReactNode } from "react";
import { useLocale } from "../../provider/context.js";
import { Card, CardLink } from "../card/card.js";
import { Image } from "../media/image.js";
import { Location } from "../location/location.js";

export interface EventCardProps {
  title: string;
  href?: string;
  start: Date;
  end?: Date;
  venue?: ReactNode;
  image?: { src: string; alt: string };
  price?: ReactNode;
  /** e.g. `<AvatarGroup>` of attendees or "120 going". */
  attendees?: ReactNode;
  badges?: ReactNode;
  action?: ReactNode;
  headingLevel?: 2 | 3 | 4;
  className?: string;
}

/** Event listing with a localized date block and time range. */
export function EventCard({
  title,
  href,
  start,
  end,
  venue,
  image,
  price,
  attendees,
  badges,
  action,
  headingLevel = 3,
  className,
}: EventCardProps) {
  const { locale } = useLocale();
  const Heading = `h${headingLevel}` as const;
  const month = new Intl.DateTimeFormat(locale, { month: "short" }).format(start);
  const day = new Intl.DateTimeFormat(locale, { day: "numeric" }).format(start);
  const timeFmt = new Intl.DateTimeFormat(locale, {
    weekday: "short",
    hour: "numeric",
    minute: "2-digit",
  });
  const time = end ? timeFmt.formatRange(start, end) : timeFmt.format(start);
  return (
    <Card interactive={Boolean(href)} className={className}>
      {image ? (
        <div className="relative">
          <Image src={image.src} alt={image.alt} ratio={16 / 9} radius="none" />
          {badges ? <div className="absolute start-3 top-3 flex gap-1.5">{badges}</div> : null}
        </div>
      ) : null}
      <div className="flex gap-4 p-4">
        <time
          dateTime={start.toISOString()}
          className="flex h-14 w-12 shrink-0 flex-col items-center justify-center rounded-lg border border-border bg-surface"
        >
          <span className="text-xs font-semibold uppercase text-primary">{month}</span>
          <span className="text-lg font-bold leading-none tabular-nums">{day}</span>
        </time>
        <div className="grid min-w-0 flex-1 gap-1.5">
          <Heading className="font-semibold leading-snug">
            {href ? <CardLink href={href}>{title}</CardLink> : title}
          </Heading>
          <p className="flex items-center gap-1.5 text-sm text-muted-foreground [&_svg]:size-4">
            <ClockIcon aria-hidden />
            {time}
          </p>
          {venue ? <Location address={venue} /> : null}
          {price || attendees ? (
            <div className={cn("mt-1 flex flex-wrap items-center justify-between gap-2")}>
              {attendees}
              {price}
            </div>
          ) : null}
          {action ? <div className="relative z-[2] mt-2">{action}</div> : null}
        </div>
      </div>
    </Card>
  );
}

import { cn } from "@ux-sting/utils";
import type { ReactNode } from "react";
