"use client";
import { useControllableState } from "@ux-sting/hooks";
import { StarIcon } from "@ux-sting/icons";
import { cn } from "@ux-sting/utils";
import { forwardRef, useId, useState, type HTMLAttributes } from "react";
import { useLocale, useMessages } from "../../provider/context.js";

const sizeClass = { sm: "size-3.5", md: "size-4", lg: "size-5", xl: "size-6" };

export interface ReviewStarsProps extends HTMLAttributes<HTMLSpanElement> {
  /** Rating value, supports fractions (4.5). */
  value: number;
  max?: number;
  size?: keyof typeof sizeClass;
  /** Show the numeric value. */
  showValue?: boolean;
  /** Number of reviews, shown as "(128)". */
  count?: number;
}

/**
 * Read-only star rating with fractional fill. Announced as text
 * ("4.5 out of 5 stars"), never by color alone. Server-compatible.
 */
export const ReviewStars = forwardRef<HTMLSpanElement, ReviewStarsProps>(function ReviewStars(
  { value, max = 5, size = "md", showValue, count, className, ...props },
  ref,
) {
  const messages = useMessages();
  const { locale } = useLocale();
  const nf = new Intl.NumberFormat(locale, { maximumFractionDigits: 1 });
  return (
    <span ref={ref} className={cn("inline-flex items-center gap-1.5", className)} {...props}>
      <span
        role="img"
        aria-label={messages.rating(Number(value.toFixed(1)), max)}
        className="relative inline-flex"
      >
        <span className="flex text-border-strong" aria-hidden>
          {Array.from({ length: max }, (_, i) => (
            <StarIcon key={i} className={cn(sizeClass[size], "fill-current")} />
          ))}
        </span>
        <span
          className="absolute inset-0 flex overflow-hidden text-warning"
          style={{ width: `${(Math.max(0, Math.min(value, max)) / max) * 100}%` }}
          aria-hidden
        >
          {Array.from({ length: max }, (_, i) => (
            <StarIcon key={i} className={cn(sizeClass[size], "shrink-0 fill-current")} />
          ))}
        </span>
      </span>
      {showValue ? (
        <span className="text-sm font-semibold tabular-nums">{nf.format(value)}</span>
      ) : null}
      {count !== undefined ? (
        <span className="text-sm tabular-nums text-muted-foreground">({nf.format(count)})</span>
      ) : null}
    </span>
  );
});

export interface RatingProps extends Omit<
  HTMLAttributes<HTMLDivElement>,
  "onChange" | "defaultValue"
> {
  value?: number;
  defaultValue?: number;
  onValueChange?: (value: number) => void;
  max?: number;
  size?: keyof typeof sizeClass;
  readOnly?: boolean;
  disabled?: boolean;
  name?: string;
  /** Accessible group label, e.g. "Rate this restaurant". */
  label?: string;
}

/**
 * Interactive star rating implemented as a native radio group, so it is
 * keyboard accessible (arrows) and form-submittable.
 */
export const Rating = forwardRef<HTMLDivElement, RatingProps>(function Rating(
  {
    value: valueProp,
    defaultValue = 0,
    onValueChange,
    max = 5,
    size = "lg",
    readOnly,
    disabled,
    name,
    label = "Rating",
    className,
    ...props
  },
  ref,
) {
  const [value, setValue] = useControllableState({
    value: valueProp,
    defaultValue,
    onChange: onValueChange,
  });
  const [hover, setHover] = useState<number | null>(null);
  const messages = useMessages();
  const autoName = `rating${useId().replace(/:/g, "")}`;
  const groupName = name ?? autoName;
  if (readOnly) return <ReviewStars value={value} max={max} size={size} className={className} />;
  const shown = hover ?? value;
  return (
    <div
      ref={ref}
      role="radiogroup"
      aria-label={label}
      aria-disabled={disabled || undefined}
      className={cn("inline-flex items-center gap-0.5", disabled && "opacity-50", className)}
      onPointerLeave={() => setHover(null)}
      {...props}
    >
      {Array.from({ length: max }, (_, i) => {
        const star = i + 1;
        return (
          <label
            key={star}
            className="ui-hit-area relative cursor-pointer rounded-sm has-[:focus-visible]:ring-2 has-[:focus-visible]:ring-ring"
            onPointerEnter={() => !disabled && setHover(star)}
          >
            <input
              type="radio"
              className="sr-only"
              name={groupName}
              value={star}
              checked={value === star}
              disabled={disabled}
              aria-label={messages.rating(star, max)}
              onChange={() => setValue(star)}
            />
            <StarIcon
              aria-hidden
              className={cn(
                sizeClass[size],
                "transition-colors",
                star <= shown ? "fill-warning text-warning" : "text-border-strong",
              )}
            />
          </label>
        );
      })}
    </div>
  );
});

"use client";
import { cn } from "@ux-sting/utils";
import { forwardRef, type HTMLAttributes, type ReactNode } from "react";
import { useLocale } from "../../provider/context.js";

export interface PriceProps extends HTMLAttributes<HTMLSpanElement> {
  amount: number;
  /** ISO 4217 code, e.g. "USD", "EUR", "MAD". */
  currency: string;
  /** Previous price; rendered struck through with an accessible label. */
  compareAt?: number;
  /** Suffix such as "/ night" or "per month". */
  period?: ReactNode;
  size?: "sm" | "md" | "lg" | "xl";
  /** Label for the previous price (localize). */
  compareAtLabel?: string;
  fractionDigits?: number;
  locale?: string;
}

const sizeClass = { sm: "text-sm", md: "text-md", lg: "text-xl", xl: "text-3xl" };

/** Locale-aware price with optional discount and period. Tabular figures. */
export const Price = forwardRef<HTMLSpanElement, PriceProps>(function Price(
  {
    amount,
    currency,
    compareAt,
    period,
    size = "md",
    compareAtLabel = "Original price",
    fractionDigits,
    locale: localeProp,
    className,
    ...props
  },
  ref,
) {
  const { locale } = useLocale();
  const fmt = new Intl.NumberFormat(localeProp ?? locale, {
    style: "currency",
    currency,
    minimumFractionDigits: fractionDigits,
    maximumFractionDigits: fractionDigits,
  });
  return (
    <span
      ref={ref}
      className={cn("inline-flex flex-wrap items-baseline gap-x-1.5", className)}
      {...props}
    >
      <span className={cn("font-semibold tabular-nums text-foreground", sizeClass[size])}>
        {fmt.format(amount)}
      </span>
      {compareAt !== undefined && compareAt > amount ? (
        <span className="text-sm tabular-nums text-muted-foreground line-through">
          <span className="sr-only">{compareAtLabel}: </span>
          {fmt.format(compareAt)}
        </span>
      ) : null}
      {period ? <span className="text-sm text-muted-foreground">{period}</span> : null}
    </span>
  );
});

export interface PriceRangeProps extends HTMLAttributes<HTMLSpanElement> {
  min: number;
  max: number;
  currency: string;
  fractionDigits?: number;
}

export const PriceRange = forwardRef<HTMLSpanElement, PriceRangeProps>(function PriceRange(
  { min, max, currency, fractionDigits = 0, className, ...props },
  ref,
) {
  const { locale } = useLocale();
  const fmt = new Intl.NumberFormat(locale, {
    style: "currency",
    currency,
    maximumFractionDigits: fractionDigits,
    minimumFractionDigits: fractionDigits,
  });
  const text =
    typeof fmt.formatRange === "function"
      ? fmt.formatRange(min, max)
      : `${fmt.format(min)} – ${fmt.format(max)}`;
  return (
    <span ref={ref} className={cn("font-medium tabular-nums", className)} {...props}>
      {text}
    </span>
  );
});

export interface PriceLevelProps extends HTMLAttributes<HTMLSpanElement> {
  /** 1–max, e.g. 2 renders "$$" of "$$$$". */
  level: number;
  max?: number;
  symbol?: string;
  /** Accessible text, e.g. "Moderate price" (localize). */
  label?: string;
}

/** Relative price indicator ($ – $$$$) for places and restaurants. */
export const PriceLevel = forwardRef<HTMLSpanElement, PriceLevelProps>(function PriceLevel(
  { level, max = 4, symbol = "$", label, className, ...props },
  ref,
) {
  return (
    <span
      ref={ref}
      role="img"
      aria-label={label ?? `Price level ${level} of ${max}`}
      className={cn("inline-flex font-medium tracking-wider", className)}
      {...props}
    >
      <span aria-hidden className="text-foreground">
        {symbol.repeat(level)}
      </span>
      <span aria-hidden className="text-border-strong">
        {symbol.repeat(Math.max(0, max - level))}
      </span>
    </span>
  );
});

/** Formats a number as currency inline: `<Currency value={12} currency="EUR" />`. */
export function Currency({
  value,
  currency,
  fractionDigits,
  className,
}: {
  value: number;
  currency: string;
  fractionDigits?: number;
  className?: string;
}) {
  const { locale } = useLocale();
  return (
    <span className={cn("tabular-nums", className)}>
      {new Intl.NumberFormat(locale, {
        style: "currency",
        currency,
        minimumFractionDigits: fractionDigits,
        maximumFractionDigits: fractionDigits,
      }).format(value)}
    </span>
  );
}

