  activeCount?: number;
  onClear?: () => void;
  clearLabel?: string;
  /** Mobile "Show results" button label and handler. */
  applyLabel?: ReactNode;
  onApply?: () => void;
  className?: string;
}

/**
 * Filters as a sidebar on desktop and a bottom/side sheet on mobile, from
 * the same children. Pair with `FilterChips` to show applied filters.
 */
export function FilterPanel({
  title = "Filters",
  children,
  activeCount = 0,
  onClear,
  clearLabel = "Clear all",
  applyLabel = "Show results",
  onApply,
  className,
}: FilterPanelProps) {
  const [open, setOpen] = useState(false);
  const header = (
    <div className="flex items-center justify-between gap-2">
      <h2 className="text-md font-semibold">{title}</h2>
      {onClear && activeCount > 0 ? (
        <button
          type="button"
          onClick={onClear}
          className="rounded-xs text-sm font-medium text-primary underline-offset-4 outline-none hover:underline focus-visible:ring-2 focus-visible:ring-ring"
        >
          {clearLabel}
        </button>
      ) : null}
    </div>
  );
  return (
    <>
      <aside
        aria-label={typeof title === "string" ? title : undefined}
        className={cn(
          // Follows the page while results scroll; scrolls itself if taller than the viewport.
          // Offset defaults to below a 4rem sticky header; override with --ui-sticky-offset.
          "hidden w-full flex-col gap-4 lg:sticky lg:top-(--ui-sticky-offset,5rem) lg:flex lg:max-h-[calc(100dvh-var(--ui-sticky-offset,5rem)-1rem)] lg:self-start lg:overflow-y-auto lg:pe-1",
          className,
