          </SheetTrigger>
          <SheetContent side="bottom" className="max-h-[90dvh]">
            <SheetHeader>
              <SheetTitle>{title}</SheetTitle>
            </SheetHeader>
            <SheetBody className="grid divide-y divide-border py-0">{children}</SheetBody>
            <SheetFooter>
              {onClear ? (
                <Button variant="outline" onClick={onClear}>
