"use client";
import { useControllableState } from "@ux-sting/hooks";
import { MinusIcon, PlusIcon } from "@ux-sting/icons";
import { clamp, cn } from "@ux-sting/utils";
import { forwardRef, useEffect, useId, useState, type InputHTMLAttributes } from "react";
import { useField, useFieldControlProps } from "../../lib/field.js";
import { useMessages } from "../../provider/context.js";

const sizes = {
  sm: { root: "h-8", button: "w-8 [&_svg]:size-3.5", input: "w-10 text-sm" },
  md: { root: "h-10", button: "w-10 [&_svg]:size-4", input: "w-12 text-md" },
  lg: { root: "h-12", button: "w-12 [&_svg]:size-5", input: "w-14 text-lg" },
};

export interface QuantitySelectorProps extends Omit<
  InputHTMLAttributes<HTMLInputElement>,
  "type" | "value" | "defaultValue" | "onChange" | "min" | "max" | "step" | "size"
> {
  value?: number;
  defaultValue?: number;
  onValueChange?: (value: number) => void;
  /** Default 1. */
  min?: number;
  /** Defaults to `stock` when given. */
  max?: number;
  step?: number;
  /** Units available; shows "N in stock" under the control and caps the value. */
  stock?: number;
  size?: keyof typeof sizes;
  /** Stretch to the container width (mobile add-to-cart bars). */
  fullWidth?: boolean;
}

/**
 * Cart quantity control: − / input / + with clamping to stock. The input is a
 * native number field (spinbutton), so arrows, typing and form submission
 * work; the buttons are real tab stops, sized for touch. Adapted from the
 * Storefront UI QuantitySelector block (MIT).
 */
export const QuantitySelector = forwardRef<HTMLInputElement, QuantitySelectorProps>(
  function QuantitySelector(
    {
      value: valueProp,
      defaultValue,
      onValueChange,
      min = 1,
      max: maxProp,
      step = 1,
      stock,
      size = "md",
      fullWidth,
      disabled,
      className,
      onBlur,
      onKeyDown,
      "aria-describedby": describedByProp,
      ...props
    },
    ref,
  ) {
    const messages = useMessages();
    const field = useField();
    const max = maxProp ?? stock ?? Infinity;
    const [value, setValue] = useControllableState({
      value: valueProp,
      defaultValue: defaultValue ?? min,
      onChange: onValueChange,
    });
    const [text, setText] = useState(String(value));
    useEffect(() => setText(String(value)), [value]);

    const autoId = useId();
    const stockId = `qty${autoId.replace(/:/g, "")}-stock`;
    const describedBy =
      [describedByProp, stock !== undefined ? stockId : undefined].filter(Boolean).join(" ") ||
      undefined;
    const control = useFieldControlProps({
      ...props,
      disabled,
      "aria-describedby": describedBy,
    });
    const inputId = control.id ?? `qty${autoId.replace(/:/g, "")}`;

    const commit = (n: number) => {
      const next = Number.isFinite(n) ? clamp(Math.round(n / step) * step, min, max) : value;
      setValue(next);
      setText(String(next));
    };
    const s = sizes[size];
    const buttonClass = cn(
      "ui-hit-area inline-flex h-full shrink-0 items-center justify-center text-foreground outline-none transition-colors",
      "hover:bg-accent focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring",
      "disabled:cursor-not-allowed disabled:text-muted-foreground disabled:hover:bg-transparent",
      s.button,
    );

    return (
      <div className={cn("inline-grid gap-1", fullWidth ? "w-full" : "w-fit", className)}>
        <div
          className={cn(
            "flex items-stretch overflow-hidden rounded-md border border-input bg-background shadow-xs",
            disabled && "opacity-50",
            s.root,
          )}
        >
          <button
            type="button"
            aria-controls={inputId}
            aria-label={messages.decrement}
            className={cn(buttonClass, "border-e border-input")}
            disabled={disabled || value <= min}
            onClick={() => commit(value - step)}
          >
            <MinusIcon />
          </button>
          <input
            ref={ref}
            type="number"
            inputMode="numeric"
            // A Field label or aria-labelledby names the input; otherwise fall back to "Quantity".
            aria-label={field || props["aria-labelledby"] ? undefined : messages.quantity}
            {...control}
            id={inputId}
            min={min}
            max={Number.isFinite(max) ? max : undefined}
            step={step}
            value={text}
            className={cn(
              "ui-number-input min-w-0 grow appearance-none bg-transparent text-center font-medium tabular-nums outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring",
              "[&::-webkit-inner-spin-button]:appearance-none [&::-webkit-outer-spin-button]:appearance-none [-moz-appearance:textfield]",
              s.input,
            )}
            onChange={(e) => setText(e.target.value)}
            onBlur={(e) => {
              commit(text === "" ? min : Number(text));
              onBlur?.(e);
            }}
            onKeyDown={(e) => {
              onKeyDown?.(e);
              if (e.defaultPrevented) return;
              const keys: Record<string, number | undefined> = {
                ArrowUp: value + step,
                ArrowDown: value - step,
                Home: min,
                End: Number.isFinite(max) ? max : undefined,
                Enter: text === "" ? min : Number(text),
              };
              const next = keys[e.key];
              if (next === undefined) return;
              e.preventDefault();
              commit(next);
            }}
          />
          <button
            type="button"
            aria-controls={inputId}
            aria-label={messages.increment}
            className={cn(buttonClass, "border-s border-input")}
            disabled={disabled || value >= max}
            onClick={() => commit(value + step)}
          >
            <PlusIcon />
          </button>
        </div>
        {stock !== undefined ? (
          <p id={stockId} className="text-center text-xs text-muted-foreground">
            {messages.inStock(stock)}
          </p>
        ) : null}
      </div>
    );
  },
);

"use client";
import * as RadioGroupPrimitive from "@radix-ui/react-radio-group";
import { CheckIcon } from "@ux-sting/icons";
import { cn } from "@ux-sting/utils";
import { forwardRef, type ComponentPropsWithoutRef, type ReactNode } from "react";
import { useFieldControlProps } from "../../lib/field.js";
import { useMessages } from "../../provider/context.js";

export interface SwatchGroupProps extends Omit<
  ComponentPropsWithoutRef<typeof RadioGroupPrimitive.Root>,
  "orientation"
> {
  invalid?: boolean;
}

/**
 * Product variant picker (color, size, material). A single-select radio group:
 * one tab stop, arrow keys move and select, form-submittable via `name`.
 * Pattern adapted from Storefront UI's product details block (MIT).
 */
export const SwatchGroup = forwardRef<HTMLDivElement, SwatchGroupProps>(function SwatchGroup(
  { className, invalid, loop = true, ...props },
  ref,
) {
  const control = useFieldControlProps({ ...props, "aria-invalid": invalid || undefined });
  const { id: _id, ...rest } = control;
  return (
    <RadioGroupPrimitive.Root
      ref={ref}
      orientation="horizontal"
      loop={loop}
      className={cn("flex flex-wrap gap-2", className)}
      {...rest}
    />
  );
});

export interface SwatchProps extends Omit<
  ComponentPropsWithoutRef<typeof RadioGroupPrimitive.Item>,
  "children" | "color"
> {
  /** Accessible and visible name, e.g. "Sand" or "M". */
  label: string;
  /** CSS color (or gradient) for a color swatch. Omit for a text swatch ("S", "M", "L"). */
  color?: string;
  /** Sold out: still listed and announced, but crossed out and not selectable. */
  unavailable?: boolean;
  /** Custom content for text swatches (defaults to `label`). */
  children?: ReactNode;
  size?: "sm" | "md" | "lg";
}

const colorSize = { sm: "size-7", md: "size-9", lg: "size-11" };
const textSize = {
  sm: "h-8 min-w-8 px-2 text-xs",
  md: "h-10 min-w-10 px-3 text-sm",
  lg: "h-12 min-w-12 px-4 text-md",
};

export const Swatch = forwardRef<HTMLButtonElement, SwatchProps>(function Swatch(
  { label, color, unavailable, disabled, size = "md", className, children, ...props },
  ref,
) {
  const messages = useMessages();
  const isColor = color !== undefined;
  const crossOut = unavailable ? (
    <span
      aria-hidden
      className="pointer-events-none absolute inset-x-[-20%] top-1/2 h-px -rotate-45 bg-muted-foreground"
    />
  ) : null;
  return (
    <RadioGroupPrimitive.Item
      ref={ref}
      aria-label={unavailable ? `${label}, ${messages.unavailable}` : label}
      title={label}
      disabled={disabled || unavailable}
      className={cn(
        "ui-hit-area group/swatch relative inline-flex shrink-0 items-center justify-center overflow-hidden outline-none transition-[box-shadow,border-color,background-color] duration-(--ui-duration-fast)",
        "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
        "disabled:cursor-not-allowed",
        isColor
          ? cn(
              "rounded-full border border-border-strong",
              "data-[state=checked]:ring-2 data-[state=checked]:ring-primary data-[state=checked]:ring-offset-2 data-[state=checked]:ring-offset-background",
              colorSize[size],
            )
          : cn(
              "rounded-md border border-input bg-background font-medium text-foreground tabular-nums",
              "hover:border-border-strong data-[state=checked]:border-primary data-[state=checked]:bg-primary-subtle data-[state=checked]:text-primary-subtle-foreground data-[state=checked]:ring-1 data-[state=checked]:ring-primary",
              "disabled:text-muted-foreground",
              textSize[size],
            ),
        className,
      )}
      {...props}
    >
      {isColor ? (
        <>
          <span aria-hidden className="absolute inset-0" style={{ background: color }} />
          <RadioGroupPrimitive.Indicator className="relative flex size-1/2 items-center justify-center rounded-full bg-background text-foreground shadow-xs [&_svg]:size-3">
            <CheckIcon />
          </RadioGroupPrimitive.Indicator>
        </>
      ) : (
        <span aria-hidden className={cn(unavailable && "opacity-60")}>
          {children ?? label}
        </span>
      )}
      {crossOut}
    </RadioGroupPrimitive.Item>
  );
});

"use client";
import { useControllableState } from "@ux-sting/hooks";
import { ChevronLeftIcon, ChevronRightIcon } from "@ux-sting/icons";
import { cn, getNextIndex } from "@ux-sting/utils";
import { forwardRef, useRef, type HTMLAttributes, type KeyboardEvent } from "react";
import { useLocale, useMessages } from "../../provider/context.js";
import { IconButton } from "../button/button.js";
import { Image } from "../media/image.js";

export interface ProductGalleryImage {
  src: string;
  alt: string;
  /** Smaller source for the thumbnail. Defaults to `src`. */
  thumbnail?: string;
}

export interface ProductGalleryProps extends Omit<HTMLAttributes<HTMLElement>, "onChange"> {
  images: ProductGalleryImage[];
  index?: number;
  defaultIndex?: number;
  onIndexChange?: (index: number) => void;
  /** Aspect ratio of the main image. Default 1 (square). */
  ratio?: number;
  /** Thumbnails below (default) or beside the image from `md` up. */
  thumbnails?: "bottom" | "start" | "none";
  /** Accessible name for the gallery (defaults to "Product images"). */
  label?: string;
}

/**
 * Product image viewer: main image with previous/next buttons and a thumbnail
 * strip. Thumbnails are one tab stop (arrow keys, Home/End, RTL-aware); the
 * current position is announced politely. Layout adapted from the
 * Storefront UI Gallery block (MIT).
 */
export const ProductGallery = forwardRef<HTMLElement, ProductGalleryProps>(function ProductGallery(
  {
    images,
    index: indexProp,
    defaultIndex = 0,
    onIndexChange,
    ratio = 1,
    thumbnails = "bottom",
    label,
    className,
    ...props
  },
  ref,
) {
  const messages = useMessages();
  const { dir } = useLocale();
  const [index, setIndex] = useControllableState({
    value: indexProp,
    defaultValue: defaultIndex,
    onChange: onIndexChange,
  });
  const listRef = useRef<HTMLDivElement>(null);
  const count = images.length;
  const current = images[Math.min(index, count - 1)];
  const go = (i: number) => setIndex((i + count) % count);

  const onThumbKeyDown = (e: KeyboardEvent) => {
    const next = getNextIndex(e.key, index, count, {
      orientation: thumbnails === "start" ? "both" : "horizontal",
      dir,
      loop: true,
    });
    if (next === null) return;
    e.preventDefault();
    setIndex(next);
    listRef.current?.querySelectorAll<HTMLButtonElement>("button")[next]?.focus();
  };

  if (!current) return null;
  const side = thumbnails === "start";

  return (
    <section
      ref={ref}
      aria-label={label ?? messages.productImages}
      className={cn("grid gap-3", side && "md:grid-cols-[4.5rem_1fr] md:items-start", className)}
      {...props}
    >
      <div className={cn("relative", side && "md:order-2")}>
        <Image
          key={current.src}
          src={current.src}
          alt={current.alt}
          ratio={ratio}
          radius="lg"
          className="bg-muted"
        />
        {count > 1 ? (
          <>
            <IconButton
              aria-label={messages.previous}
              variant="secondary"
              shape="circle"
              size="sm"
              className="absolute start-2 top-1/2 -translate-y-1/2 shadow-sm"
              onClick={() => go(index - 1)}
            >
              <ChevronLeftIcon className="rtl:rotate-180" />
            </IconButton>
            <IconButton
              aria-label={messages.next}
              variant="secondary"
              shape="circle"
              size="sm"
              className="absolute end-2 top-1/2 -translate-y-1/2 shadow-sm"
              onClick={() => go(index + 1)}
            >
              <ChevronRightIcon className="rtl:rotate-180" />
            </IconButton>
            <p aria-live="polite" className="sr-only">
              {messages.slideOf(index + 1, count)}
            </p>
          </>
        ) : null}
      </div>
      {count > 1 && thumbnails !== "none" ? (
        <div
          ref={listRef}
          role="group"
          aria-label={label ?? messages.productImages}
          onKeyDown={onThumbKeyDown}
          className={cn(
            "flex gap-2 overflow-x-auto p-1 [scrollbar-width:thin]",
            side &&
              "md:order-1 md:max-h-[32rem] md:flex-col md:overflow-x-visible md:overflow-y-auto",
          )}
        >
          {images.map((image, i) => (
            <button
              key={image.src}
              type="button"
              tabIndex={i === index ? 0 : -1}
              aria-label={messages.showImage(i + 1, count)}
              aria-current={i === index ? "true" : undefined}
              onClick={() => setIndex(i)}
              className={cn(
                "relative size-16 shrink-0 overflow-hidden rounded-md border-2 border-transparent bg-muted outline-none transition-[border-color,opacity] duration-(--ui-duration-fast)",
                "opacity-70 hover:opacity-100 focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
                "aria-[current=true]:border-primary aria-[current=true]:opacity-100",
              )}
            >
              {/* Decorative: the button's label names the image position. */}
              <img
                src={image.thumbnail ?? image.src}
                alt=""
                loading="lazy"
                decoding="async"
                className="size-full object-cover"
              />
            </button>
          ))}
        </div>
      ) : null}
    </section>
  );
});

"use client";
import { cn } from "@ux-sting/utils";
import { forwardRef, useId, type HTMLAttributes, type ReactNode } from "react";
import { useLocale, useMessages } from "../../provider/context.js";

export interface OrderSummaryLine {
  label: ReactNode;
  /** Amount in currency units. Discounts are given as positive numbers with `kind: "discount"`. */
  amount: number;
  /** `discount` renders as a deduction (−) with success styling and text. */
  kind?: "default" | "discount";
  /** Replaces the formatted amount, e.g. "Free" or "Calculated at checkout". */
  display?: ReactNode;
  /** Small secondary text under the label (e.g. a promo code). */
  hint?: ReactNode;
}

export interface OrderSummaryProps extends Omit<HTMLAttributes<HTMLElement>, "title"> {
  /** ISO 4217 code. */
  currency: string;
  lines: OrderSummaryLine[];
  /** Grand total. Computed from `lines` when omitted. */
  total?: number;
  /** Heading text (defaults to "Order summary"); `null` hides the heading. */
  title?: ReactNode;
  headingLevel?: 2 | 3 | 4;
  totalLabel?: ReactNode;
  /** Text under the total, e.g. "Taxes included". */
  note?: ReactNode;
  locale?: string;
  /** Promo-code field, checkout button, trust badges… rendered below the total. */
  children?: ReactNode;
}

/**
 * Cart and checkout totals as a description list: subtotal, discounts,
 * shipping, tax and a prominent total. Amounts are locale-formatted with
 * tabular figures; discounts read as deductions in text, not only by color.
 * Adapted from the Storefront UI OrderSummary block (MIT).
 */
export const OrderSummary = forwardRef<HTMLElement, OrderSummaryProps>(function OrderSummary(
  {
    currency,
    lines,
    total: totalProp,
    title,
    headingLevel = 2,
    totalLabel,
    note,
    locale: localeProp,
    className,
    children,
    ...props
  },
  ref,
) {
  const { locale } = useLocale();
  const messages = useMessages();
  const fmt = new Intl.NumberFormat(localeProp ?? locale, { style: "currency", currency });
  const total =
    totalProp ??
    lines.reduce((sum, l) => sum + (l.kind === "discount" ? -Math.abs(l.amount) : l.amount), 0);
  const Heading = `h${headingLevel}` as const;
  const headingId = `order-summary${useId().replace(/:/g, "")}`;
  const showHeading = title !== null;

  return (
    <section
      ref={ref}
      aria-labelledby={showHeading ? headingId : undefined}
      aria-label={showHeading ? undefined : messages.orderSummary}
      className={cn(
        "grid gap-4 rounded-xl border border-border bg-card p-4 text-card-foreground sm:p-6",
        className,
      )}
      {...props}
    >
      {showHeading ? (
        <Heading id={headingId} className="text-lg font-semibold text-balance">
          {title ?? messages.orderSummary}
        </Heading>
      ) : null}
      <dl className="grid gap-2.5 text-sm">
        {lines.map((line, i) => {
          const discount = line.kind === "discount";
          return (
            <div key={i} className="flex items-start justify-between gap-4">
              <dt className="grid gap-0.5 text-muted-foreground">
                <span>{line.label}</span>
                {line.hint ? <span className="text-xs">{line.hint}</span> : null}
              </dt>
              <dd
                className={cn(
                  "shrink-0 text-end tabular-nums",
                  discount ? "font-medium text-success" : "text-foreground",
                )}
              >
                {line.display ??
                  (discount ? `−${fmt.format(Math.abs(line.amount))}` : fmt.format(line.amount))}
              </dd>
            </div>
          );
        })}
        <div className="mt-1.5 flex items-baseline justify-between gap-4 border-t border-border pt-4">
          <dt className="text-md font-semibold text-foreground">{totalLabel ?? messages.total}</dt>
          <dd className="text-xl font-semibold tabular-nums text-foreground">
            {fmt.format(total)}
          </dd>
        </div>
      </dl>
      {note ? <p className="-mt-2 text-end text-xs text-muted-foreground">{note}</p> : null}
      {children ? <div className="grid gap-3">{children}</div> : null}
    </section>
  );
});

"use client";
import { MenuIcon } from "@ux-sting/icons";
import { cn } from "@ux-sting/utils";
import { useState, type ReactNode } from "react";
import { useMessages } from "../../provider/context.js";
import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from "../accordion/accordion.js";
import { IconButton } from "../button/button.js";
import {
  NavigationMenu,
  NavigationMenuContent,
  NavigationMenuItem,
  NavigationMenuLink,
  NavigationMenuList,
  NavigationMenuTrigger,
  navigationMenuTriggerStyle,
} from "../navigation-menu/navigation-menu.js";
import {
  Sheet,
  SheetBody,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetTrigger,
} from "../sheet/sheet.js";

export interface MegaMenuLink {
  label: string;
  href: string;
  description?: string;
}

export interface MegaMenuColumn {
  title: string;
  links: MegaMenuLink[];
}

export interface MegaMenuItem {
  label: string;
  /** A plain top-level link. */
  href?: string;
  /** Columns of links shown in the panel. */
  columns?: MegaMenuColumn[];
  /** Promo tile at the end of the panel (image card, campaign). Desktop only. */
  featured?: ReactNode;
  /** "See all" link under the columns. */
  allHref?: string;
  allLabel?: string;
}

export interface MegaMenuProps {
  items: MegaMenuItem[];
  /** Accessible name of the navigation landmark. Default "Main". */
  label?: string;
  /** href of the current page, marked with `aria-current="page"`. */
  currentHref?: string;
  className?: string;
}

/**
 * Store navigation: category panels with link columns and an optional promo
 * tile on desktop (hover, click or keyboard), and a side sheet with
 * collapsible categories below `lg`. Built from one data structure so both
 * stay in sync. Adapted from the Storefront UI MegaMenu block (MIT).
 */
export function MegaMenu({ items, label = "Main", currentHref, className }: MegaMenuProps) {
  const messages = useMessages();
  const [open, setOpen] = useState(false);
  const current = (href: string) => (href === currentHref ? "page" : undefined);

  return (
    <div className={cn("flex items-center", className)}>
      <NavigationMenu aria-label={label} className="hidden max-w-none lg:flex">
        <NavigationMenuList>
          {items.map((item) =>
            item.columns?.length ? (
              <NavigationMenuItem key={item.label}>
                <NavigationMenuTrigger>{item.label}</NavigationMenuTrigger>
                <NavigationMenuContent className="md:w-[min(56rem,calc(100vw-2rem))]">
                  <div
                    className={cn(
                      "grid gap-6 p-2",
                      item.featured ? "md:grid-cols-[1fr_16rem]" : undefined,
                    )}
                  >
                    <div className="grid gap-6 sm:grid-cols-2 md:grid-cols-3">
                      {item.columns.map((column) => (
                        <div key={column.title} className="grid content-start gap-1">
                          <p className="px-3 pb-1 text-xs font-semibold uppercase tracking-wide text-muted-foreground">
                            {column.title}
                          </p>
                          <ul className="grid gap-0.5">
                            {column.links.map((link) => (
                              <li key={link.href}>
                                <NavigationMenuLink
                                  href={link.href}
                                  aria-current={current(link.href)}
                                  className="py-2"
                                >
                                  <span className="font-medium text-foreground">{link.label}</span>
                                  {link.description ? (
                                    <span className="mt-0.5 block text-xs text-muted-foreground">
                                      {link.description}
                                    </span>
                                  ) : null}
                                </NavigationMenuLink>
                              </li>
                            ))}
                          </ul>
                        </div>
                      ))}
                      {item.allHref ? (
                        <NavigationMenuLink
                          href={item.allHref}
                          className="col-span-full justify-self-start font-medium text-primary"
                        >
                          {item.allLabel ?? item.label}
                        </NavigationMenuLink>
                      ) : null}
                    </div>
                    {item.featured ? <div className="hidden md:block">{item.featured}</div> : null}
                  </div>
                </NavigationMenuContent>
              </NavigationMenuItem>
            ) : (
              <NavigationMenuItem key={item.label}>
                <NavigationMenuLink
                  href={item.href}
                  aria-current={item.href ? current(item.href) : undefined}
                  className={navigationMenuTriggerStyle}
                >
                  {item.label}
                </NavigationMenuLink>
              </NavigationMenuItem>
            ),
          )}
        </NavigationMenuList>
      </NavigationMenu>

      <Sheet open={open} onOpenChange={setOpen}>
        <SheetTrigger asChild>
          <IconButton aria-label={messages.openMenu} variant="ghost" className="lg:hidden">
            <MenuIcon />
          </IconButton>
        </SheetTrigger>
        <SheetContent side="start">
          <SheetHeader>
            <SheetTitle>{label}</SheetTitle>
          </SheetHeader>
          <SheetBody>
            <nav aria-label={label}>
              <Accordion type="single" collapsible>
                {items.map((item) =>
                  item.columns?.length ? (
                    <AccordionItem key={item.label} value={item.label}>
                      <AccordionTrigger>{item.label}</AccordionTrigger>
                      <AccordionContent>
                        <div className="grid gap-4">
                          {item.columns.map((column) => (
                            <div key={column.title} className="grid gap-1">
                              <p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">
                                {column.title}
                              </p>
                              <ul className="grid">
                                {column.links.map((link) => (
                                  <li key={link.href}>
                                    <a
                                      href={link.href}
                                      aria-current={current(link.href)}
                                      onClick={() => setOpen(false)}
                                      className="flex min-h-11 items-center rounded-md px-2 text-md outline-none hover:bg-accent focus-visible:ring-2 focus-visible:ring-ring aria-[current=page]:font-semibold aria-[current=page]:text-primary"
                                    >
                                      {link.label}
                                    </a>
                                  </li>
                                ))}
                              </ul>
                            </div>
                          ))}
                          {item.allHref ? (
                            <a
                              href={item.allHref}
                              onClick={() => setOpen(false)}
                              className="flex min-h-11 items-center rounded-md px-2 font-medium text-primary outline-none hover:bg-accent focus-visible:ring-2 focus-visible:ring-ring"
                            >
                              {item.allLabel ?? item.label}
                            </a>
                          ) : null}
                        </div>
                      </AccordionContent>
                    </AccordionItem>
                  ) : (
                    <a
                      key={item.label}
                      href={item.href}
                      aria-current={item.href ? current(item.href) : undefined}
                      onClick={() => setOpen(false)}
                      className="flex min-h-12 items-center border-b border-border text-md font-medium outline-none focus-visible:ring-2 focus-visible:ring-ring aria-[current=page]:text-primary"
                    >
                      {item.label}
                    </a>
                  ),
                )}
              </Accordion>
            </nav>
          </SheetBody>
        </SheetContent>
      </Sheet>
    </div>
  );
}

"use client";
import { Trash2Icon } from "@ux-sting/icons";
import { cn } from "@ux-sting/utils";
import { forwardRef, type HTMLAttributes, type ReactNode } from "react";
import { useMessages } from "../../provider/context.js";
import { IconButton } from "../button/button.js";
import { Image } from "../media/image.js";
import { Price } from "../price/price.js";
import { QuantitySelector } from "../quantity-selector/quantity-selector.js";

export interface CartLineItemOption {
  label: string;
  value: string;
}

export interface CartLineItemProps extends Omit<HTMLAttributes<HTMLDivElement>, "onChange"> {
  name: string;
  href?: string;
  image: { src: string; alt: string };
  /** Chosen variant, e.g. `[{ label: "Color", value: "Sand" }, { label: "Size", value: "M" }]`. */
  options?: CartLineItemOption[];
  /** Unit price. The line shows unit price × quantity. */
  price: number;
  /** Previous unit price (sale). */
  compareAt?: number;
  /** ISO 4217 code. */
  currency: string;
  quantity: number;
  onQuantityChange?: (quantity: number) => void;
  /** Units available; caps the quantity. */
  stock?: number;
  onRemove?: () => void;
  /** Small note such as "Only 2 left" or "Ships in 3 days". */
  meta?: ReactNode;
  headingLevel?: 2 | 3 | 4;
  /** Read-only line (order confirmation): shows "Qty: n" instead of the control. */
  readOnly?: boolean;
  /** Label for the read-only quantity. Default "Quantity". */
  quantityLabel?: string;
}

/**
 * One product in a cart or order: image, name, chosen options, line price,
 * quantity control and remove. Wrap lines in a `<ul>` with `<li>` per item.
 * Adapted from the Storefront UI cart line block (MIT).
 */
export const CartLineItem = forwardRef<HTMLDivElement, CartLineItemProps>(function CartLineItem(
  {
    name,
    href,
    image,
    options,
    price,
    compareAt,
    currency,
    quantity,
    onQuantityChange,
    stock,
    onRemove,
    meta,
    headingLevel = 3,
    readOnly,
    quantityLabel,
    className,
    ...props
  },
  ref,
) {
  const messages = useMessages();
  const Heading = `h${headingLevel}` as const;
  return (
    <div
      ref={ref}
      className={cn(
        "grid grid-cols-[5rem_1fr] gap-x-4 gap-y-3 py-4 sm:grid-cols-[6rem_1fr_auto]",
        className,
      )}
      {...props}
    >
      <Image
        src={image.src}
        alt={image.alt}
        ratio={1}
        radius="md"
        className="row-span-2 bg-muted sm:row-span-1"
      />
      <div className="grid min-w-0 content-start gap-1">
        <Heading className="line-clamp-2 text-sm font-medium text-foreground">
          {href ? (
            <a
              href={href}
              className="rounded-xs outline-none hover:underline focus-visible:ring-2 focus-visible:ring-ring"
            >
              {name}
            </a>
          ) : (
            name
          )}
        </Heading>
        {options?.length ? (
          <dl className="flex flex-wrap gap-x-3 gap-y-0.5 text-xs text-muted-foreground">
            {options.map((o) => (
              <div key={o.label} className="flex gap-1">
                <dt>{o.label}:</dt>
                <dd className="text-foreground">{o.value}</dd>
              </div>
            ))}
          </dl>
        ) : null}
        {meta ? <p className="text-xs text-muted-foreground">{meta}</p> : null}
      </div>
      <div className="col-start-2 flex flex-wrap items-center justify-between gap-3 sm:col-start-3 sm:row-start-1 sm:flex-col sm:items-end sm:justify-start">
        <Price
          amount={price * quantity}
          compareAt={compareAt !== undefined ? compareAt * quantity : undefined}
          currency={currency}
          className="sm:justify-end"
        />
        <div className="flex items-center gap-1">
          {readOnly ? (
            <span className="text-sm text-muted-foreground tabular-nums">
              {quantityLabel ?? messages.quantity}: {quantity}
            </span>
          ) : (
            <QuantitySelector
              size="sm"
              value={quantity}
              onValueChange={onQuantityChange}
              max={stock}
              aria-label={`${messages.quantity}, ${name}`}
            />
          )}
          {onRemove && !readOnly ? (
            <IconButton
              aria-label={messages.removeItem(name)}
              variant="ghost"
              size="sm"
              onClick={onRemove}
              className="text-muted-foreground hover:text-destructive"
            >
              <Trash2Icon />
            </IconButton>
          ) : null}
        </div>
      </div>
    </div>
  );
});

"use client";
import { LockIcon } from "@ux-sting/icons";
import { cn } from "@ux-sting/utils";
import { type ChangeEvent, type ReactNode } from "react";
import { Field, Fieldset } from "../field/field.js";
import { Input } from "../input/input.js";
import { NativeSelect } from "../native-select/native-select.js";

export interface AddressFieldsLabels {
  fullName: string;
  line1: string;
  line2: string;
  city: string;
  region: string;
  postalCode: string;
  country: string;
  phone: string;
  phoneHint: string;
}

const addressDefaults: AddressFieldsLabels = {
  fullName: "Full name",
  line1: "Address",
  line2: "Apartment, suite, etc. (optional)",
  city: "City",
  region: "State / region",
  postalCode: "Postal code",
  country: "Country",
  phone: "Phone",
  phoneHint: "For delivery questions only.",
};

export interface AddressFieldsProps {
  /** Group legend, e.g. "Shipping address". */
  legend: ReactNode;
  /**
   * Autofill section and field-name prefix. Field names are `<section>.<field>`
   * (`shipping.line1`), so a shipping and a billing group can share one Form.
   */
  section?: "shipping" | "billing";
  /** Country options; when omitted the country is a text field. */
  countries?: Array<{ value: string; label: string }>;
  defaultCountry?: string;
  /** Hide the region field (countries without states). */
  hideRegion?: boolean;
  /** Hide the phone field. */
  hidePhone?: boolean;
  labels?: Partial<AddressFieldsLabels>;
  disabled?: boolean;
  className?: string;
}

/**
 * Address block for checkout: visible labels, the right `autoComplete`
 * tokens per section (so browsers and password managers fill it in one
 * tap), mobile keyboards per field and required validation through `Form`.
 * Adapted from the Storefront UI checkout address block (MIT).
 */
export function AddressFields({
  legend,
  section = "shipping",
  countries,
  defaultCountry,
  hideRegion,
  hidePhone,
  labels: overrides,
  disabled,
  className,
}: AddressFieldsProps) {
  const l = { ...addressDefaults, ...overrides };
  const n = (key: string) => `${section}.${key}`;
  const ac = (token: string) => `${section} ${token}`;
  return (
    <Fieldset legend={legend} disabled={disabled} className={className}>
      <Field name={n("fullName")} label={l.fullName} required>
        <Input autoComplete={ac("name")} />
      </Field>
      <Field name={n("country")} label={l.country} required>
        {countries ? (
          <NativeSelect autoComplete={ac("country")} defaultValue={defaultCountry}>
            {countries.map((c) => (
              <option key={c.value} value={c.value}>
                {c.label}
              </option>
            ))}
          </NativeSelect>
        ) : (
          <Input autoComplete={ac("country-name")} defaultValue={defaultCountry} />
        )}
      </Field>
      <Field name={n("line1")} label={l.line1} required>
        <Input autoComplete={ac("address-line1")} />
      </Field>
      <Field name={n("line2")} label={l.line2}>
        <Input autoComplete={ac("address-line2")} />
      </Field>
      <div
        className={cn("grid gap-(--ui-stack-gap) sm:grid-cols-2", !hideRegion && "md:grid-cols-3")}
      >
        <Field name={n("city")} label={l.city} required>
          <Input autoComplete={ac("address-level2")} />
        </Field>
        {hideRegion ? null : (
          <Field name={n("region")} label={l.region}>
            <Input autoComplete={ac("address-level1")} />
          </Field>
        )}
        <Field name={n("postalCode")} label={l.postalCode} required>
          <Input autoComplete={ac("postal-code")} autoCapitalize="characters" />
        </Field>
      </div>
      {hidePhone ? null : (
        <Field name={n("phone")} label={l.phone} description={l.phoneHint}>
          <Input type="tel" inputMode="tel" autoComplete={ac("tel")} />
        </Field>
      )}
    </Fieldset>
  );
}

export interface PaymentFieldsLabels {
  cardNumber: string;
  nameOnCard: string;
  expiry: string;
  expiryHint: string;
  cvc: string;
  cvcHint: string;
  secure: ReactNode;
}

const paymentDefaults: PaymentFieldsLabels = {
  cardNumber: "Card number",
  nameOnCard: "Name on card",
  expiry: "Expiry date",
  expiryHint: "MM / YY",
  cvc: "Security code",
  cvcHint: "3 or 4 digits on the back of the card",
  secure: "Payments are encrypted and processed securely.",
};

/** Groups digits by four ("4242 4242 4242 4242") as the user types. */
function formatCardNumber(value: string): string {
  return value
    .replace(/\D/g, "")
    .slice(0, 19)
    .replace(/(\d{4})(?=\d)/g, "$1 ");
}

/** Inserts the " / " between month and year ("0827" → "08 / 27"). */
function formatExpiry(value: string): string {
  const digits = value.replace(/\D/g, "").slice(0, 4);
  return digits.length > 2 ? `${digits.slice(0, 2)} / ${digits.slice(2)}` : digits;
}

const reformat = (format: (v: string) => string) => (e: ChangeEvent<HTMLInputElement>) => {
  e.currentTarget.value = format(e.currentTarget.value);
};

export interface PaymentFieldsProps {
  legend: ReactNode;
  /** Field-name prefix. Default `"payment"` → `payment.cardNumber`. */
  name?: string;
  labels?: Partial<PaymentFieldsLabels>;
  /** Accepted-card logos or a wallet button row, shown under the legend. */
  accepted?: ReactNode;
  disabled?: boolean;
  className?: string;
}

/**
 * Card payment fields with `cc-*` autofill, numeric keyboards, as-you-type
 * formatting and format validation. For real payments, render your payment
 * provider's hosted fields inside the same layout instead, so card data
 * never touches your servers (PCI DSS).
 */
export function PaymentFields({
  legend,
  name = "payment",
  labels: overrides,
  accepted,
  disabled,
  className,
}: PaymentFieldsProps) {
  const l = { ...paymentDefaults, ...overrides };
  const n = (key: string) => `${name}.${key}`;
  return (
    <Fieldset legend={legend} disabled={disabled} className={className}>
      {accepted ? <div className="-mt-2 flex flex-wrap items-center gap-2">{accepted}</div> : null}
      <Field name={n("cardNumber")} label={l.cardNumber} required>
        <Input
          autoComplete="cc-number"
          inputMode="numeric"
          pattern="[0-9 ]{14,23}"
          maxLength={23}
          className="tabular-nums"
          onChange={reformat(formatCardNumber)}
        />
      </Field>
      <Field name={n("nameOnCard")} label={l.nameOnCard} required>
        <Input autoComplete="cc-name" />
      </Field>
      <div className="grid gap-(--ui-stack-gap) sm:grid-cols-2">
        <Field name={n("expiry")} label={l.expiry} description={l.expiryHint} required>
          <Input
            autoComplete="cc-exp"
            inputMode="numeric"
            pattern="(0[1-9]|1[0-2]) ?/ ?[0-9]{2}"
            maxLength={7}
            className="tabular-nums"
            onChange={reformat(formatExpiry)}
          />
        </Field>
        <Field name={n("cvc")} label={l.cvc} description={l.cvcHint} required>
          <Input
            autoComplete="cc-csc"
            inputMode="numeric"
            pattern="[0-9]{3,4}"
            maxLength={4}
            className="tabular-nums"
          />
        </Field>
      </div>
      <p className="flex items-center gap-1.5 text-xs text-muted-foreground">
        <LockIcon aria-hidden className="size-3.5 shrink-0" />
        {l.secure}
      </p>
    </Fieldset>
  );
}

"use client";
import { cn } from "@ux-sting/utils";
import type { ReactNode } from "react";
import { useLocale, useMessages } from "../../provider/context.js";
import { FilterChips, FilterPanel, type FilterChip } from "../filter-panel/filter-panel.js";

export interface ProductListingProps {
  /** Page heading, e.g. the category name. Rendered as the page's `h1`. */
  title: ReactNode;
  /** Short intro under the title. */
  description?: ReactNode;
  /** Breadcrumb above the title. */
  breadcrumb?: ReactNode;
  /** Total number of products for the current filters. Announced politely when it changes. */
  resultCount: number;
  /** FilterSection elements (categories, price, size, color…). */
  filters: ReactNode;
  /** Applied filters, shown as removable chips above the grid. */
  activeFilters?: FilterChip[];
  onRemoveFilter?: (id: string) => void;
  onClearFilters?: () => void;
  /** Sort control (e.g. a labelled NativeSelect), shown at the end of the toolbar. */
  sort?: ReactNode;
  /** The product grid. */
  children: ReactNode;
  /** Pagination under the grid. */
  pagination?: ReactNode;
  filtersTitle?: string;
  className?: string;
}

/**
 * Category page layout: heading and live result count, a filter sidebar
 * (a sheet on mobile, from the same filters), applied-filter chips, a sort
 * control, the product grid and pagination. Composes FilterPanel. Layout
 * adapted from the Storefront UI category page block (MIT).
 */
export function ProductListing({
  title,
  description,
  breadcrumb,
  resultCount,
  filters,
  activeFilters = [],
  onRemoveFilter,
  onClearFilters,
  sort,
  children,
  pagination,
  filtersTitle,
  className,
}: ProductListingProps) {
  const messages = useMessages();
  const { locale } = useLocale();
  const countText = messages
    .results(resultCount)
    .replace(String(resultCount), new Intl.NumberFormat(locale).format(resultCount));
  return (
    <div className={cn("grid gap-6", className)}>
      <header className="grid gap-2">
        {breadcrumb}
        <h1 className="text-2xl font-semibold tracking-tight text-balance sm:text-3xl">{title}</h1>
