import { cn } from "@ux-sting/utils";
import { forwardRef, type CSSProperties, type ElementType, type HTMLAttributes } from "react";

export type TextEffectPreset = "fade" | "blur" | "slide" | "scale";

export interface TextEffectProps extends Omit<HTMLAttributes<HTMLElement>, "children"> {
  /** The text to animate. Plain text only, so it can be split safely. */
  children: string;
  /** Element to render. Default `p`. */
  as?: ElementType;
  /** Animate per word or per character. Default `word`. */
  per?: "word" | "char";
  /** Entrance style. Default `fade`. */
  preset?: TextEffectPreset;
  /** Delay before the first piece, in ms. */
  delay?: number;
  /** Delay between pieces, in ms. Defaults to 60 (word) or 25 (char). */
  stagger?: number;
  /** Duration of each piece, in ms. Default 600. */
  duration?: number;
}

/**
 * Staggered text entrance in pure CSS: a server component with no client
 * JavaScript. Screen readers get the whole sentence once; the animated pieces
 * are hidden from them. Nothing moves under reduced motion. Inside a
 * `Reveal`, the animation waits until the text scrolls into view.
 */
export const TextEffect = forwardRef<HTMLElement, TextEffectProps>(function TextEffect(
  {
    children,
    as: Tag = "p",
    per = "word",
    preset = "fade",
    delay = 0,
    stagger,
    duration = 600,
    className,
    style,
    ...props
  },
  ref,
) {
  const words = children.split(/(\s+)/);
  let index = 0;
  const piece = (text: string, key: string | number) => (
    <span key={key} className="ui-text-effect-piece" style={{ "--ui-i": index++ } as CSSProperties}>
      {text}
    </span>
  );
  return (
    <Tag
      ref={ref}
      className={cn("ui-text-effect", className)}
      data-preset={preset}
      style={
        {
          "--ui-te-delay": `${delay}ms`,
          "--ui-te-stagger": `${stagger ?? (per === "char" ? 25 : 60)}ms`,
          "--ui-te-duration": `${duration}ms`,
          ...style,
        } as CSSProperties
      }
      {...props}
    >
      <span className="sr-only">{children}</span>
      <span aria-hidden>
        {words.map((word, i) =>
          /^\s+$/.test(word) || word === "" ? (
            word
          ) : per === "char" ? (
            <span key={i} className="inline-block whitespace-nowrap">
              {Array.from(word).map((char, j) => piece(char, j))}
            </span>
          ) : (
            piece(word, i)
          ),
        )}
      </span>
    </Tag>
  );
});

export interface TextShimmerProps extends HTMLAttributes<HTMLElement> {
  /** Element to render. Default `span`. */
  as?: ElementType;
  /** Seconds per sweep. Default 2. */
  duration?: number;
}

/**
 * A light sweep across text — for "Thinking…", "Generating…" and other
 * in-progress labels. Pure CSS; static under reduced motion and in forced
 * colors. Keep it to short status text, never body copy.
 */
export const TextShimmer = forwardRef<HTMLElement, TextShimmerProps>(function TextShimmer(
  { as: Tag = "span", duration = 2, className, style, ...props },
  ref,
) {
  return (
    <Tag
      ref={ref}
      className={cn("ui-text-shimmer", className)}
      style={{ "--ui-shimmer-duration": `${duration}s`, ...style } as CSSProperties}
      {...props}
    />
  );
});

"use client";
import { useInterval, usePrefersReducedMotion } from "@ux-sting/hooks";
import { cn } from "@ux-sting/utils";
import { forwardRef, useEffect, useState, type HTMLAttributes } from "react";

export interface RotatingTextProps extends HTMLAttributes<HTMLSpanElement> {
  /** Words or short phrases to cycle through. */
  words: string[];
  /** Time each word stays, in ms. Default 2500. */
  interval?: number;
  /** Stops on the current word. */
  paused?: boolean;
  /** What screen readers hear instead. Defaults to the words joined by commas. */
  srText?: string;
}

/**
 * Cycles through words in place ("Build apps that are fast / safe / yours").
 * All words share one grid cell, so the line never reflows. Screen readers
 * hear the full list once instead of every change; reduced motion keeps the
 * first word.
 */
export const RotatingText = forwardRef<HTMLSpanElement, RotatingTextProps>(function RotatingText(
  { words, interval = 2500, paused = false, srText, className, ...props },
  ref,
) {
  const reduced = usePrefersReducedMotion();
  const [index, setIndex] = useState(0);
  const running = !paused && !reduced && words.length > 1;
  useInterval(() => setIndex((i) => (i + 1) % words.length), running ? interval : null);
  return (
    <span ref={ref} className={cn("ui-rotating-text", className)} {...props}>
      <span className="sr-only">{srText ?? words.join(", ")}</span>
      <span aria-hidden className="inline-grid">
        {words.map((word, i) => (
          <span key={word} data-active={i === index ? "" : undefined}>
            {word}
          </span>
        ))}
      </span>
    </span>
  );
});

export interface TypewriterProps extends HTMLAttributes<HTMLSpanElement> {
  /** Text to type. Pass several to type, erase and loop through them. */
  text: string | string[];
  /** Ms per character. Default 45. */
  speed?: number;
  /** Pause on a finished phrase before erasing, in ms. Default 1800. */
  hold?: number;
  /** Show a blinking caret. Default `true`. */
  cursor?: boolean;
}

/**
 * Types text character by character. Space for the longest phrase is
 * reserved, so nothing below jumps. Screen readers and reduced motion get the
 * full text immediately; without JavaScript the text is simply shown.
 */
export const Typewriter = forwardRef<HTMLSpanElement, TypewriterProps>(function Typewriter(
  { text, speed = 45, hold = 1800, cursor = true, className, ...props },
  ref,
) {
  const phrases = Array.isArray(text) ? text : [text];
  const reduced = usePrefersReducedMotion();
  const [phrase, setPhrase] = useState(0);
  const [count, setCount] = useState(0);
  const [deleting, setDeleting] = useState(false);
  const current = phrases[phrase] ?? "";
  const loop = phrases.length > 1;
  const done = !loop && count >= current.length;

  useEffect(() => {
    if (reduced || done) return;
    const atEnd = !deleting && count >= current.length;
    const atStart = deleting && count === 0;
    const id = setTimeout(
      () => {
        if (atEnd) setDeleting(true);
        else if (atStart) {
          setDeleting(false);
          setPhrase((p) => (p + 1) % phrases.length);
        } else setCount((c) => c + (deleting ? -1 : 1));
      },
      atEnd ? hold : deleting ? speed / 2 : speed,
    );
    return () => clearTimeout(id);
  }, [reduced, done, deleting, count, current.length, hold, speed, phrases.length]);

  const longest = phrases.reduce((a, b) => (b.length > a.length ? b : a), "");
  const shown = reduced ? current : current.slice(0, count);
  return (
    <span ref={ref} className={cn("ui-typewriter", className)} {...props}>
