  format?: Intl.NumberFormatOptions;
  /** Overrides the provider locale. */
  locale?: string;
  /** Duration in ms. Default 900. */
  duration?: number;
  /** Wait until the number scrolls into view before counting. Default `true`. */
  startOnView?: boolean;
