/** Picks the closest built-in catalog for a locale, falling back to English. */
export function getMessages(locale: string | undefined): Messages {
  if (!locale) return en;
  return builtInMessages[locale] ?? builtInMessages[locale.split("-")[0] ?? ""] ?? en;
